SELECT 'all 51 creatures are in' AS assertion, count(*) AS got, 51 AS want
  FROM creatures WHERE slug IN ('adna-nomad', 'akysse-tribal-hunter', 'amana', 'arac', 'auto-g', 'aviane', 'bayou-ursine', 'blucie', 'bruutasaur', 'butter-troll', 'chasseur-vert', 'crab-warrior', 'deer-horn-tribesman', 'dewtani', 'dirari-ecto-man', 'dnorr-devilman', 'dramin', 'drizzit', 'feni-nomad', 'fingertooth-carpetbagger', 'flooper', 'forest-warden', 'ganka', 'idie-swamp-man', 'iktek-digger', 'krak', 'larmac', 'loak', 'loronoid', 'lyvorrk', 'malvoren', 'mraghiile-tree-man', 'nreta', 'nuhr-dwarf', 'obsedai', 'phlebus', 'posluznik', 'roane-piper', 'septumbran-witch-wolf', 'shale-bogle', 'shaper', 'shemarrian-warrior', 'slurmph', 'spinne', 'squilb', 'swamp-sludger', 'vernulian', 'vintex-warrior', 'tokanii', 'simvan-monster-rider', 'psi-x-alien');
SELECT 'and 51 of them are playable' AS assertion, count(*) AS got, 51 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('adna-nomad', 'akysse-tribal-hunter', 'amana', 'arac', 'auto-g', 'aviane', 'bayou-ursine', 'blucie', 'bruutasaur', 'butter-troll', 'chasseur-vert', 'crab-warrior', 'deer-horn-tribesman', 'dewtani', 'dirari-ecto-man', 'dnorr-devilman', 'dramin', 'drizzit', 'feni-nomad', 'fingertooth-carpetbagger', 'flooper', 'forest-warden', 'ganka', 'idie-swamp-man', 'iktek-digger', 'krak', 'larmac', 'loak', 'loronoid', 'lyvorrk', 'malvoren', 'mraghiile-tree-man', 'nreta', 'nuhr-dwarf', 'obsedai', 'phlebus', 'posluznik', 'roane-piper', 'septumbran-witch-wolf', 'shale-bogle', 'shaper', 'shemarrian-warrior', 'slurmph', 'spinne', 'squilb', 'swamp-sludger', 'vernulian', 'vintex-warrior', 'tokanii', 'simvan-monster-rider', 'psi-x-alien');
SELECT 'the creatures carry 75 attacks' AS assertion, count(*) AS got, 75 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('adna-nomad', 'akysse-tribal-hunter', 'amana', 'arac', 'auto-g', 'aviane', 'bayou-ursine', 'blucie', 'bruutasaur', 'butter-troll', 'chasseur-vert', 'crab-warrior', 'deer-horn-tribesman', 'dewtani', 'dirari-ecto-man', 'dnorr-devilman', 'dramin', 'drizzit', 'feni-nomad', 'fingertooth-carpetbagger', 'flooper', 'forest-warden', 'ganka', 'idie-swamp-man', 'iktek-digger', 'krak', 'larmac', 'loak', 'loronoid', 'lyvorrk', 'malvoren', 'mraghiile-tree-man', 'nreta', 'nuhr-dwarf', 'obsedai', 'phlebus', 'posluznik', 'roane-piper', 'septumbran-witch-wolf', 'shale-bogle', 'shaper', 'shemarrian-warrior', 'slurmph', 'spinne', 'squilb', 'swamp-sludger', 'vernulian', 'vintex-warrior', 'tokanii', 'simvan-monster-rider', 'psi-x-alien');

