INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('adna-nomad', 'Adna Nomad', 'humanoid', 'rifts', 1, 'Any, but tend to be Principled (25%), Scrupulous (30%), Unprincipled (20%) or Anarchist (10%)', '{"IQ":"3D6+5","ME":"3D6+5","MA":"3D6+7","PS":"3D6","PP":"2D6+3","PE":"2D6+3","PB":"2D6+1","Spd":"3D6"}', NULL, NULL, 'PE+6D6', '2D6', 'ME+2D6', 'M.D.C. is the P.E. number plus 6D6, +2D4 per level of experience. I.S.P. is the M.E. number plus 2D6, +1D6 per level. No Hit Points or S.D.C. are printed (a Mega-Damage being). P.S. is ordinary: physical attacks do S.D.C. damage. Horror Factor: not applicable.', NULL, NULL, NULL, '+3 to Perception Rolls, +2 to save vs disease, +2 to save vs possession, +3 to save vs heat and cold; all in addition to attribute and skill bonuses. Attacks per melee as per the O.C.C.''s Hand to Hand skill (few have better than Basic); damage as per combat skill and P.S., S.D.C. only. Vulnerabilities: -2 to save vs magic, and no P.E. or O.C.C. bonus to save vs magic applies; 98% carry the Long Death, a genetic disease that sterilizes and then kills.', 'Special skill, Lore: Traversing the Megaverse, 50% +3% per level of experience (the dimension-traveling races and the common means of dimensional travel; an Adna cannot open a Rift itself). Other skills as per O.C.C.', 'Clever, resourceful and quick to adapt. Not physically mature until 21. A healthy female can bear a single child about once every four years, after an 18 month pregnancy. Most pair for life, and a widowed Adna wanders alone afterward.', 'None; the Adna avoid magic', 'Minor Psychic, all of them: Resist Thirst (6), Resist Fatigue (4), Summon Inner Strength (4) and Presence Sense (4).', '8-9 feet (2.4 to 2.7 m) tall', '300 to 500 pounds (135 to 225 kg)', '4D6+90 years; ancestors lived to 220', 'Anywhere a human can live, but they favor quiet wilderness. A small community lives in the Appalachian Mountains and a dozen or more are in eastern Europe looking for Gene-Splicers.', 'Humans and most D-Bees; especially Kraks, Larmac, Fennodi, Bubblemakers and Grackle Tooth, and happy, simple-living folk such as most Idie Swamp Men and some Bayou Ursines', 'The Splugorth and their minions first, then the Naruni and Kreeghor; warmongers, destroyers and slavers generally. Horune Pirates think drinking Adna blood brings wisdom and visions of the future', 'Takes an O.C.C.: any Adventurer class, with Rogue Scholar, Rogue Scientist, Wilderness Scout and a schooled Vagabond the favorites; never a Men of Arms or Magic occupation. NPCs are level 1D8+5; player characters start at level one or two. The race''s own gear replaces the O.C.C.''s: L-20 Pulse Rifle or similar, an energy sidearm, 1D4+2 spare E-Clips per weapon, Vibro-Knife (1D6 M.D.) or Neural-Mace, light M.D. body armor (35 M.D.C.), travel and camp gear, plus 1D6+1 items of the O.C.C. Money is the O.C.C.''s plus 1D6x1,000 credits and 4D6x1,000 credits of trade goods. No cybernetics to start. Slave market value: as a psychic human.', 'Among the rarest D-Bees in North America: gentle, very tall and thin nomads with salmon-pink skin, arms long enough to hang below the knee, a two-foot head with nostril slits and big dark gray eyes. Nearly the whole race is dying of an inherited illness, which most face with calm good humor, and they wander the eastern wilderness as peaceful explorers whom even barbarians tend to leave alone. Also called the Quiet Wanderers and End Men.', 'Rifts World Book 30: D-Bees of North America p.11-13'),
('akysse-tribal-hunter', 'Akysse Tribal Hunter', 'humanoid', 'rifts', 1, 'Any, but typically Unprincipled, Anarchist or Aberrant', '{"IQ":"2D6+4","ME":"2D6+2","MA":"2D6+2","PS":"3D6+6","PP":"2D6+8","PE":"2D6+8","PB":"2D6","Spd":"3D6+4"}', 'PE', '1D4x10+8', NULL, '4D6', NULL, 'Hit Points are the P.E. number plus 1D8 per level of experience. Base S.D.C. is 1D4x10+8. No M.D.C. of its own (hide armor, below). P.P.E. 4D6 but never used for magic. I.S.P. is not printed (psionics as for a human). Horror Factor: not applicable.', NULL, NULL, '{"initiative":3,"strike":1,"parry":1,"dodge":2}', '+1 to Perception Rolls and +3 to save vs disease, heat and cold; all in addition to attribute and skill bonuses. Attacks per melee as per the O.C.C.''s Hand to Hand skill; damage as per combat skill, and every kick does double normal damage. Vulnerabilities: without surprise, and above all in towns or in captivity, -3 to save vs Horror Factor, -1 on initiative, -2 to strike, parry and dodge, and -2 to roll with punch.', 'As per O.C.C., but no tech-related skills (Engineering, Electrical, Mechanical, Science); those are swapped for Domestic, Horsemanship, Physical, Rogue, Ancient W.P., Wilderness and fitting Technical skills such as Lore. Speaks Gobblely, and most speak basic American.', 'Nightvision 90 feet (27.4 m). Sight and smell are about human; hearing is sharp enough to catch a heartbeat 12 feet (3.6 m) off. Mature by 15; a female carries one or two young for eight months. Most pair for life.', 'None; never practiced, not understood and somewhat feared', 'Same chance of psionics as a human', '5 to 6 feet (1.5 to 1.8 m) tall', '100-200 pounds (45 to 90 kg)', '2D6+50 years', 'Temperate forest, low mountains and swamp along the East Coast, mostly the Southeast (old Virginia, the Carolinas, Georgia and Florida), going farther north only in summer. Family clans of 5 to 500, seldom over 100; a clan of 3,000+ is rumored. Fewer than 15,000 in all.', 'Only other Akysse of the same family clan are trusted. Exiles and rogues get on with humans and D-Bees without fully trusting them. Psi-Goblins, Goblins and Orcs are generally accepted', 'Tech-invaders (anyone using modern technology or Techno-Wizard machines); other tribal peoples are rivals; the Splugorth and their minions are hated most. Shemarrians are distrusted and avoided', 'Takes an O.C.C.: a tribal Akysse is a Barbarian class (the Wild Knives Warrior above all), Wilderness Scout, Swamp Stomper, Dinosaur Hunter or Vagabond. One raised away from the tribe may learn any O.C.C. it qualifies for and is treated as a traitor by its own people. Juicer and M.O.M. (Crazy) conversion do not work on the race; cyborg or Cyber-Knight is possible but unheard of. NPCs are level 1D4+3; player characters start at level one. The race''s own gear replaces the O.C.C.''s: a makeshift Vibro-Spear (1D6, 2D4 or 2D6 M.D.), Vibro-Knife (1D6 M.D.), survival knife, patchwork Fury Beetle or dinosaur hide armor of 4D6+28 M.D.C. and camp gear; never guns, computers, tech armor or vehicles. Money is 1D6x1,000 credits of trade goods. No cybernetics. Slave market value: twice an average human.', 'Orange-skinned tribal hunters with backward-jointed legs, three-fingered hands, a short tapir-like snout, pig-like ears and a red-striped bony crest (the klawen) that sheds body heat. They follow big game up and down the eastern seaboard in loincloths and hide armor, shun technology apart from Vibro-Blades, loathe slavery, and fight outsiders only when threatened or when someone settles on their range. Also called Red Capped Wild Men and Pig Barbarians.', 'Rifts World Book 30: D-Bees of North America p.13-15'),
('amana', 'Amana', 'humanoid', 'rifts', 1, 'Typically good: Principled (55%) or Scrupulous (35%), 10% other (typically Unprincipled)', '{"IQ":"3D4+4","ME":"3D4+4","MA":"3D4+2","PS":"3D4+2","PP":"3D4+6","PE":"3D4+6","PB":"3D4+8","Spd":"3D4+4"}', NULL, NULL, 'PE+3D4', 'PE+2D4x10', 'ME', 'M.D.C. is the P.E. number +3D4, plus 1D4 per level of experience. P.P.E. is the P.E. number +2D4x10, plus 4D4 per level; more can be drawn from ley lines and nexus points as a Ley Line Walker does, but not from living creatures. I.S.P. is the M.E. number plus 2D4 per level of experience. Horror Factor: not applicable.', NULL, NULL, NULL, '+2 on Perception Rolls, +4 to save vs Horror Factor, +2 to save vs Necromancy or Spoiling Magic, +2 to save vs mind control and possession, +4 to save vs Bio-Wizardry, symbiotes and parasites. A vampire''s bite does physical damage only, and an Amana cannot be made undead. Attacks per melee as per Hand to Hand skill; damage as per combat skill and attributes. Vulnerabilities: none per se.', 'R.C.C. skills: Language: Native Tongue (typically American or Spanish, +15%), Language: Other, one of choice (+15%), Literacy: Native Tongue (+20%), Literacy: Other, one of choice (+15%), Biology (+20%), Chemistry (+15%), Medical Doctor (+25%), Pathology (+20%), two Domestic of choice (+10%). Hand to Hand: none, but Basic costs one R.C.C. Related Skill and Expert four. Six R.C.C. Related Skills, plus one at levels 3, 6, 9, 12 and 15; four Secondary Skills, plus one at levels 4, 8 and 12.', 'Mature at 17; one child after a 12 month term. Natural Empathy: always on and free, the same as the Sensitive power of Empathy. Super-Healing (two melee actions, bare touch, a calm patient): each 6 P.P.E. restores 4D4+6 Hit Points or S.D.C., or 1D4 M.D.C. to an M.D.C. being, in 1D4 seconds and without scars; a broken bone costs 10 P.P.E. and gives back 4D4+6 Hit Points; 32 P.P.E. cures most disease and physical affliction (not curses, insanity, birth defects or magical ailments), with only a 01-33% chance against a genetic disease and never a second try. Regrow Lost Limbs: 2D4 minutes and 1D6x10+40 P.P.E.; the limb grows back over 4D4 days while the patient rests four weeks (01-80% chance of failure if too active), and the healer is without that P.P.E. until it is done and at -25% to attributes and bonuses for four weeks. A limb hurt within 96 hours and still partly attached costs 1D4x10+8 P.P.E. and rejoins at once, with a 01-40% chance of a dead limb unless the arm is rested 24 hours. Resurrection: a body dead six weeks or less with 70% remaining returns with full S.D.C. and 2D4 Hit Points (or M.D.C.) and recovers in 3D4 days; it costs the healer 80% of total P.P.E. and 4D4+4 M.D.C. until the patient recovers, and the healer must save vs Coma/Death or lie in a coma, rolling again every 12 hours for two days. No power works on the undead or the non-living; used on itself, each costs half the P.P.E. Aura of Life: 10 P.P.E. per melee round for a white aura of 4 feet (1.2 m) radius, +4 feet (1.2 m) at levels 2, 4, 8, 12 and 16, which wards off demons and undead as a holy symbol does (Horror Factor 15, no damage), repels evil Entities and ghosts, and gives allies inside it +2 on saves vs disease, possession and mind control, +4 on saves vs Horror Factor, and 1D4 S.D.C. healed per melee round. Touch of Life: see attacks.', 'None; they are born healers', 'Major Psychic: Induce Sleep (4), Mind Block (4), Presence Sense (4), Sense Evil (2), plus four powers of choice from the Healer category.', '6-7 feet (1.8 to 2.1 m)', '140-190 pounds (63 to 85.5 kg)', '4D4+180 years, though few die of natural causes', 'Any. A few dozen at Lazlo and New Lazlo, a couple hundred in the Magic Zone, and two or three thousand scattered over the eastern Old Canadian and American Empires, mostly east of the Mississippi; reported in the north, south, southwest and the Vampire Kingdoms. Several thousand more are slaves on Atlantis.', 'Nearly anyone not overtly violent, war-like, aggressive or evil. They suspect the Shemarrians are robots and keep the secret', 'Minions of Splugorth, demons, slavers, Shifters, Necromancers, Witches, Cyber-Snatchers and unscrupulous doctors; they fear the Coalition Army and the Federation of Magic', 'No O.C.C.: a full R.C.C. with its own skills, advancing on the Body Fixer experience table. NPCs are level 1D4+4; player characters start at level one. Starts with a first-aid kit, 10 S.D.C. scalpels, a box of 100 surgical gloves and 50 masks, an apron and disinfectant, traveling and dress clothes, a language translator, a pack or large sack, and food and fresh water for 1D4+1 weeks. Money: 3D4x1,000 credits and 1D4x10,000 credits of tradable items. No cybernetics to start, at most a surgical tool implant. Slave market value: the Splugorth pay 2D6 million credits for a healthy one and resell at triple.', 'Tall, very thin, hairless healers whose glistening pure white skin looks like marble or porcelain, usually dressed in robes and loose gowns. Pacifists sickened by violence, they tend the sick and the poor wherever they are free. The Splugorth conquered their world a thousand years ago; the free Amana of North America descend from several thousand slaves who fled through a Rift during a botched raid, and since the fall of Tolkeen they are hunted as the Resurrection D-Bees.', 'Rifts World Book 30: D-Bees of North America p.18-21'),
('arac', 'A''rac', 'humanoid', 'rifts', 1, 'Any, but tend to be Principled (20%), Scrupulous (30%), Unprincipled (20%) or Anarchist (20%)', '{"IQ":"3D6+8","ME":"3D6","MA":"3D6+6","PS":"3D6+2","PP":"3D6+4","PE":"4D6+2","PB":"2D4+1","Spd":"4D6"}', 'PE+3D6', '1D4x10', NULL, '2D6', NULL, 'Hit Points are 3D6 plus the P.E. number, plus 1D8 per level of experience starting at level one. S.D.C. is 1D4x10, +5 per level from level two, with no S.D.C. from Physical skills. Natural A.R. 13. M.D.C. by armor, force field or magic. P.P.E. is 2D6, or per a magic O.C.C. I.S.P. is not printed (psionics as for a human). P.S. equals Bionic Strength. P.B. 2D4+1 is by human standards (2D6+10 by A''rac standards). No Horror Factor is printed.', 13, NULL, NULL, '+1D4 to Perception Rolls, +2 to save vs Horror Factor, and +1 per level of experience to save vs poison, toxins and disease; all in addition to attribute and skill bonuses. Attacks per melee as per Hand to Hand skill. Physical skills raise P.P. and Spd but never S.D.C., P.S. or P.E.', 'Natural Climb 81% +1% per level (climbing and rappelling alike); balance at a base 50%, or +15% to Acrobatics and Gymnastics. Whatever the O.C.C.: one extra Language: Other at +20%, one extra Science skill at +10%, and +5% to all Science and Technical skills.', 'Eyesight sharp enough to make out a face or a small sign at 1200 feet (366 m), and it takes in infrared and ultraviolet light. Microscopic hairs on the six-fingered hands make it a born climber with fine balance. The skin is an exoskeleton of tiny armored plates (Natural A.R. 13). Resists poison, toxins and disease, and has a venomous bite. Mature by 18; a female lays 1D4 eggs after 8 months, until age 200, and both parents carry the eggs for the 3 months until they hatch.', 'Only by O.C.C., as a human; those who study it lean to Shifter and Temporal Wizard', 'Standard, same as humans', '6-7 feet (1.8 to 2.1 m); tall and lean', '130 to 210 lbs (58.5 to 94.5 kg)', '6D6+260 years', 'Prefers cool, dry climates but is found anywhere, rarely settling for more than a year or two. Fewer than two thousand in the US and Canada, mostly the East and the Magic Zone: about thirty in New Lazlo, four times that in Lazlo, and isolated communities of 4D6x10. Vampires of Mexico drive them off because A''rac blood cannot be drunk.', 'Anyone who loves knowledge, science and exploration: the Aardan Tek, Adna Nomads, Dewtani and N''reta, and often dragons, Mystics, Rogue Scholars, Rogue Scientists and free thinkers', 'The Coalition States, the Federation of Magic, the Splugorth and their minions; wary of Spinne (rivals) and the Chasseur Vert. Many humans take them for monsters or demons. The Horune and Splugorth prize them as slaves', 'Takes an O.C.C.: most often a Scholar and Adventurer class, explorers especially (Pathfinder, Vagabond, Saddle Tramp, Wilderness Scout, and the bulk of the Dinosaur Swamp classes); combat classes are usually avoided, and any magic O.C.C. is open. NPCs are level 2D4; player characters start at level one and use the O.C.C.''s experience table. Equipment and money as per the O.C.C. Tends to avoid cybernetics and bionics. Slave market value: 1D6x10,000 credits as an intelligent slave, half that for the arena or labor.', 'Studious, curious spider people: tall, lean bipeds with deceptively thin limbs, six digits on each hand and foot, a lustrous carapace of minute plates, and a spider''s head with four eyes, two false eyes above them and four toothed mandibles. Carnivores who prefer liquefied meat and blood. They roam the Megaverse collecting knowledge and keeping journals, despise enforced ignorance, and on Rifts Earth gather at Lazlo and New Lazlo.', 'Rifts World Book 30: D-Bees of North America p.25-27'),
('auto-g', 'Auto-G', 'humanoid', 'rifts', 1, 'Any, but professional assassins and spies lean toward Anarchist (35%), Aberrant (30%), Miscreant (10%) and Diabolic (15%)', '{"IQ":"2D6+8","ME":"2D6+8","MA":"3D6","PS":"3D6","PP":"3D6","PE":"2D6+8","PB":"3D6+6","Spd":"3D6"}', 'PE', 'PE+24', NULL, 'PE+2D4x10', 'ME+2D6', 'Hit Points are the P.E. number plus 1D6 per level of experience. S.D.C. is 24 plus the P.E. number, plus any from skills or O.C.C. M.D.C. only while copying a mortal Mega-Damage race; otherwise by armor, force field or magic. P.P.E. is 2D4x10 plus the P.E. number, and falls by 70% for 24 hours after a change into a nonhuman form. I.S.P. is printed twice: the stat block gives the M.E. number +2D6 (stored), the Psionics paragraph the M.E. number plus 4D6; both add 1D6+1 per level. M.E.: roll another 1D6 if the first result is 17 or higher. Figures are for the natural, human-looking form.', NULL, 10, '{"initiative":1,"pull_punch":2}', '+2 to save vs magic (magic illusions included), +3 to save vs disease, +3 to save vs Horror Factor, and +2 to save vs possession at levels 2, 4, 6, 8, 11 and 15. Needs a 12 or higher to save vs psionic attack. A copied D-Bee body may add its own bonuses and natural abilities. Attacks per melee as per Hand to Hand skill, O.C.C. and current body; damage varies with race or weapons. Vulnerabilities: copies only mortal humanoids; cannot cast, learn or draw on magic; hated, feared and distrusted nearly everywhere.', 'As per O.C.C. Keeps its own skills and memories in any form.', 'Senses and abilities are a human''s, except that it heals three times as fast and shrugs off most disease. Mature at 16, with shape-shifting showing by about 7; one child after nine months, fertile to 72. It has two forms only: its own human-looking one (P.B. usually 12 or more, youthful even at 90-110) and whatever it is copying, and leaving a copy always returns it to the human form. To become a member of a race it chews or swallows anything bearing that race''s DNA, a hair or a drop of blood being enough, and one minute (four melee rounds) later it is that race down to the genes, with its size, extra limbs, wings, natural armor, M.D.C. body, strength, psionics and instincts, but never spell casting, learned skills or memories. Only mortal, intelligent humanoids can be copied: no supernatural beings, creatures of magic, animals or the truly alien (blobs, energy beings, stone or plant people). To double one particular person it studies the subject, alive or dead, for 15 minutes or more, eats at least an ounce of tissue and must be within 12 feet (3.6 m) at the change; the match is 99.7 percent, down to prints, voice, scars and DNA. Tattoos, piercings and bionics are not copied. Reverting sheds any implants and regrows missing limbs and organs. Over 40% machine parts kills it. Its P.P.E. cannot be drained by mages, Psi-Stalkers or other P.P.E. vampires. A new body is at once familiar to it. If slain in a copied shape the corpse keeps that shape. A Mind Bond always exposes one; See Aura and casual telepathy seldom do.', 'None; cannot practice magic of any kind', 'Major Psychic: Alter Aura (2), Death Trance (1), Mask P.P.E. (4), Mask I.S.P. & Psionics (7), Mind Block (4), Nightvision (4) and Summon Inner Strength (4).', 'Human in its natural form; otherwise that of the being copied', 'Human in its natural form; otherwise that of the being copied', '6D6+134 years', 'Wherever a human, or the race being impersonated, lives. Thought to originate in North America, perhaps the Devil''s Gate (St. Louis) or a Rift in the ruins of Old Chicago; once mainly the Mid-West. Believed to number 200 to 600 across North America.', 'Nobody in particular; only their own kind are truly trusted. Criminal ones work with like-minded evildoers and power-brokers; some are rumored to serve the Federation of Magic, and Tolkeen hired some', 'Feared by all and usually killed on discovery. The Coalition States above all (it has an enzyme test for them); Splugorth Slavers trade in them and Splugorth minions kill them on sight', 'Takes an O.C.C.: any in theory. Favorites are Bounty Hunter and other man-hunters, Merc Soldier, Sheriff, Gunslinger, Gunfighter, Con Artist, Smuggler, Highway Man, Bandit, Professional Thief, Super-Spy, Freelance Spy and Master Assassin; the less violent few take a Scholar and Adventurer class. Barred: any O.C.C. that artificially augments the body (Cyber-Knight and Headhunter included) and every Practitioner of Magic or Psychic O.C.C. NPCs are level 1D8 and player characters begin at first level, both on the O.C.C.''s experience table. Equipment and money as per O.C.C. Cybernetics are avoided and never pass 40% of the body. Slave market value: 1D6x100,000 credits.', 'A rare, feared shape-changer named for auto-genetic: it rewrites its own genes to become a true member of another humanoid race, or the exact double of one person. In its own shape it looks like an attractive human and insists that it is one. Hunted for generations by the Coalition, which found one among the would-be assassins of Emperor Prosek in 106 P.A., most are cold or resentful, and many live as spies, thieves and killers. Few people have heard of them and fewer still believe they exist.', 'Rifts World Book 30: D-Bees of North America p.27-31'),
('aviane', 'Aviane', 'humanoid', 'rifts', 1, 'Any, but lean toward good', '{"IQ":"3D6","ME":"2D6+6","MA":"2D6","PS":"3D6+6","PP":"4D6+6","PE":"2D6+10","PB":"4D6","Spd":"2D6"}', 'PE', '5D6+18', NULL, 'PE+2D6', NULL, 'Hit Points are the P.E. number plus 2D6 per level of experience. S.D.C. 5D6+18 is the main body; each wing has 4D6+60, +2D6 per level. M.D.C. by armor, magic, psionics or force field. P.P.E. is the P.E. number plus 2D6, added to the base P.P.E. of a magic O.C.C. I.S.P. is not printed (psionics as for a human). P.S. is Augmented. P.B. 4D6 is the male''s; a female rolls 3D6. Spd 2D6 is running; flying is 2D6x10+60 (80 to 180, 56-124 mph / 89.6 to 198 km). The 11 is printed as Awe/Horror Factor.', NULL, 11, '{"attacks":1,"roll":2,"pull_punch":2}', '+2 on Perception Rolls; in flight, +2 on initiative and +2 to automatic dodge (no melee action used); all in addition to attribute and skill bonuses. The +1 attack is one extra attack or action per melee on top of Hand to Hand skill. Augmented P.S. as a Juicer or cyborg: a Power Punch may do M.D. but counts as two attacks. Vulnerabilities: night vision about half a human''s, so many will not fly at night; falls do 50% more damage and break a bone unless it rolls with impact and beats a 14.', 'As per O.C.C. Cannot pilot robots or power armor.', 'Eyes like an eagle''s pick out a rabbit or a signpost at two miles (3.2 km). Holds its breath 1D6+6 minutes. Fine balance and an inner gyroscope tell it its attitude, magnetic north and how near the ground and obstacles are, even at top speed, so it stops, turns and dodges precisely. Polarized Vision: glare and bright light do nothing, and Blinding Flash has half its penalties for half as long. Winged Flight: glides and flies for hours below two-thirds of top speed, for half the P.E. number in hours at cruising speed and half that again at top speed or anything above cruising (P.E. 15 gives seven and a half hours, or three hours 45 minutes). Ceiling 11,000 feet (3,353 m). Speed-Burst Flying: double top speed for P.E. minutes, or triple for P.E. seconds, then 1D6 minutes of rest before exceeding half speed. Wing Regeneration: 2D6 S.D.C. per 24 hours; a half-destroyed wing takes 4D6+12 days and a lost wing 6D6+45 days. M.D. energy blasts mostly pass through a wing, so each 1D6 M.D. does 1D6 S.D.C. to it; S.D.C. bullets and blasts at the wings do 10%, and fire balls and fiery blasts half.', 'None, unless a magic O.C.C. is taken', 'Same probability of psionics as humans', '4-5 feet (1.2 to 1.5 m) tall', '120-160 pounds (54 to 72 kg)', '2D6+76 years', 'Chiefly the mountains and canyons of the West, the Rockies above all, with a flock of 839 in and around Arzno; anywhere there is room to fly. Not known outside North America.', 'The Lyn-Srial and most residents of Arzno', 'Mostly the Coalition and other human supremacists; wary of humans in general until trust is earned', 'Takes an O.C.C.: the usual ones are Wilderness Scout, Vagabond, Merc Soldier and Rogue Scholar. Vehicle-heavy classes are shunned and robots and power armor cannot be piloted. About 5% take up magic, leaning to Mystic, Ley Line Walker, or a Warlock of Air or Fire. M.O.M. and Juicer augmentation do not work; a few in Arzno are Momano Headhunters with TW bionics. NPCs are level 1D4+2; player characters start at level one. Equipment and money as per O.C.C., limited to light or medium armor that can be flown in: patchwork armor is typically 3D6+30 M.D.C., and Arzno''s Techno-Wizard flyer armor typically 60 M.D.C. or carries Armor of Ithan. No cybernetics to start. Slave market value: two or three times a human slave.', 'Winged humanoids a little smaller than a man, feathered over the head, neck, upper arms and back; males are brightly colored in blues or reds and females tan and grey. Refugees from a dying world of peaks and canyons, they settled the western mountains of North America. Sociable, curious and often too trusting, they love to fly, hunt and play, and avoid Coalition territory, where they are shot on sight. Also called Avian Men and Bird Men.', 'Rifts World Book 30: D-Bees of North America p.31-33'),
('bayou-ursine', 'Bayou Ursine', 'humanoid', 'rifts', 1, 'Any, but most are Unprincipled (15%), Anarchist (45%) or Miscreant (30%)', '{"IQ":"3D6","ME":"2D6+4","MA":"2D6+4","PS":"3D6+10","PP":"3D6","PE":"2D6+6","PB":"2D6+3","Spd":"3D6"}', 'PE', '1D6x100+100', NULL, '3D6', NULL, 'Hit Points are the P.E. number plus 1D10 per level of experience. S.D.C. is 1D6x100+100, which makes it an extremely light Mega-Damage creature (equivalent M.D.C. of 2-7). I.S.P. is not printed (psionics as for a human). P.S. is Augmented. Spd is doubled swimming in or under water. Horror Factor: not applicable.', NULL, NULL, '{"dodge":1,"pull_punch":1}', 'The two bonuses are in addition to those from attributes and skills. Attacks per melee as per Hand to Hand skill; damage as per combat skill. Augmented P.S. as a Juicer or cyborg: a power punch does Mega-Damage but counts as two attacks. Vulnerabilities: none per se, beyond the racial prejudice against them.', 'Natural swimmer, 92% skill equivalent. Other skills as per O.C.C.', 'Six eyes take in infrared and ultraviolet light, with Nightvision 120 feet (36.6 m). Four ears: one pair for the human range, one for ultrasonic sound. Amphibious, breathing air and water alike. Oily fur insulates it in the water and cools it on land.', 'None', 'Same chance of psionic abilities as a human', '4 to 6 feet (1.2 to 1.8 m) tall', '120 to 300 pounds (54 to 135 kg)', '2D6+60 years', 'Forests, swamps, bayous and river deltas and small offshore islands, from the Ohio River Valley to the north bank of the Rio Grande, and the Caribbean islands; almost never desert or arctic. Commonest in the Deep South (old Louisiana and Mississippi). About 250,000, with perhaps 15,000 more elsewhere on the continent.', 'Their own kind and any race that treats them fairly; Grackle Tooth, Kraks and Larmac; pirates, bandits and outlaw bands of the Southeast. Most would side with the Crulls in Louisiana. Common crew on Horune Pirate ships', 'Anyone in their way or out to get them, judged case by case; they avoid the Coalition as D-Bee haters', 'Takes an O.C.C. from a fixed list. Men of Arms: Bandit, Highway Man, Bounty Hunter, Coalition Grunt (equivalent), Head Hunter (not Momano), Mercenary Soldier, Pecos Raider, Merchant Marine, Privateer, Pirate, River Pirate, Pirate Slaver, and rarely Combat Cyborg, Psi-Slinger or (very rarely) Maxi-Juicer. Adventurers: City Rat (not Hack Rat), Cyber-Snatcher, Operator, Saddle Tramp, Professional Gambler, Salvage Expert, Saloon Bum, Trapper-Woodsman, Storyteller, Vagabond, Wilderness Scout (not Naturalist or Legacy Scout). Psychics: Burster, Mind Melter, Psi-Slinger. No Juicer or Crazy conversion other than Maxi-Juicer. NPCs are level 1D4; player characters start at level one. Equipment, money and cybernetics as per O.C.C. Slave market value: 3D4x1,000 credits.', 'Short, bear-like humanoids with shaggy white, black and brown fur, six eyes, four ears and a pair of bushy fox tails. Cheerful but work-shy, they live by hunting, fishing and scavenging in the swamps of the Deep South, and roughly eight in ten turn to piracy or banditry, which has earned the whole race a bad name there. They have no language or culture of their own and remember no homeworld. Also called Bandit Bears, Bayou Bears, Six-Eyed Bear Men and Pirate Bears.', 'Rifts World Book 30: D-Bees of North America p.33-35'),
('blucie', 'Blucies', 'humanoid', 'rifts', 1, 'Any, but they lean toward Principled (20%), Scrupulous (30%), Unprincipled (20%) and Aberrant (15%)', '{"IQ":"2D6+5","ME":"2D6+5","MA":"3D6+4","PS":"4D6+12","PP":"3D6","PE":"4D6+4","PB":"3D6","Spd":"3D6"}', 'PEx10+2D6', '2D4x10+40', NULL, 'PE+6D6', NULL, 'Hit Points are the P.E. number x10, plus 2D6 per level of experience (the formula rolls level one). M.D.C. by armor or magic only. The P.P.E. figure is added to the base P.P.E. of a magic O.C.C. when one is taken. P.S. is Augmented. Spd is doubled underwater.', NULL, 13, '{"strike":1,"parry":1,"dodge":1,"pull_punch":3,"disarm":2}', '+5 to save vs poison, +3 to save vs Horror Factor, +1 to Perception Rolls; the disarm bonus may be used with the tail. All in addition to attribute and skill bonuses. Attacks per melee as per the Hand to Hand skill of the O.C.C. Damage as per combat skill; a whipping tail slash does punch damage and cannot be a power strike. Vulnerability, heat: above 80 degrees Fahrenheit (26.7 C) with no water nearby to cool off in, Spd and combat bonuses are halved; above 100 degrees Fahrenheit (37.8 C) ALL bonuses are lost, all combat rolls are at -4 and attacks per melee are halved. Dehydrates at twice the human rate in warm weather.', 'Natural aptitudes, in addition to any O.C.C.: Swimming 88%, Land Navigation 80%, and speaks American and its Native Language at 88% +1% per level of experience.', 'Holds its breath underwater for as many minutes as its P.E. number, swims with webbed hands and feet and a rudder-like tail, and sees perfectly underwater behind a clear protective eyelid. Hears and speaks in an ultra-low range most humans cannot hear; with it two or more can talk across half a mile (0.8 km), twice that underwater. Digests anything organic, spoiled or poisonous to humans included, and resists most poisons. Cold attacks do half damage; a natural antifreeze means -50 degrees Fahrenheit (-46 C) costs it nothing, and cold twice that severe only half the usual penalties.', 'Only by a magic O.C.C. About 10% are Water or Earth Warlocks or Elemental Fusionists, and some are Inuit-type Shamans.', 'Standard; the same chance as a human.', '6-8 feet (1.8 to 2.4 m) tall', '200 to 400 pounds (90 to 180 kg)', '3D6+80 years; mature by 15, twins after an 11 month gestation, infertile by 42', 'Anywhere cold and wintery, but known only in North America: the Great Lakes region, Eastern and Northern Canada, Greenland, Alaska and the American Northeast.', 'Others close to nature who live with honor: Native Americans, Sasquatch, Shemarrians, Amana and Cyber-Knights.', 'Minions of Splugorth, Coalition and Free Quebec soldiers, and anyone without honor; demons, monsters and evildoers generally.', 'Takes an O.C.C.: in theory any that does not depend on mechanical or chemical augmentation or on working with technology. The usual choices, by kind - wilderness: Wilderness Scout (any), Swamp Stomper, Trapper-Woodsman, Tundra Ranger; fighting: Merc Soldier, Cyber-Knight, Justice Ranger; learning and wandering: Vagabond, Rogue Scholar; magic and psionics: Earth Warlock, Water Warlock, Inuit Shaman (equivalent), Psi-Druid, and Elemental Fusionist (likeliest pairing Water with Fire). No cybernetics or bionics (incompatible physiology). Equipment and money as per O.C.C.; favors heavy energy weapons and blunt weapons, magic and Techno-Wizard ones above all. Player characters start at level one; NPCs are level 1D6+3. Slave market value 4D6x1,000 credits in cold markets, 1D6x1,000 in warm ones, nothing in hot ones.', 'Tall blue-scaled reptilian D-Bees with a crocodile-like head, bony brow ridges, ear membranes and a long tapering tail, also called Blue Cannibals, Blue Crocs and Snow Lizard Men. Warm-blooded and live-bearing despite their looks. They arrived through a Rift early in the Dark Age and are known for a strict code of honor and for defending their neighbors.', 'Rifts World Book 30: D-Bees of North America p.35-37'),
('bruutasaur', 'Bruutasaur', 'humanoid', 'rifts', 1, 'Any, but most are Anarchist (30%), Miscreant (30%) or Aberrant (20%)', '{"IQ":"1D6+5","ME":"4D6","MA":"2D6","PS":"4D6+6","PP":"4D6","PE":"3D6+10","PB":"2D4+4","Spd":"3D6+18"}', NULL, NULL, '2D6x10+PE', '3D6', NULL, 'M.D.C. is 2D6x10 plus the P.E. number to start, +10 M.D.C. per level of experience. P.S. is Robotic. Runs at twice its Spd in bursts of 1D4 minutes. Cold-blooded.', NULL, 13, '{"initiative":1,"strike":2,"parry":1,"dodge":1,"disarm":1,"pull_punch":3,"roll":2}', '+2 attacks per melee round on top of the Hand to Hand skill and any from Physical skills. +3 to save vs Horror Factor, +6 to save vs vampire charm and control; a vampire''s bite does not affect it. All in addition to attribute and skill bonuses. Punches, kicks and tail strikes do Robot P.S. damage; the tail strikes with half the usual strike bonus, even at a target behind or beside it. Vulnerabilities: at 45 degrees Fahrenheit or colder it loses one attack and its initiative bonus; in extreme cold, or after more than 36 hours of cold, attacks, all bonuses, Spd and skills are halved, and below freezing it takes 2D6 M.D. every 12 hours even in furs. Cold attacks do normal damage. Lacks the patience for civilized behavior or complex skills. Widely feared as a man-eater.', 'R.C.C. skills: Spanish (adopted native tongue) 92%, Language: American (+10%), Appraise Goods (+15%), Barter (+12%), Climbing (+30%), Hunting, Land Navigation (+20%), Recognize Weapon Quality (+20%), Spelunking (+20%), Swimming (+10%), Track (people; +10%), Track & Trap Animals (+20%), Wilderness Survival (+20%), W.P. Ancient (3 of choice), W.P. Modern (4 of choice), Hand to Hand: Basic (Expert for one R.C.C. Related Skill, Martial Arts or Commando for two). Five R.C.C. Related Skills, plus one more at levels 2, 4, 8, 10, 12 and 14; two Secondary Skills at levels 1, 4, 8 and 12.', 'An alert hunter with quick reflexes and a sense of smell three times as keen as a human''s. Nightvision 500 feet (152 m). Runs six hours before tiring and leaps 10 feet (3 m), and a further foot (0.3 m) for each P.S. point. Heals at double speed and regrows a lost tail, hand or finger over 2D4+8 weeks. Eats raw or spoiled meat, carrion, blood and bone safely. A polarizing film and a clear protective lid cover the eyes against glare, sand and grit. Pinning Leap: uses three attacks, and a target under 20 feet (6.1 m) tall is knocked down 01-68% of the time, losing initiative and two attacks; a downed target is pinned 01-35% of the time, helpless while it is bitten or just held, with a new roll each melee round, and the Bruutasaur has initiative when it lets go. Prehensile Tail: 1D6+9 feet (3 to 4.6 m) long with the same Robot P.S.; it swats, trips, grabs, holds or throws a man-sized foe and helps in climbing, but cannot work a weapon.', 'None; never studies magic, but values magic weapons and Techno-Wizard devices.', 'None, but a high M.E. makes it resistant to psionic attack.', '10-12 feet (3 to 3.6 m) tall', '850-1200 pounds (382.5 to 540 kg)', '2D6+40 years; mature by 14, 1D4 live young after an 11 month pregnancy, as often as every 20 months', 'Warm climates: Arizona, New Mexico, Utah, Texas and Northern Mexico. In summer one may roam 1500 miles (2400 km) or more. A few hundred live in the Deep South and Dinosaur Swamp, and some are thought to have reached Central America.', 'Other fighters and reptilian peoples: Brodkil, Gargoyles, Gurgoyles, Greot Hunters, Larmac, Lyvorrk, Grackle Tooth and humans. Respects Cyber-Knights, Juicers, Crazies and Lyn-Srial, and takes in anyone who proves loyal to the tribe.', 'Simvan, in a feud more than a century old; vampires and all undead, which it actively hunts. The Coalition States are a rival and favorite target, respected rather than hated.', 'A full R.C.C. with its own skills, on the Psi-Stalker experience table; no other O.C.C. is offered. Player characters start at level one; NPCs are level 1D10. Travels light: backpack or satchel, ammo belt, air filter, two canteens, 1D4 large sacks, a week of rations, 1D4+4 wooden stakes and a mallet, a two foot (0.6 m) wooden cross, 1D4+4 E-Clips or ammo cartridges (72 silver bullets if it has an S.D.C. gun). No magic or Techno-Wizard gear to start. May wear custom armor: patchwork 5D6+55 M.D.C., medium full-body 1D4x10+80, heavy 1D6x10+140. Money 1D6x1,000 credits plus 2D4x1,000 in trade goods. Slave market value 2D4x10,000 credits.', 'Huge cold-blooded reptilian humanoids, also called Dinosaur Men and the Great Lizards: tan scales with green accents, machete-sized claws, a long prehensile tail and a spiny, horned-toad head. Stone Age tribal hunters brought to Earth by a Dark Age Shifter, they now roam as packs of hunters, raiders and mercenaries. Reprinted from Rifts World Book One: Vampire Kingdoms.', 'Rifts World Book 30: D-Bees of North America p.37-40'),
('butter-troll', 'Butter Trolls', 'humanoid', 'rifts', 1, 'Any, but usually Unprincipled (20%), Anarchist (60%) or Miscreant (10%)', '{"IQ":"3D6+2","ME":"2D6+2","MA":"2D6","PS":"2D6+6","PP":"1D6+6","PE":"1D6+6","PB":"1D6+1","Spd":"1D6+4"}', 'PE+1D6', '30', NULL, '2D6', NULL, 'Hit Points are the P.E. number plus 1D6 per level of experience (the formula rolls level one). M.D.C. by armor only. P.P.E. is 2D6 or by O.C.C. Horror Factor is not applicable.', NULL, NULL, NULL, 'No combat or save bonuses. +5% to Interrogation Techniques and to Cook if either is chosen, and one free Lore skill at +10%. Attacks per melee as per the Hand to Hand skill; damage as per combat skill. Vulnerabilities: none.', 'Every Butter Troll has, whatever its O.C.C., all at +20%: Basic Electronics, Basic Mechanics, Computer Hacking, Computer Operation, Computer Programming, Computer Repair, Jury-Rig, Literacy: Techno-Can or American, Locksmith, Safe-Cracking and Salvage. With an O.C.C. it takes no O.C.C. Related Skills at level one, only the O.C.C. Skills and Secondary Skills; related skills at later levels are gained as usual.', 'A knack for technology, computers above all (see the skills). A thick, oily, butter-yellow sweat coats the body, ten times heavier when it exerts itself, and smells of butter; it makes the troll hard to hold, pin or wrestle, so it slides out of grips, restraints and handcuffs. Most animal predators dislike the smell and the taste.', 'By O.C.C. only.', 'Same chance as a human, but never a Master Psionic.', '5 feet to 5 feet, 6 inches (1.5 to 1.7 m); males a couple of inches taller than females', '230 to 480 pounds (104 to 216 kg)', '3D6+52 years; mature by 18, a single young after a 10 month gestation', 'Urban: the ''Burbs and cities such as Kingsdale, MercTown, Lazlo, New Lazlo and Upper Michigan. Most common in North America but found worldwide, including Atlantis, the New German Republic and among the Warlords of Russia.', 'None as such; gets along with its own kind, City Rats and other technocrats.', 'Looked down on by real monster races as posers. Jealous of attractive, successful humanoids. Gremlins and other creatures that make machines malfunction are its worst enemies.', 'Takes an O.C.C., and only from this list: City Rat, Operator, Robot Pilot, Techno-Wizard, Rogue Scholar, Vagabond, Saloon Bum, Forger, Safecracker, Smuggler, and rarely Headhunter or Rogue Scientist. Fewer than 10% become Techno-Wizards or Rogue Scientists. No cybernetics or bionics to start, but a candidate for any. Equipment and money by O.C.C., plus 2D6x1,000 credits of Black Market goods (computers, video discs, electronics, books). Player characters start at level one; NPCs are level 1D4+1. Slave market value 2D4x2,000 credits.', 'Short, fat D-Bees of unknown origin with big hairy pointed ears, a balding head, a pig-like nose, bad teeth, small claws and pale pockmarked skin, named for their buttery sweat and troll-like looks. Gifted with machines and computers but lazy, self-indulgent and often cowardly.', 'Rifts World Book 30: D-Bees of North America p.40-41'),
('chasseur-vert', 'Chasseur Vert', 'plant', 'rifts', 1, 'Any, but good and selfish alignments predominate', '{"IQ":"2D6+6","ME":"2D6+6","MA":"3D6+6","PS":"3D6+6","PP":"2D6+6","PE":"2D6+6","PB":"3D6","Spd":"3D6"}', 'PE+2D6', '2D6x10', NULL, '1D6', NULL, 'Hit Points are the P.E. number plus 2D6 per level of experience (the formula rolls level one). M.D.C. by armor only. Horror Factor is not applicable.', 12, NULL, '{"strike":2,"roll":1}', '+2 to Perception Rolls in a natural setting; impervious to human diseases. All in addition to attribute and skill bonuses. Attacks per melee as per the Hand to Hand skill of the O.C.C.; damage other than the thorns by hand to hand skill. Vulnerabilities. Ennui: after more than two weeks in a city, -2 to Perception Rolls, -4 on initiative, -2 to all combat rolls and -25% on all skills. Solar powered: needs four hours of natural sunlight a day (eight under a grow lamp); after 48 hours with no light it loses 25% of its Hit Points, then 10% more every 48 hours until dead. Poison vulnerability: -2 to save vs toxic chemicals, pollutants and defoliants; a defoliant spray or gas does 3D6 S.D.C. per blast, immersion 1D6x10 per minute. Diet: five pounds of meat a week or it starves. Fear of blades: double damage from edged and slashing weapons, and facing one it must save vs Horror Factor 10 (14 for Vibro-Blades) or lose initiative and take -2 to all combat rolls.', 'No R.C.C. skills beyond the O.C.C.''s. Natural Prowl 76% +3% per level in vegetation and natural landscapes, halved in an urban or artificial setting.', 'An intelligent carnivorous plant. Water Absorption: takes in water by drinking, from standing water or from humid air, and 1D4 hours of it lasts two days per level. Camouflage: skin color shifts to match natural surroundings; in vegetation it is 90% undetectable when motionless, 70% when creeping no faster than two feet (0.6 m) a melee round, 20% at 6 feet (1.8 m) per round and not at all faster; -60% in a wholly artificial setting, no penalty in parks and gardens. Regeneration: heals at twice the human rate and regrows a limb in 1D4+1 months. Chemical Lure: a pheromone reaching about 2,500 feet (762 m) with the wind; prey failing a save vs non-lethal poison comes looking for the source in a stupor, with half its attacks, -5 on initiative, and -3 on each of strike, parry and dodge (half those penalties, rounded down, for intelligent beings). Sap: a resin from the hands mends broken things or glues down a person or object of up to 300 pounds (135 kg); breaking loose needs a combined P.S. of 25, solvents dissolve it, and one melee round yields enough to stick a man to a tree. Root to Ground: after one melee of rooting into stone, soil or sand (never a man-made surface) only a Supernatural P.S. above its P.E. +1 per level can move it. Poison: a victim of the forearm thorns sickens in 1D4 melee rounds (-2 to all combat bonuses, -10% to skills and speed), then for two hours must save vs lethal poison every ten minutes or lose 2D6 Hit Points.', 'None, unless a magic O.C.C. is selected.', 'Standard; the same chance as a human.', '5 feet to 6 feet, 6 inches (1.6 to 2.5 m) tall', '150 to 190 pounds (68 to 88.5 kg)', '2D6+50 years', 'Humid, deep forest by preference, or any unspoiled wilderness. First recorded in 105 P.A. in central Europe and North America; here it lives in the forests of southern and eastern Canada and east of the Mississippi, Dinosaur Swamp included. Fewer than 2,000 in North America.', 'All free and free-thinking races.', 'The Spinne, its ancient rivals, first of all; also every tyrant and slaver.', 'Takes an O.C.C.; none is barred by name. The military-minded lean to Wilderness Scout, Special Forces, Military Specialist, Merc Soldier, Bandit and the like; artists and thinkers are Rogue Scholars or Vagabonds; Mystics and Ley Line Walkers lead among the magical. No cybernetics or bionics (incompatible physiology). Equipment and money as per O.C.C. Player characters start at level one; NPCs are level 1D4. Slave market value 3D6x1,000 credits.', 'Green Hunters, also called Plant Men and Libertines: broad, strong plant people just under six feet tall with smooth light green skin, tendril hair, glittering eyes and a wide mouth of sharp teeth. Passionate hedonists, artists and campaigners against slavery who hate city life. From the same world as the Spinne Spider People.', 'Rifts World Book 30: D-Bees of North America p.46-48'),
('crab-warrior', 'Crab Warrior', 'humanoid', 'rifts', 1, 'Any, but most are Anarchist (50%) and Miscreant (40%)', '{"IQ":"1D4+3","ME":"2D6+4","MA":"1D6+2","PS":"2D6+18","PP":"1D6+14","PE":"3D6+8","PB":"1D6","Spd":"1D4x10+10"}', NULL, NULL, '2D4x10+32+PE+3D6', '6D6', 'MEx4', 'The M.D.C. formula is the main body (front and underbelly): 2D4x10+32 plus the P.E. number, and 3D6 per level of experience starting at level one. Other locations: feelers (2) 1D4+6 each, horns (2) 20+2D6 each, legs (6) 3D6+24 each, upper arms and shoulders (2) 1D4x10+80 each, pincer claws (2) 1D6x10+100 each, back plate 2D6x10+100. Feelers, horns and legs need a called shot at -4 to strike. I.S.P. is M.E. x4 plus 1D6 per level of experience. Females are +2 to I.Q., M.E. and M.A. P.S. and P.E. are Supernatural. Spd is the same on land and underwater.', NULL, 14, '{"attacks":6,"initiative":5,"strike":3,"parry":3,"dodge":4,"pull_punch":4,"disarm":3,"roll":4}', 'Males have six attacks per round, +1 at levels 3, 6, 9, 12 and 15; females four, +1 at levels 3, 7, 10 and 13. Claws count as Paired Weapons. +2 on initiative in the first melee round when hidden in a sand dome. All in addition to attribute and skill bonuses. Blunt attacks (punch, swat, head butt, body block) do Supernatural P.S. damage. Vulnerabilities: cold attacks do double damage. After more than three weeks out of water it dehydrates: every three days (72 hours) without an hour''s soak costs one point each of P.S., P.P., P.E. and Spd and one point off every bonus, cumulatively; at P.E. zero it falls into a coma and dies in 1D6 days unless immersed for a week (save vs coma and death).', 'R.C.C. skills: Barter (+5%), Camouflage (+20%), Climb (+10%), Dance (+10%), Detect Ambush (+15%), Detect Concealment (+10%), Land Navigation (+15%, undersea too), Language: Native Tongue 96%, Language: Other (usually Spanish or American), Sing (whistling, +15%), Tailing (+10% only in or under water), Wilderness Survival (+20%, underwater too), Sea Holistic Medicine (+15%), Marine Biology (+10%), Undersea Salvage (+10%), Underwater Navigation (+10%). Natural swimmer 75% +1% per level. One R.C.C. Related Skill at levels 1, 4, 8, 12 and 15 (Domestic; Physical: Forced March, Physical Labor, Prowl, Running, Wrestling; Rogue: Cardsharp, Gambling, Gambling Dirty Tricks; Wilderness +5%); one Secondary Skill at levels 3, 6, 9 and 12.', 'Depth tolerance 4000 feet (1219 m); at home in salt or fresh water. Heat and fire do half damage. Sees only about half as far as a human but picks up infrared and sees in dim, murky water. Regenerates 1D6x10 M.D.C. every 24 hours, regrows feelers in 6D6 days and a claw or leg in 1D4+2 months. Hearing: catches a human step at 300 feet (91.5 m) or through a 20 foot (6.1 m) thickness of earth, sand or stone, twice that underwater, so blindness and darkness penalties are cut by 75%. Feelers: a pair of antennae that sense wind, current and temperature shifts at 60% +3% per level and any movement within 50 feet (15.2 m), even behind it; they identify chemicals by taste at 55% and track by taste at 40% (+20% on a blood trail) out to one mile (1.6 km), and each can dodge on its own. Sand dome: digs a pit and banks up wet sand or gravel into a watertight, airtight shelter of 1D4x100 S.D.C. holding 2D4 hours of air.', 'None.', 'Major Psychic: Hydrokinesis (varies), Empathy (4), Telepathy (4), Presence Sense (4), Levitation (varies), Resist Hunger (2), Resist Thirst (6) and Mind Block (4).', '5-6 feet (1.5 to 1.8 m) tall and 10-15 feet (3 to 4.6 m) in diameter; females 10% larger', '700 to 1,200 pounds (315 to 540 kg)', 'Males 3D6+40 years, females 3D6+70 years; mature by 12, 1D6 eggs every spring', 'Sandy or gravel beaches and river banks in warm, tropical and sub-tropical climates, moving into temperate regions for the summer. All along the Gulf Coast and the Caribbean islands; also the coast of Atlantis and the seas and rivers of Africa and the Indian subcontinent.', 'Mostly its own kind, though it will associate with humans and D-Bees, other aquatic beings especially; often found in pirate crews on the coasts, rivers and lakes.', 'Treats most humanoids as prey. Coalition Dead Boys and Free Quebec Glitter Boys are enemies; dislikes Bayou Ursines, Psi-Stalkers and most mammalian peoples; hates Deer Horn, Butter Trolls and Dramins; Horune Pirates, who enslave its kind, are hated rivals.', 'A full R.C.C. with its own skills, on the Juicer experience table; no O.C.C. is available. Hard to play: the mind of a ten year old, a six year old''s emotional maturity, and little grasp of technology, magic, law or manners. Its claws are too large for most human weapons, devices or tools. Player characters start at level one; NPCs are level 1D4+3. Carries two giant satchels, 1D4 large sacks and a 3-5 gallon (11-19 liter) water skin. No bionics. Slave market value 2D4x10,000 credits.', 'Crab-Men or Devil Crabs: semi-intelligent alien predators with a hunched, roughly humanoid upper body, oversized pincer arms, short horns, feelers and six crab-like legs, armored in a sand-colored shell as tough as ceramic tank plate. They live on shores, spend over half their lives underwater, and ambush ships and travelers for food. Reprinted from Rifts Sourcebook Four: Coalition Navy.', 'Rifts World Book 30: D-Bees of North America p.48-51'),
('deer-horn-tribesman', 'Deer Horn Tribesmen', 'humanoid', 'rifts', 1, 'Theoretically any; commonly Anarchist (40%), Miscreant (20%) and Diabolic (40%)', '{"IQ":"1D6+5","ME":"2D6+1","MA":"1D6","PS":"3D6+8","PP":"3D6","PE":"2D6+3","PB":"1D6+3","Spd":"6D6"}', NULL, NULL, '3D6+PE', '3D6', NULL, 'M.D.C. is 3D6 plus the P.E. number, plus 1D6 M.D.C. per level of experience. P.P.E. 3D6 is the typical tribesman''s; a Shaman (one in ten) adds it to the P.E. number x3, plus 1D6+5 P.P.E. per level. P.S. is Supernatural. Horror Factor is 12 with the head twisted into an odd position and 14 for a pack of five or more.', NULL, 10, NULL, '+2 to save vs psionic attacks; +1 to save vs Horror Factor at levels 1, 3, 6 and 9. In addition to attribute and skill bonuses. Attacks per melee as per Hand to Hand: Basic; damage as per Supernatural Strength. Vulnerabilities: none as such.', 'R.C.C. skills: Language (Native Tongue): Gobblely 92% (never improves), Language: Other, one of choice (+6%; no language above 90%), Art (+10%), Cook (+5%), Dance (+10%), Fishing (+15%), Identify Plants & Fruit (+15%), Land Navigation (+15%), Sing (+5%), Whittling & Sculpting (+10% with antler and bone), Wilderness Survival (+20%), W.P. Archery, W.P. Targeting, W.P. Blunt, Hand to Hand: Basic (cannot be changed). Natural climbing 92/82%, acrobatics 90%, swimming 65%. Five R.C.C. Related Skills, plus one at levels 3, 6, 10 and 14; three Secondary Skills, plus one at levels 4, 8 and 12. A Shaman lacks W.P. Archery and W.P. Targeting, picks no further W.P.s and has half the Secondary Skills.', 'Nightvision 1,000 feet (305 m), working in total darkness. Turns its head 280 degrees to either side, owl-fashion, or spins it 180 degrees either way so the face sits upside down. A born climber, acrobat and swimmer (see the skills).', 'None, except the Shaman, who knows magic intuitively much as a Mystic does but with no psionics. Starting spells: Befuddle (6), Chameleon (6), Cleanse (6), Death Trance (1), Energy Bolt (5), Globe of Daylight (2) and Light Healing (6); one more spell from Invocations levels 1-4 at each level from level two.', 'None.', '4 feet (1.2 m) tall', '90-100 pounds (40.5 to 45 kg)', '4D6+35 years; mature at 14, litters of 1D4 after a 10 month gestation, up to age 35', 'Almost only the Dark Woods of Alabama and parts of Mississippi, in packs of 2D6+5, rarely as many as 3D6+10. Thought to have come through a Rift near the old town of Talladega.', 'Keeps to its own kind; even separate packs squabble.', 'Tries to dominate or drive off every other intelligent being it meets and treats most races as intruders to scare away or rob. Has learned to steer clear of Splugorth Slavers, Horune Pirates and Forest Wardens.', 'A full R.C.C. on the Crazy experience table; no O.C.C. may be taken. Not recommended as a player character, and a G.M. may ban it. One in ten is a Shaman. Player characters start at level one; NPCs are level 1D4+1. Owns little: a satchel, crude wooden cross, walking stick (1D8 S.D.C.), one other blunt weapon, a bow with 2D6+6 arrows, and antler weapons that mostly do 2D6 S.D.C. Only pack leaders wear M.D.C. armor (bone and hide: 20+2D6 on the main body, half elsewhere); one in four has a Vibro-Knife or other M.D. weapon (1D4 E-Clips), and one in twelve a magic item. Money 1D6x100 credits in gemstones, or 1D6x1,000 in trade goods for a player character or Chieftain. No cybernetics. Slave market value up to 1D4x1,000 credits in Atlantean arenas, half that to a freak show.', 'Deep Forest Apes or Spinning Head Wildmen: small, hairless, gray-green apish D-Bees with an alligator-like head and huge round eyes, the males with a shaggy white or black stripe down the spine. Named for the deer antlers they use and revere, they live in wolf-pack style bands under a Chieftain and are notorious for crude, wild behavior.', 'Rifts World Book 30: D-Bees of North America p.61-63'),
('dewtani', 'Dewtani', 'humanoid', 'rifts', 1, 'Principled or Scrupulous at first; by middle age most are Unprincipled (40%), Anarchist (30%) or Aberrant (15%); in the last two decades of life many are Anarchist (40%) or Aberrant (40%)', '{"IQ":"3D6+4","ME":"3D6+4","MA":"2D6","PS":"2D4+4","PP":"2D6+4","PE":"3D6+2","PB":"3D6+2","Spd":"3D6"}', NULL, NULL, 'PE+6', '1D4x10+PE', NULL, 'A minor M.D.C. being: the P.E. number +6 M.D.C., plus 1D6 M.D.C. per level of experience. The P.P.E. figure is added to the base P.P.E. of the magic O.C.C. chosen. Horror Factor is not applicable.', NULL, NULL, NULL, '+1 to Spell Strength from level one, +2 to save vs disease, +2 to save vs Horror Factor; the vampire''s bite and charms do not affect it. In addition to attribute, O.C.C. and skill bonuses. Attacks per melee as per the Hand to Hand skill of the O.C.C.; damage by combat skill, weapon or magic. Vulnerability: gathers insanities through life with no save, and more from trauma: a phobia at level 3 and again at level 7, an obsession at levels 5 and 11, a psychosis at level 9, an affective disorder at level 13, and a random insanity at level 15 and every three levels after.', NULL, 'A natural with magic. Whatever its O.C.C., it senses ley lines, nexus points, Rifts and magic being used as well as a first level Ley Line Walker can. Its pale blue skin markings turn nearly black while it casts, draws P.P.E. or works a magic device.', 'Knows the principles of magic by nature, but no spells without a magic O.C.C. Taking a class that calls for psychic powers (Mystic, Mystic Knight), it gets no psionics and instead one extra spell per level.', 'None.', 'Males 6-7 feet (1.8 to 2.1 m) tall; females 5 feet to 5 feet, 10 inches (1.5 to 1.78 m)', 'Males 110 to 170 pounds (49.5 to 76.5 kg); females 90 to 140 pounds (40.5 to 63 kg)', '6D6+160 years; mature at 20, middle-aged at 90, an elder at 145; one child after a 20 month gestation, sterile by middle age', 'Chiefly North America, wherever there are ley lines: the Magic Zone, Minnesota, Colorado and Lazlo. Also England, France, Poland, Russia and China.', 'No natural allies; inclined to trust other practitioners of magic, renowned heroes, Cyber-Knights and those who have proven themselves.', 'No known enemies, but regards psychics as rivals and untrustworthy, with rare exceptions such as a Cyber-Knight, Mind Melter or Psi-Warrior.', 'Takes a magic O.C.C., one of: Ley Line Walker, Shifter, Mystic, Conjurer, Ocean Wizard, Stone Mage/Stone Master, Russian Fire Sorcerer, Old Believer/Nature Magic or (if evil) Mystic Knight. Under 1% practice Techno-Wizardry or Mystic Kuznya. Never a Witch, Necromancer or Bio-Wizard, and it shuns Warlock elemental magic. Equipment and money as per O.C.C. Accepts Bio-Systems for medical reasons only. Player characters start at level one; NPCs are level 1D8+2. Slave market value 6D6x10,000 credits.', 'The Gifted: human-looking D-Bees with tall pointed ears, narrow jaws, bronze skin and black hair that silvers in middle age, marked from neck to wrists with unique light blue patterns. Flung to Earth from a ley line world of their own, they are devout born magic users whom the ley lines here slowly drive insane.', 'Rifts World Book 30: D-Bees of North America p.64-66'),
('dirari-ecto-man', 'Dirari Ecto-Man', 'alien', 'rifts', 1, 'Theoretically any, but good is rare; typically Anarchist (30%), Miscreant (30%), Diabolic (15%) or Aberrant (12%)', '{"IQ":"2D6+10","ME":"3D6","MA":"2D4+3","PS":"3D6","PP":"3D6","PE":"2D6","PB":"N/A","Spd":"1D4x10+24"}', '2D6x100', '4D6x100', NULL, '1D4x10+1D6', 'ME+2D6x10+30', 'Hit Points are 2D6x100, +11 per level of experience. S.D.C. is 4D6x100. Both belong to the orb alone. Never a Mega-Damage being, but each 100 points counts as about one M.D.C., so the orb has roughly 6 to 36 M.D.C. I.S.P. is the M.E. number plus 2D6x10+30, +10 per level. Spd is hovering/flying. Vapor body (astral Hit Points): main body 50 +10 per level, each of four limbs 12 +3 per level. Solid ectoplasm body: main body 100 M.D.C. +5 per level, each of four limbs 25 M.D.C. +2 per level. Losing a body of either kind costs the Dirari 10% of its Hit Points and 20% of its S.D.C. (round up).', 16, 15, '{"attacks":6,"initiative":2,"strike":1,"parry":2,"automatic_dodge":5}', 'Six physical or psionic attacks per melee at level one, +1 at levels 5, 10 and 15. +3 on Perception Rolls. +1 to strike at each of levels 1, 4, 8 and 12. The +2 parry needs the ecto-body arms, which can parry energy blasts at no penalty. +6 to save vs possession, +4 vs all mind control, +2 vs magic illusions, +1 vs Horror Factor at each of levels 1, 3, 6, 9, 12 and 16. Immune to disease and to ordinary heat and cold. A.R. 16 counts against non-Mega-Damage attacks only. Hitting the orb takes a Called Shot and the attacker is still -2 to strike. Mega-Damage only by M.D. weapon or certain psionic powers. Vulnerabilities: plainly inhuman, physically limited, and the orb is fragile against M.D. attacks unless shielded by a Psychic Body Field or similar force field.', 'R.C.C. skills: Language: Native Tongue (Dirari) 98%, four Language: Other (+10% each), Land Navigation (+15%), Mathematics: Basic (+20%), Mathematics: Advanced (+10%), Prowl (+30%, and +10% more as a bare orb), Streetwise (+20%), Tailing (+20%), one W.P. Ancient and one W.P. Modern. R.C.C. Related: five at level one, +1 at levels 4, 9 and 12, from Communications (+5%), Domestic (+5%), Espionage (+5%), Rogue (+10%), Technical (+5%) and W.P. (any). Secondary: four, +1 at levels 3, 6, 9 and 12.', 'Nightvision 900 feet (274 m), sees the invisible, human-grade day vision, and 360 degree sight, so a conscious Dirari is never surprised. Needs no air, feels no pain, mends three times as fast as a human, and takes half damage and effect from poisons and drugs. Perpetual Flight: free, unlimited psionic flight up to 200 feet (61 m) high, hovering at will and never landing unless held down; underwater it moves at half Spd down to 1,000 feet (305 m); always silent. Ectoplasmic Body: a six foot (1.8 m) featureless humanoid shape grown under the orb at no I.S.P. cost, able to wear clothes and hold things. Growing one takes two melee rounds; switching state or dropping it takes two melee actions; a destroyed body cannot be regrown for six hours. As invisible vapor it is seen only by those who see the invisible, ultraviolet sight or sight of Astral Beings, slips through cracks and keyholes but not walls, lifts at most 40 lbs (18 kg), and its limbs reach 40 feet (12.2 m) +5 feet (1.5 m) per level; only magic, psionics, magic weapons, Astral Beings and anti-entity weapons hurt it, M.D. converting point for point. As solid ectoplasm it is a glowing white figure that lifts whatever the P.S. allows, with limbs reaching 10 feet (3 m) +3 feet (0.9 m) per level through any gap a golf ball would pass; magic, psionics and astral attacks do full damage, energy weapons half, kinetic attacks nothing.', 'None; no magical aptitude', 'Master Psionic. Level one: Alter Aura, Mind Block, Sixth Sense and Psychic Body Field (around the orb only), plus ten powers from Healing, Physical and Sensitive. Level two: two more from those three categories and one Super (not Mind Wipe, Psi-Sword or Mentally Possess Others). Level three: two more from the three and one Super (any). Level four: one Super. From level five: one non-Super power per level, and one more Super at levels 7, 9, 11 and 14.', 'Orb the size of a soccer ball; the ectoplasmic body stands 5-6 feet (1.5 to 1.8 m) with the orb as its head', '20 lbs (9 kg)', '3D6+85 years', 'Anywhere, but mostly North America, wherever easy money is to be had: the Chi-Town ''Burbs, Old Bones, Ciudad Juarez, the Barony of Charity, the Pirate Kingdom of Montreal. Under 200 on the continent, all arrived by the Calgary Rift.', 'Criminals and evildoers of any race, dragons, demons and Minions of Splugorth among them; the Black Market, Pecos Bandits, mercenary companies, slavers, pirates and assassin guilds', 'Heroes and lawmen, Cyber-Knights and Sky Knights above all. Admires the Coalition States but keeps clear of them for fear of being shot as a monster.', 'No O.C.C.: a full R.C.C. that lives on its own skills and psionics and advances on the Dragon experience table. Player characters start at level one or two; NPCs average 1D4+2. No cybernetics or bionics. Carries one M.D. firearm and one S.D.C. firearm with 1D4+1 reloads each, a survival knife, and 3D6x1,000 credits.', 'A psionic alien that is nothing but a hovering blue sphere. To deal with humanoids it grows a faceless ectoplasm body beneath itself and dresses it, so that it looks like empty clothes walking under a glowing ball, and is widely taken for a ghost. Brilliant and amoral, most on Earth are professional criminals: thieves, smugglers, kidnappers, spies and hired killers.', 'Rifts World Book 30: D-Bees of North America p.66-71'),
('dnorr-devilman', 'D''norr Devilman', 'humanoid', 'rifts', 1, 'Any, but mostly Principled (30%), Scrupulous (30%), Unprincipled (15%) or Anarchist (15%)', '{"IQ":"2D6+6","ME":"2D6+4","MA":"2D6+12","PS":"3D6","PP":"3D6","PE":"3D6","PB":"2D6+3","Spd":"3D6"}', 'PE', '20', NULL, '6D6+PE', NULL, 'Hit Points are the P.E. number, plus 1D6+2 per level of experience. S.D.C. is 20, plus whatever skills or the O.C.C. add. M.D.C. only from body armor, force field or magic. P.P.E. is 6D6 plus the P.E. number for every D''norr, mage or not, and any P.P.E. from a magic O.C.C. is added on top. M.A.: when the 2D6+12 roll comes to 18 or more, one further 1D6 is rolled and added.', NULL, 12, NULL, '+4 on Perception Rolls, +1 to save vs mind control, +1 to save vs illusions, +3 to save vs possession. Vulnerabilities: -1 to save vs Horror Factor and vs Insanity. The Horror Factor of 12 fades once people know the individual. Attacks per melee as per Hand to Hand skill; damage by combat training, weapon or magic.', 'R.C.C. skills, whatever the O.C.C.: Anthropology (+10%), Art (+20%), Mathematics: Basic and Mathematics: Advanced (+15%).', 'No special powers: the body is a match for a human''s. What sets a D''norr apart is the mind, the high I.Q. and M.A. producing clever, likeable talkers who can turn that charm to a swindle.', 'By O.C.C. only, on top of the racial P.P.E.', 'None', '5-6 feet (1.5 to 1.8 m)', '120 to 180 lbs (54 to 81 kg); slender', '5D6+170 years; adult at 18, and females can bear a child up to age 80', 'All over the Americas, thickest at Tolkeen (until it fell), Lazlo, New Lazlo and the Midwest. A few have gone to the Magic Zone, and those who went to Atlantis ended up enslaved.', 'Makes friends widely; well regarded by Cyber-Knights, lawmen and all who know the race as honorable', 'The Coalition States, which rank them high for extermination as mages; monsters, villains and cutthroats; Psi-Stalkers and other P.P.E. feeders, though Psi-Stalkers who get to know them tend to warm to them', 'Any O.C.C., Men at Arms included, though most pick an Adventurer, Scholar or magic class; half are mages, commonly a Warlock, Techno-Wizard, Conjurer or Ley Line Walker. Never Witchery, demon worship or the dark arts, and no psionic O.C.C., Mystic included. Advances on the O.C.C.''s experience table; player characters start at level one, NPCs average 1D8. Gear and money as per O.C.C. Most shun implants beyond an O.C.C.''s minimum or a medical prosthetic.', 'Red-tan humanoids with a gourd-shaped skull (dark red on males, purple on females) studded with small spines, deep blue eyes, pointed ears and two forehead horns. The devil looks mislead: they are gentle, learned and curious, born teachers and diplomats, a third of them outright pacifists. Magic did not exist on their world and it enthralls them. First printed in Coalition Wars Three: Sorcerers'' Revenge.', 'Rifts World Book 30: D-Bees of North America p.71-72'),
('dramin', 'Dramin', 'humanoid', 'rifts', 1, 'Any', '{"IQ":"3D6","ME":"4D6","MA":"2D6+2","PS":"3D6","PP":"3D6","PE":"3D6","PB":"3D6","Spd":"3D6"}', 'PE', '5D6+2', NULL, '5D6', NULL, 'Hit Points are the P.E. number, plus 1D6 per level of experience. Base S.D.C. is 5D6+2. Horror Factor is printed as not applicable. I.S.P. is not printed (psionics as for humans).', NULL, NULL, NULL, '+1 on Perception Rolls, +5 to save vs illusions of any kind. Attacks per melee and damage as per Hand to Hand skill.', NULL, 'Close to human in most respects. The eyes have no lids, are solid black and compound: they see only ordinary light, but the many separate receptors make illusions easy to see through (the +5 save). An unusually high P.P.E. for a human-like race, put down to how readily a Dramin accepts the strange.', 'None, unless a magic O.C.C. is taken', 'Standard; the same odds as a human', '5 to 6 feet (1.5 to 1.8 m)', '110 to 190 pounds (49.9 to 86 kg)', '2D6+70 years; ages and breeds much as humans do', 'Turns up anywhere from time to time, crossing the Megaverse by both machine and magic. On Rifts Earth most are in North America, especially around Lazlo, the Magic Zone and the CS ''Burbs.', 'None as a race; a handful of committed Dramin diplomats aside, they do little diplomacy with other species', 'No racial enemy; individuals often make personal ones through single-minded pursuit of a goal and an offhand manner toward others', 'Any commonly available O.C.C., and any school of magic, exotic ones included, if a teacher can be found. Most avoid chemical or mechanical augmentation (under 3% favor it). Player characters start at level one; NPCs average 2D4. Gear, money and cybernetics as per O.C.C. Slave market value 1D6x1,000 credits.', 'Human-looking D-Bees with ash-gray skin and small black lidless eyes, and no natural powers to speak of. What is alien is the outlook: nearly every Dramin believes it is the only real being and that the world is a test or game staged for it. Some answer with faith and good works, some with study and science, some with reckless self-indulgence. All are self-reliant, adaptable and distant, working with others only while it serves their purpose.', 'Rifts World Book 30: D-Bees of North America p.73-75'),
('drizzit', 'Drizzit', 'insectoid', 'rifts', 1, 'Any, but leans toward Principled (10%), Scrupulous (20%), Unprincipled (20%) and Anarchist (30%)', '{"IQ":"2D6+10","ME":"3D6+3","MA":"4D6","PS":"5D6+6","PP":"4D6","PE":"4D6","PB":"2D6","Spd":"6D6x10+36"}', NULL, NULL, 'PEx3', '2D6', NULL, 'The M.D.C. formula is the MALE''s: P.E. x3, plus 1D6 per level of experience. A FEMALE has P.E. x5, plus 2D6 per level. Each of a female''s four wings has 1D4x10+14 M.D.C. P.S. is Augmented (equal to bionic). Spd is as printed for running upright; it doubles when hopping, and a female flies at Spd 132 (90 mph/144 km).', NULL, 10, '{"attacks":1,"initiative":3,"strike":1,"parry":2,"dodge":2,"roll":1}', 'The attack is one EXTRA attack per melee from the second pair of arms, added to the Hand to Hand skill of the chosen O.C.C. Dodge is +4 while hopping and +5 while flying (females only). Horror Factor is 13 when taken for a Xiticix. Damage as per combat skill and Augmented P.S. Vulnerabilities: triple penalties from spells and attacks that work on hearing or smell (the Glitter Boy''s Boom Gun included); loud noise is twice as loud to a Drizzit, and distracts and frightens it.', 'Every Drizzit has Botany and Farming at 90%. Antennae tracking equals the Tracking skill at 75%.', 'Both sexes: mend twice as fast as a human, jump 50 feet (15.2 m) up or over, see in the dark to 120 feet (36.6 m), and have body hairs that read air pressure and temperature (wind direction at 80%, a weather forecast 1D4 hours ahead at 60%). Four working arms speed any manual work. Rubbing the raised arms makes a very loud cricket-like alarm that brings other Drizzit together. Females alone have four wings kept under a hard hood; a wing mends normally but one destroyed is gone for good. Antennae Sensor System: smells picked up at 4 miles (6.4 km) and faint sounds at 1,000 feet (305 m), and a trail followed by scent or sound, rolling again each 1,000 feet (305 m).', 'None, unless a magic O.C.C. is taken', 'None', 'Males 6-8 feet (1.8 to 2.4 m); females 8-12 feet (2.4 to 3.6 m)', 'Males 160 to 180 pounds (72 to 81 kg); females 200 to 320 pounds (90 to 144 kg)', 'Males 2D4+32 years, females 3D4+38; adult at 10. A female lays 2D4+16 young at a time, as often as every 6 months.', 'Temperate country by preference, rainforest too: anywhere fruit will grow. On Rifts Earth mostly between the Magic Zone, Dinosaur Swamp and the Deep South, with a large community in South America.', 'None in particular; gives every race a fair hearing and gets on best with farmers and wilderness folk', 'The Xiticix, whom they loathe as murderous savages. Dislikes heavy industry and keeps away from the CS.', 'Any Scholar or Adventurer O.C.C. that neither grants nor needs psionics. A magic O.C.C. is allowed but unusual: of the mages, 70% are Biomancers, 15% Priests of nature spirits, the rest Ley Line Walkers, Shifters and Warlocks. Player characters start at level one; NPCs average 1D6. Gear and money as per O.C.C. No cybernetics or bionics. Slave market value 1D4x1,000 credits.', 'Tall, lanky, intelligent grasshopper people, pale green to sandy brown and darker in winter, known as Hopper Bugs. They cannot form human speech and talk in pops, clicks, whistles and a forearm chirp that carries for miles. Peaceful fruit farmers with no hunting instinct, they would sooner move on than fight, yet will fight to the death for brood or farm.', 'Rifts World Book 30: D-Bees of North America p.75-76'),
('feni-nomad', 'Feni Nomad', 'humanoid', 'rifts', 1, 'Any, but tends toward Unprincipled (40%) and Anarchist (40%)', '{"IQ":"2D6+4","ME":"1D6+5","MA":"2D6+1","PS":"2D6+7","PP":"2D6+7","PE":"3D6+9","PB":"3D6","Spd":"1D6x10+46"}', 'PEx2', '4D6x20', NULL, '2D6+6', NULL, 'Hit Points are P.E. x2, plus 1D8 per level of experience. Base S.D.C. is 4D6x20, enough to soak a little Mega-Damage. M.D.C. only from light or medium armor and the Berserker Fight Response, which adds 1D6x100 S.D.C. (equal to 1D6 M.D.) per level for the length of the fight; damage comes off that first, then normal S.D.C., then Hit Points. Spd is for two legs (66-76 is typical); +30% on all fours.', NULL, NULL, '{"initiative":4,"dodge":2,"roll":1,"pull_punch":1}', '+4 on Perception Rolls and +16 to save vs toxins and disease; the printed bonuses already count those from the natural abilities. Berserker Fight Response only: +2 attacks per melee, +2 strike, +3 parry, +4 automatic dodge, +5 to disarm, pin or entangle, +5 to save vs mind control or possession, and Horror Factor 13. No Horror Factor otherwise. Attacks per melee as per Hand to Hand skill. Vulnerabilities: -3 to save vs Horror Factor, and it bolts as soon as it can move; any strong emotional strain needs a roll of 12 or better or it runs. Cornered, trapped or guarding women, children or loved ones it always fights instead. Anxious, wary of technology and of strangers.', 'R.C.C. skills, whatever the O.C.C.: Wilderness Survival (+10%), Track (but not Trap) Animals (+5%), Land Navigation (+5%), Outdoorsmanship, Swimming (+10%), Sing (+10%); these stack with an O.C.C.''s bonus to the same skill. Hearing: judge a sound''s distance 50% +5% per level, its speed and heading 45% +5% per level, know a particular voice or sound 60% +5% per level. Smell: track by scent alone 44% +4% per level (+10% on blood or another strong smell), identify common or strong scents 70% +3% per level, identify a specific odor 52% +2% per level.', 'Berserker Fight Response: triggered when defending someone else, a mate or young above all, or when escape is cut off; it still knows friend from enemy and stops once the way out is clear. Chameleon Fur: recolors to match the background in 1D4 seconds, often by reflex when frightened; 90% unseen when motionless, 70% at 2 feet (0.6 m) a melee round or less, 33% at 6 feet (1.8 m) a round, useless faster, and -75% when clothes or armor cover over half the body. Superior Hearing out to 500 feet (152 m); a sudden noise can set off the fur. Superior Sense of Smell, on a par with a Dog Boy. Punctuated Equilibrium: the body rebuilds itself for arctic, desert, mountain, underground, underwater or (rarely) gliding life in 1D4 melee rounds, during which it loses 1D6 Hit Points outright, has -9 on strike, on parry and on dodge, -65% on skills and at one tenth speed; afterward it is at ease from -150 to +150 Fahrenheit (-101 to 65.6 C). Gliding manages 20 mph (32 km) from a standing jump or 50 mph (80 km) with wind or height. Vacuum is the one thing it cannot adapt to. Atmospheric Equilibrium: breathes any atmosphere after one melee round, losing two actions and taking -2 in combat that round; a change of under 60 minutes can be reversed harmlessly. Digestive Equilibrium: eats nearly anything short of M.D.C. material, teeth reshaping to suit.', 'None', 'None', '4 to 4.6 feet (1.2 to 1.4 m) at the shoulder; 5.6 to 7 feet (1.7 to 2.1 m) overall with neck and head', '130 to 200 pounds (58.5 to 90 kg)', '2D6+33 years; adult at 10. One or two young after 7 months, as often as every two years, until age 32.', 'Any, with a liking for thickly wooded temperate land and for snow. Roams the North American wilds in family clans of 6D6 or tribes of 3D4x100, drifting south and west in winter, north and east in summer; commonest in the Pacific Northwest, Northern Mexico, Canada and the West Coast.', 'Mostly its own kind and other gentle peoples: Amana, Sasquatch, Cactus People, Fennodi. Sometimes Native Americans, Blucies, Elemental Fusionists, Druids and an adventuring party. Slow to befriend, loyal once it does.', 'Hunted for meat and sport by Psi-Stalkers, barbarians, slavers, Dark Hounds, Mystic Knights, Worm Wraiths, Oborus-Slitherers and Devil Unicorns. Fears the Minions of Splugorth, Horune Pirates and Coalition soldiers. Simvan scorn them but let them be.', 'One of these only: Wilderness Scout, Woodsman-Trapper, Pathfinder or Naturalist (the last two from World Book 26: Dinosaur Swamp), or a Rogue Scientist or Vagabond built around wilderness, plant, animal or domestic skills. Never pilots anything beyond a bicycle or a paddle or sail boat, and never builds or repairs machines. Player characters start at level one; NPCs average 1D6. Gear as per O.C.C., usually with fitted bone-and-hide armor of 35-55 M.D.C. No cybernetics or bionics. Slave market value 1D4x1,000 credits, or 1D4x100 as meat.', 'Deer-like nomads from the unstable world of Fen: sleek and furred, with back-bent hind legs on three-toed hooves and near-human arms ending in a half-hoof hand. They walk upright or run on all fours. Called Deerstalkers and Demon Fawn. Jumpy by nature, a Feni runs from trouble first, but one that is trapped or protecting the weak turns into a savage fighter.', 'Rifts World Book 30: D-Bees of North America p.80-83'),
('fingertooth-carpetbagger', 'Fingertooth Carpetbagger', 'humanoid', 'rifts', 1, 'Any, but leans toward Scrupulous, Unprincipled and Anarchist', '{"IQ":"2D4+7","ME":"2D4+7","MA":"3D4+9","PS":"3D4+11","PP":"2D4+5","PE":"3D4+9","PB":"2D4","Spd":"2D4+5"}', NULL, NULL, 'PE+11', '3D4', NULL, 'M.D.C. is the P.E. number +11, plus 2D4 per level of experience. P.S. is Augmented, like a Juicer''s or a cyborg''s.', NULL, 9, '{"initiative":1,"dodge":2,"roll":1,"pull_punch":1}', '+1 on Perception Rolls. +2 to save vs poison, spoiled food, drugs and alcohol; +7 vs disease; +4 vs psionic attack (and vs helpful or healing psionics); +6 vs possession and mind control. Horror Factor 9 on first meeting only; none for anyone who knows the race. Attacks per melee as per the Hand to Hand skill of the chosen O.C.C. Vulnerabilities: psionic resistance cuts both ways, so Telepathy, Empathy and similar contact work at half range and healing or helpful powers (Healing Touch included) at half effect; gullible and greedy when a big score is dangled.', 'R.C.C. skills, bonuses on top of any from the O.C.C.: Appraise Goods (+20%), Barter (+20%), Cardsharp (+5%), Find Contraband (+14%), Gambling (+10%), two Language: Other (+20%), Mathematics: Basic (+25%), Public Speaking (+15%), Recognize Weapon Quality (+20%). They REPLACE all the Secondary Skills of the chosen O.C.C.', 'Augmented/Bionic-grade P.S.; a Power Punch can do Mega-Damage at the cost of two attacks (no figure is printed). Nightvision 90 feet (27.2 m), a tough constitution and a hard head for drink. Superior Vision and Eye Filters: sharp color and polarized sight, untroubled by glare or bright light, with Blinding Flash at half penalty and half duration, plus a clear inner lid that closes against dust, sand and pollution.', 'None; never takes a magic O.C.C.', 'None, but psionically resistant', '4-5 feet (1.2 to 1.5 m)', '130-200 pounds (58.5 to 90 kg); pot bellied', '3D4+57 years; adult at 15. 1D4 young after eight months; 01-60% chance a female is infertile after her first birthing, and four birthings is about the limit.', 'Wherever there is buying, selling or gambling to be done, seldom over 1D4+3 years in one spot: boomtowns, trading posts, New West towns, MercTown, Arzno, Kingsdale, Upper Michigan and the CS ''Burbs.', 'Anyone it trusts or who might lead to a big score; City Rats in the ''Burbs, and a soft spot for drunks, Barmaids, Professional Gamblers, Saddle Tramps and Vagabonds. Travels alone or as a small family.', 'Sees the Naruni and the Splugorth as both models and rivals (they think it a joke). Dislikes slavers and will not touch the slave trade.', 'Limited to Rogue Scholar, Vagabond (any, the Merchant/Salesman above all), City Rat, Smuggler and Con Artist, plus four from World Book 14: New West (Saddle Tramp, Saloon Bum/Stoolie, Professional Gambler, Saloon Girl/Barmaid). Player characters start at level one; NPCs average 1D4+3. Gear as per O.C.C. plus a salesman''s kit (cards, pocket watch, translator, recorder, tool kit, carpetbag, duffle, 1D4+1 sacks) and an extra 2D4x1,000 credits in trade goods or information. Avoids bionics except for medical repair. Slave market value 1D4x1,000 credits.', 'Pear-shaped, pot-bellied little D-Bees, pale green or yellow with dark speckles, bulging brown eyes, and two finger-like pincers on the upper lip above rows of sharp teeth. Also called the Two-Finger D-Bee. Born hucksters with a knack for languages, they wander selling, dealing and gambling, yet deal honestly and are generous to the unlucky.', 'Rifts World Book 30: D-Bees of North America p.85-87'),
('flooper', 'Flooper', 'humanoid', 'rifts', 1, 'Any, but most are Unprincipled (15%) or Anarchist (65%)', '{"IQ":"2D6+3","ME":"2D6+6","MA":"3D6+12","PS":"2D6+3","PP":"2D4+14","PE":"3D6+2","PB":"2D6+2","Spd":"4D6"}', NULL, NULL, '2D6x10', '1D6x10', '4D6+ME', 'M.D.C. is 2D6x10, plus 1D6 per level of experience. I.S.P. is 4D6 plus the M.E. number, +1D6 per level. Horror Factor: none.', NULL, NULL, '{"initiative":1,"dodge":2,"roll":3}', '+2 melee ACTIONS (not attacks) per melee. +1 to dodge by Flooping at each of levels 1, 2, 4, 6, 7, 8, 9, 11, 13 and 15. +2 to save vs magic, +2 to save vs Horror Factor. Attacks per melee as for a character with no Hand to Hand skill (Rifts Ultimate Edition p.347), or by Hand to Hand if one is taken, never better than Basic. Vulnerabilities: lazy, slovenly and inclined to push its luck.', 'R.C.C. skills: Acrobatics, Appraise Goods (+15%), Barter (+24%), Climbing (+10%), Dance (+15%), Escape Artist (+20%), Gymnastics, Juggling (+20%), Math: Basic (+15%), Performance (+10%), Prowl (+5%), Public Speaking (+20%), two Language: Other (+10%), W.P. Paired Weapons, W.P. Targeting. No Hand to Hand skill. Ambidexterity gives +5% to Cardsharp, Forgery, Juggling, Palming, Pick Locks and Pick Pockets. R.C.C. Related: four at level one, +2 at levels 4, 7, 11 and 15, from Communications (+5%), Domestic, Espionage (+5%), Horsemanship (General and Exotic Animals only), Physical (not Boxing), Pilot (no robots or military vehicles), Rogue (+10%), Technical and W.P. (not Heavy Weapons or Pole Arm). Secondary: two at each of levels 3, 6, 9 and 12.', 'Senses like a human''s; a Mega-Damage being that mends three times as fast as a human. Double-jointed and ambidextrous with very high P.P.: a born tumbler, juggler, escape artist and thief who shrugs off long falls. Flooping: at a thought it blinks out of the world into a limbo, normally for 2-5 seconds and for at most one melee round (15 seconds) per level, and can do nothing while away. It comes back where it left or up to three feet (0.9 m) per level off in any direction it can see, up and down included. Each there-and-back costs 3 I.S.P.', 'None', 'Minor Psychic: Empathy, Mind Block and Sixth Sense only', '4-5 feet (1.2 to 1.5 m); very round and flabby', '1D4x100 pounds (45 to 180 kg)', '1D6x10+122 years; adult at 20. One young after 12 months, possible up to age 100, but rarely more than five in a lifetime. Males outnumber females two to one.', 'Commonest in the American Southwest, the Deep South and Mexico near the border, but met anywhere, often with a traveling show', 'Other Floopers, in twos to fours. Fond of humans and Larmac, and of anyone who enjoys the act or stands a meal or a drink.', 'No true enemies beyond those it has cheated or robbed. Counts Phlebus, Roane Pipers, Fingertooth Carpetbaggers, Kraks, Shapers and most shape changers as rivals.', 'No O.C.C.: a full R.C.C. that earns its keep performing or as a thief, pickpocket, spy or informer, advancing on the Psi-Stalker experience table. Player characters start at level one; NPCs average 1D4+2. Starts with costumes, juggling pins, wooden and silver-plated throwing knives, a Vibro-Knife (1D6 M.D.), 2D6x100 credits and 1D4x1000 in trade goods. Cybernetics and bionics are not possible.', 'Short, round, floppy-eared D-Bees who work circuses, carnivals and taverns as clowns, tumblers and jugglers, and on the side as pickpockets, informers and gossip brokers. Agile far beyond their bulk, they dodge harm by popping out of existence for a moment with the sound that names them. Cheerful, talkative and idle to a fault. First printed in World Book One: Vampire Kingdoms.', 'Rifts World Book 30: D-Bees of North America p.87-89');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('forest-warden', 'Forest Warden', 'alien', 'rifts', 1, 'Any, but the vast majority are Anarchist (40%) or Aberrant (50%)', '{"IQ":"2D6+1","ME":"2D6","MA":"2D6","PS":"4D6+2","PP":"2D6+6","PE":"3D6+12","PB":"2D4+1","Spd":"2D6+6"}', NULL, NULL, 'PEx3', '6D6', NULL, 'M.D.C. is P.E. x3, plus 2D6 per level of experience. In S.D.C. environments: Hit Points P.E. x3 plus 2D6 per level, and S.D.C. P.E. x5 plus 4D6 per level. P.P.E. is 6D6, +3D6 for every 50 years of life. Supernatural P.S. Bio-regenerates 2D6 M.D.C. an hour. A rooted seedling (first 1D4+10 years) has only 5D6 M.D.C.', NULL, 12, '{"attacks":5,"initiative":1,"strike":1,"parry":3,"dodge":1,"roll":3,"pull_punch":2}', 'Five attacks per melee at level one, +1 at levels 3, 6, 9, 12, 15, 18, 22 and 30 (Dragon experience table for these). +2 on Perception Rolls, +10% to save vs Coma/Death, +3 to save vs mind control (a successful mind control lasts half as long), +5 to save vs possession; all in addition to attribute and skill bonuses. Damage as per Supernatural Strength or weapon. Vulnerabilities: all Mega-Damage fire, plasma included, does double damage with a 70% chance of combustion (half the initial damage again each melee round until put out); S.D.C. fire does its damage as M.D. with a 10% chance of combustion. Needs four hours of sunlight a day or bonuses are halved (round down) until six more hours are spent in the sun. From about age 300 all physical attributes and bonuses are halved.', 'R.C.C. skills: Language: Native Tongue (American) 90%, Language: Other two of choice (+10%; a language cannot exceed 90%), Acrobatics (+5% where applicable), Astronomy & Navigation (+20%), Botany (+30%), Brewing (+10%), Camouflage (+30%), Climbing (+25%), Detect Ambush (+20%), Detect Concealment, Firefighting (+15%), Holistic Medicine (+15%), Identify Plants & Fruit (+10%), Land Navigation (+5%), Lore: Demon & Monsters, Mathematics: Basic (printed as 20%), Prowl (+10%), Swimming (+10%), Tracking (people; +5%), Trap/Mine Detection (+15%), Wilderness Survival (+30%), W.P. Blunt, W.P. Energy Pistol or Energy Rifle (pick one), two W.P.s of choice (any, Ancient or Modern), Zoology (+10%). R.C.C. Related: two more skills at levels 2, 4, 8, 12, 16 and 20 from Communications, Domestic (+10%), Technical (+5%), Wilderness (+15%) and W.P. (any). Secondary skills: none. Experience: Psi-Stalker table; NPCs are level 1D10+2.', 'A Mega-Damage plant being. Breathes trace carbon dioxide instead of oxygen and lives on sunlight, water and wild plant foods. Thermal-imaging sight out to about 4,000 feet (1,220 m); hearing is human-grade. Human diseases, carcinogens, poison and toxin do nothing to it, nor do ordinary heat and cold or any attempt at symbiotic control; plant diseases may. Prehensile hands and feet let it swing limb to limb through the trees, and standing still it passes for the local flora.', 'None, despite the high P.P.E.', 'None', '7-11 feet (2.1 to 3.3 m) tall', '300 to 1,000 pounds (135 to 450 kg)', '2D4x10+420 years; mature at 30, slowing down from about 300. Once a century a female bears 2D6x10 seedlings', 'Almost exclusively the Dark Woods of Alabama and parts of Mississippi, in communal groups of 10-40; only a few thousand are thought to exist. Believed to have come through a Rift near Selma, Alabama', 'None as such, beyond their own kind', 'Humans and anyone else they see as a destroyer of nature', 'No O.C.C. at all: the R.C.C. skills and abilities are everything it gets. The book advises against it as a player character (alien thinking; secretive, paranoid and naive away from home, and enraged by harm done to plants); player characters start at level one. Carries 2D6+6 throwing stones (2D6 S.D.C. restrained, 1D4 M.D. at full strength, 2D4 M.D. as a power throw costing two attacks), a stick or club doing the same, and one weapon with two E-Clips per W.P.; one in 40 owns a magic weapon or TW device. Wears no armor and uses no force field. No cybernetics or bionics. An NPC holds 1D6x10,000+50,000 credits of stolen technology. Slave market value 2D4x1,000 credits.', 'Gaunt tree-like D-Bees that look like ailing trees given the shape of old men or hags: bark skin, trunk-like legs, two to five amber eyes, and a beard and mane of leaves, needles or willow wands matching a breed (willow, pine, oak and elm are commonest). Stranded on Earth by the Great Cataclysm, they hold the Dark Woods as a fortress and ambush outsiders, large parties above all, yet are gentle with plant life and loyal to each other. Also called Tree Men, Bark Hags and Forest Lords.', 'Rifts World Book 30: D-Bees of North America p.90-93'),
('ganka', 'Ganka', 'alien', 'rifts', 1, 'Any, but most are Unprincipled (30%), Anarchist (25%), Aberrant (20%) and Miscreant (10%)', '{"IQ":"3D6","ME":"3D6","MA":"3D6+5","PS":"3D6+10","PP":"3D6+5","PE":"3D6+10","PB":"2D4+5","Spd":"2D6+4"}', 'PEx4', '2D6x100+420', NULL, '2D6', NULL, 'Hit Points (main body: head and trunk) are P.E. x4, plus 2D4 per level of experience. Base S.D.C. is 2D6x100+420 (may withstand small amounts of Mega-Damage); each of the 3-4 arm tentacles has 1D6x100 S.D.C. Augmented P.S.; the mouth has a P.S. of 40. Bio-regenerates 3D6 Hit Points or S.D.C. per hour. Swims at half running speed. M.D.C. and I.S.P. are not printed.', NULL, 12, '{"initiative":3,"strike":1,"parry":2,"disarm":2,"entangle":2}', 'Attacks per melee as per Hand to Hand skill, +1 attack per melee from the vine arms. The +2 to disarm and entangle is with the vine arms. +6 to save vs poisons, toxins and disease. All in addition to attribute and skill bonuses. Cannot be snuck up on by an attacker within 300 feet (91.4 m), and has Automatic Dodge against all attacks from within that distance, but is -10 to dodge gunfire from farther away. Vulnerabilities: needs 200 pounds (90 kg) of meat a week (any organic matter will do), two gallons (7.6 l) of fresh water a day, and sunlight; takes 1D6 damage direct to Hit Points per hour below 20 degrees Fahrenheit (-7 Celsius).', 'No R.C.C. skills are printed; skills come from the O.C.C. Smell: tracks a scent to its source at 87%, recognizes substances by smell at 74% +1% per level and by taste at 84% +1% per level. Experience: Psi-Stalker table; NPCs are level 1D4+1.', 'Eyeless, so blindness penalties, flash grenades and illusions mean nothing to it. Regrows a lost arm tentacle in 1D6+8 days and one root tentacle every 72 hours. Resurrection: at zero Hit Points and S.D.C. it only seems dead; 01-50% (01-66% if blown apart or buried) that a piece roots and grows back in 1D6+5 months with its memories, rooted in place meanwhile; only burning at least 85% of the body to ash stops this. Smells blood and sweat up to 2 miles (3.2 km) off. Hearing about equal to bionic Amplified Hearing. Sensor hairs feel all movement within a 300 foot (91.4 m) radius. Thermal receptors in the open mouth see warm bodies and running engines to 120 feet (36.6 m) across a 100 degree arc. Walks over plant-choked swamp water on its root mass and floats in any water.', 'None, unless a Magic O.C.C. is selected', 'None; the race has no psychics', '7-9 feet (2.1 to 2.7 m) tall, with a mouth about 3-4 feet (0.9 to 1.2 m) wide', '200 to 300 pounds (90 to 135 kg)', '2D4+50 years; physically mature in 1D4+1 years. A seed pod opens after 11 months to release 4D6 young', 'Hot, wet country: mainly in and around Dinosaur Swamp, with a few in Mexico and South America. Temperate riversides and marshes are possible but unusual; cold climates are not survivable', 'None as such, though they like the company of other plant D-Bees such as Cactus People', 'Xiticix and other large insects are food, and so are intelligent insect D-Bees and mutants', 'Any O.C.C. but Coalition, Juicer, Crazy, Cyborg, Robot Pilot or a psionic one. In practice half are Wilderness Scouts (any), 20% Merc Soldiers and 20% another man-at-arms type (Vagabond, Saddle Tramp, Gunfighter, Bounty Hunter, Bandit). Player characters start at level one. Equipment and money as per O.C.C.; seldom wears full environmental armor. No cybernetics or bionics. Sold as food in lots of 100 for 3D6x20,000 credits.', 'A boneless plant D-Bee built of vines: a sinewy trunk under a bulbous head whose mouth could hold a big dog, three or four tentacle arms, and a skirt of 2D4x10+18 root tendrils it walks on. In the Southeast for only about twenty years. Cheerful, joke-telling meat eaters that digest in the mouth (about an hour a meal, during which they cannot speak) and hold that the strong survive, so they rarely avenge a death; evil ones will eat companions. Also called Killer Ganka and Flytrap People.', 'Rifts World Book 30: D-Bees of North America p.93-95'),
('idie-swamp-man', 'Idie Swamp Man', 'humanoid', 'rifts', 1, 'Any; typically good or Unprincipled', '{"IQ":"3D6","ME":"3D6","MA":"2D6+4","PS":"3D6","PP":"3D6","PE":"2D6+6","PB":"2D6","Spd":"2D6"}', 'PE', '4D6+3', NULL, '4D6', NULL, 'Hit Points are the P.E. number plus 1D6 per level of experience. Base S.D.C. 4D6+3. Spd is 2D6 running and 6D6 swimming. M.D.C. is not printed (by armor). I.S.P. is not printed (psionics as for humans). Horror Factor: not applicable.', NULL, NULL, NULL, '+2 to save vs disease, +1 to save vs Horror Factor, and normal cold does half damage (M.D.C. cold does full damage); in addition to attribute and skill bonuses. Attacks per melee as per Hand to Hand skill; damage as per combat skill or weapon. Vulnerabilities: fatigues and dehydrates three times as fast as a human in hot, dry conditions and must be in water daily; when dehydrated all bonuses drop to zero and Spd, P.B., P.E., P.P. and P.S. are halved.', 'Swimming equivalent 95%; Prowl in water 70%. R.C.C. skill (regardless of O.C.C.): Riverwise 64% +4% per level (25% +5% per level for other races; a Pilot Related and/or Wilderness skill), which also gives +10% to Navigation and Land Navigation on familiar waterways. Experience table of the chosen O.C.C.; NPCs are level 1D6+2.', 'A born swimmer who tolerates depths to 1,000 feet (305 m), sees clearly through murky water, moves through water without a ripple, and holds a breath for 2D6+6 minutes. Knows every waterway, shortcut and aquatic hazard within 500 miles (800 km) of the home village.', 'None, unless a Magic O.C.C. is selected', 'Same probability of psionics as humans', '5 to 6 feet (1.5 to 1.8 m) tall', '150 to 320 pounds (67.5 to 144 kg)', '2D6+65 years; mature by 17. Females bear 1D4 young after six months and can do so until age 40', 'Swamps, marshes, everglades, ponds, lakes, rivers and coasts, above all along the Gulf of Mexico in the southern United States; scattered communities on the waterways of Kentucky and Tennessee and up the Eastern coast to Nova Scotia. Villages usually number 6-24', 'Judged case by case. On good terms with most aquatic and amphibious D-Bees, Swamp Sludgers especially, the Natchez at Sky Fort and the Crulls; also humans, Kraks and Horune Pirates', 'Case by case, though most distrust Bayou Ursines and think Larmac lazy; all regard the Splugorth and their Minions as dangerous slavers', 'Limited to the race''s own Idie Fisherman O.C.C. (73% take it) or one of these. Fighting: Mercenary Soldier, Maxi-Juicer, Head Hunter Techno-Warrior, Robot Pilot, a Grunt equivalent, any Pirate class. Adventurer: Wilderness Scout (any), Vagabond, Salvage Expert, Saloon Bum, Operator, City Rat (not Hack Rat), Body Fixer. Magic: Techno-Wizard (very common), Whale Singer, Warlock, Sea Druid, an Ocean Wizard equivalent, Mystic, Ley Line Walker, Ley Line Rifter, Houngan/Mambo, Conjurer. Psychic: Psi-Druid, Mind Melter. Player characters start at level one. Equipment, money and cybernetics as per O.C.C., though most avoid implants. Slave market value 2D4x1,000 credits.', 'Stocky, often overweight, light gray humanoids with big fish eyes and catfish whiskers, three webbed fingers to a hand and two webbed toes to a foot. Easygoing spear fishermen, boat builders, ferrymen and river guides of the Southeast who have taken up human culture and no longer recall their origin; some turn pirate. Also called Catfish People. About 130,000 live across the Gulf States and 10,000 to 20,000 in the East.', 'Rifts World Book 30: D-Bees of North America p.103-105'),
('iktek-digger', 'Iktek Digger', 'humanoid', 'rifts', 1, 'Any, but 60% are Anarchist', '{"IQ":"3D6","ME":"2D6+2","MA":"3D6","PS":"4D6+10","PP":"3D6","PE":"4D6+6","PB":"2D6","Spd":"4D6+2"}', NULL, NULL, 'PE+6D6', '2D6', NULL, 'M.D.C. is the P.E. number plus 6D6, plus 1D8 per level of experience (a minor M.D.C. creature). Augmented P.S. Spd is running. I.S.P. as normal for a psychic (Rifts Ultimate Edition p.289, Step 4). Horror Factor: not applicable.', NULL, NULL, '{"initiative":4,"parry":1,"dodge":1,"pull_punch":2}', '+3 on Perception Rolls and 60% Maintain Balance; in addition to attribute and skill bonuses. Attacks per melee as per Hand to Hand skill. Damage as per Augmented P.S. and combat training or weapon; the legs allow no foot strike except a snap kick. Vulnerabilities: sees only blues, greens and grays, which with the wide-set eyes makes most optical gear hard or impossible to use unless built for them; -5% to Prowl on Earth; -30% on Computer (all), Optic Systems, Photography, Sensory Equipment, Surveillance (not Tailing) and T.V./Video, and no sniping. Native-born Diggers are illiterate (literacy can be learned as a Related or Secondary skill).', 'R.C.C. skills (regardless of O.C.C.): Excavation (+10%), Mining (+10%), Rope Works (+5%), Wilderness Survival (+10%); already counted in the Iktek Hunter-Gatherer O.C.C. NPCs are level 1D6.', 'Peripheral sight across roughly 280 degrees, polarized day vision that shrugs off glare, and nightvision as good as its day sight. Hears with unusual clarity at frequencies 20% above the human limit. Augmented strength, a Mega-Damage hide, good speed and sure balance.', 'None, unless a Magic O.C.C. is selected', 'Some are psychic. A Minor psionic picks two of See the Invisible, Sense Evil, Sense Magic, Sixth Sense and Empathy; a Major has all five. Either uses them at half the normal I.S.P. cost (round up). No Master psychics.', '7-9.6 feet (2.1 to 2.9 m) tall', '250-400 pounds (112.5 to 180 kg)', '4D6+34 years; mature by 16. One or two young after a 22 month gestation', 'The New West, from what was Canada down to northern Mexico, favoring the heat of Utah, Nevada, Arizona, New Mexico and northern Mexico; adventurers turn up anywhere', 'Those keeping the hunter-gatherer life get on with most Native American tribes, Psi-Stalkers, Simvan and other nomads, and with Cactus People, Fennodi and other peaceful peoples, whom they often defend', 'Territorial disputes with Native Americans, Wild Psi-Stalkers, Simvan and other wandering tribes, from which they usually withdraw; they dislike bullies and persecutors', 'Virtually any O.C.C. Roughly 29% keep to the race''s own Iktek Hunter-Gatherer O.C.C., 25% are Men-at-Arms (Merc Soldier, Gunfighter, Tribal Warrior, Bandit, Bounty Hunter, Headhunter), 36% Adventurers (Cowboy, Vagabond, Explorer, Hunter-Trapper, Wilderness Scout), 6% Practitioners of Magic and 4% Scholars, Rogue Scholars as a rule (the mages are most often Elemental Fusionist, Warlock, Witch, Priest or Mystic; sometimes Shaman or Totem Warrior; rarely Techno-Wizard). Player characters start at level one. On top of O.C.C. gear: 300 feet (91.4 m) of good rope, a pair of large entrenching tools, likely M.D. leather or hide armor, and a melee weapon such as a Vibro-Sword or spear. Cybernetics as per O.C.C. Slave price about double a human''s.', 'Tall digitigrade aliens from a desert deific realm where they were the smallest prey animals: pebbly pale yellow to rust red skin, a large upper body and long arms on dog-jointed legs, wide-set eyes beside a flat nose and upright pointed ears. Skittish at first but quick to learn, they are leaving a Stone Age life of tunnels and traps. Properly Iktektumiks; also called Diggers, Tunnelers, Desert Savages and Horse-legged Diggers.', 'Rifts World Book 30: D-Bees of North America p.106-108'),
('krak', 'Krak', 'humanoid', 'rifts', 1, 'Any, but most are Scrupulous (35%), Unprincipled (30%) and Anarchist (20%)', '{"IQ":"3D6","ME":"3D6","MA":"4D6+4","PS":"2D6+2","PP":"3D6","PE":"3D6","PB":"2D6+2","Spd":"3D6"}', 'PE', '3D6+6', NULL, '3D6', NULL, 'Hit Points are the P.E. number plus 1D6 per level of experience. Base S.D.C. 3D6+6. M.D.C. by armor only. Spd is 3D6 running, double underwater. I.S.P. is not printed (psionics as for humans). Horror Factor: not applicable.', NULL, NULL, NULL, '+1 to dodge underwater, +2 to save vs disease; in addition to attribute and skill bonuses. Attacks per melee as per Hand to Hand skill; damage as per combat skills or weapon. Naturally Charming: +10% to any Trust percentage from a high M.A., never below 35% Trust whatever the M.A., but any Intimidation percentage is 10% lower. Vulnerabilities: dry skin unless it bathes at least every 48 hours (or uses a moisturizer), early wrinkling from sun and dryness, and fatigue at twice the human rate in hot, dry weather.', 'R.C.C. skills (regardless of occupation): 1D4 Language: Other (+30% each), Impersonation (+10%), Imitate Voices and Sounds (+20%), Public Speaking (+20%). Swimming equivalent 85%. NPCs are level 1D4+1.', 'Intelligence and senses on the human level. Amphibious: breathes air or water, swims naturally, and dives to 300 feet (91.5 m) with no decompression trouble. A natural mimic and charmer (see the bonuses).', 'None, unless a Magic O.C.C. is selected', 'Same probability of psionics as a human', '3-4 feet (0.9 to 1.2 m) tall', '85-180 pounds (38 to 81 kg)', '4D6+100 years', 'The far northwest of North America (Canada and Alaska, where they are thought to have Rifted in) and eastern Siberia; a once semi-aquatic people now living on land and in the cold. Over 90% call Earth home', 'Friendly to nearly everyone and fond of humans; also get on well with Larmac, Devil Men, Dog Boys, Idie, Fingertooth Carpetbaggers, Shapers and Fennodi', 'The prejudiced and the plainly evil; they steer clear of the Minions of Splugorth, Vanguard Brawlers, Coalition soldiers, other D-Bee haters and violent hunter types', 'Any O.C.C., leaning to social trades: Preacher, Professional Gambler, Con-Artist, Smuggler, Vagabond (merchant, bartender or carnival barker), Rogue Scholar, Operator, City Rat, or driving work. Of the Magic O.C.C.s, Techno-Wizard and Mystic appeal most. M.O.M. implants and Juicer conversion are impossible for them. Player characters start at level one. Equipment and money as per O.C.C.; cybernetics as per O.C.C. but generally refused. Slave market value 1D4x1,000 credits, with low demand.', 'Short, hairless, semi-aquatic D-Bees with blotchy green, tan or brown skin, big brown or yellow eyes and two fleshy tentacles hanging from the nasal ridge like a long mustache over a very human mouth. Third and fourth generation Earth natives who copy the speech, dress, accents and gestures of whoever is around them; loud, sociable and mostly working class. Properly Q''uratigo Cephalopodans; ''Krak'' began as a slur they have happily adopted.', 'Rifts World Book 30: D-Bees of North America p.109-111'),
('larmac', 'Larmac', 'humanoid', 'rifts', 1, 'Any, but the majority are Unprincipled (30%), Anarchist (30%), Aberrant (10%) or Miscreant (20%)', '{"IQ":"2D6+3","ME":"2D6+3","MA":"2D6","PS":"4D6+16","PP":"3D6","PE":"3D6+5","PB":"1D6+3","Spd":"2D6+5"}', NULL, NULL, '5D6+PE', '1D6', NULL, 'M.D.C. is 5D6 plus the P.E. number, +2D4 per level of experience; most also wear patchwork homespun armor of 40-70 M.D.C. with no environmental capabilities. On S.D.C. worlds: Hit Points 6D6 plus P.E., S.D.C. 6D6 plus skill bonuses, Natural A.R. 12. P.S. is equivalent to Robot Strength. Recovers 2D6+3 M.D.C. per day. I.S.P. is not printed.', NULL, 12, NULL, '+5 to save vs Horror Factor; +6 to save vs poison, disease and drugs. When highly motivated or fighting for its own life: +1 melee action/attack, +1 on initiative and +1 to parry or dodge. Attacks per melee as per Hand to Hand skill (rarely better than Basic); damage as per Robot P.S. or by weapon. Horror Factor 12 lasts only until one gets to know the Larmac. Vulnerabilities: -1 on initiative unless highly motivated, and always -3 to save vs illusions.', 'R.C.C. skills, in addition to O.C.C. skills: Cook, Land Navigation and Wilderness Survival, all at +20%, and W.P. Blunt. Experience table of the chosen O.C.C.; NPCs are level 1D6.', 'Nightvision 300 feet (91.5 m). Goes a week without food and four days without water before it suffers. The thick Mega-Damage hide and the blubber under it keep off desert sun and cold down to 40 degrees Fahrenheit below zero.', 'None; too lazy to study it, though fond of magic items', 'Rare. Roll percentile: 01-02 Master Psionic (select a Psionic O.C.C.), 03-07 Major Psionic, 08-15 Minor Psionic, 16-00 none. An estimated 25-30% are hooked on Psi-Cola (Psyscape p.84).', '6-7 feet tall (1.8 to 2.1 m)', '250 to 500 lbs (112.5 to 225 kg)', '5D6+90 years; physically mature by 17. Litters of 1D4+1 young after a 12 month pregnancy, until age 50', 'Came through the Saint Louis and Detroit-Windsor Rifts and spread across lower Canada, the Pecos Empire and the old Central and Eastern United States; prefers cities, slums and the ''Burbs, anywhere with saloons, gambling halls and nightlife, from the Mexican border to northern Canada', 'Anyone who tolerates their laziness; generally like humans, Floopers, D''norr Devilmen, Kraks and most easygoing people', 'The Coalition States, Federation of Magic, Greot Hunters and Vanguard Brawlers; they also dislike scholars, teachers, scientists, driven personalities, power-mongers, tyrants and slavers', 'Pick one Adventurer or Men at Arms O.C.C., typically Vagabond, Stoolie, Saddle Tramp, Barmaid (if female), Saloon Bum, Grunt (thug or muscleman), Pirate, Sailor, Highway Man, Gambler, Thief or Bandit. Only the most ambitious become a Sheriff''s Deputy, Merc Soldier, Pecos Raider, Professional Gambler, Trapper-Woodsman or Wilderness Scout. Most Men at Arms and all psionic O.C.C.s, the Mystic included, are closed to them (a Master Psionic result is the exception). Player characters start at level one. Equipment and money as per O.C.C., with a taste for blunt and heavy weapons. Most avoid cybernetics; human bionics must be modified; no Bio-Systems.', 'Big, heavy bipedal mammals that look like horned toads: rough, blotchy tan or greenish gray scaly hide, four small horns, a long muzzle of jagged teeth, and a build 40% to double over its best weight. Capable fighters and risk-taking gamblers, but famously lazy freeloaders who work only when a big score is promised; loyal to a friend once made. Coalition nicknames: Lazy Lizards, Lazy Lards, Lard Butts.', 'Rifts World Book 30: D-Bees of North America p.118-120'),
('loak', 'Loak', 'mutant', 'rifts', 1, 'Any, but tend to be Anarchist (40%), Aberrant (25%), Miscreant (12%) and Diabolic (10%)', '{"IQ":"2D6+5","ME":"3D6+5","MA":"2D6","PS":"3D6+9","PP":"3D6+3","PE":"3D6+3","PB":"2D4+1","Spd":"5D6+6"}', 'PEx2', '4D4x10+40', NULL, NULL, '1D4x10+ME', 'Hit Points are P.E. x2, +2D6 per level of experience. S.D.C. is 4D4x10+40. M.D.C. only through artificial armor or its own Bio-Armor (up to 120 M.D.C. per level). A.R. is 9+1D4 when not in Bio-Armor or other M.D.C. protection, so the A.R. column is left empty. P.P.E. is only what it captures and stores: up to 120 points per level on the stat block, while the P.P.E. Vampire power prints a reserve of 150 per level. I.S.P. is 1D4x10 plus the M.E. number and does NOT grow with experience (it steals more). Spd is 5D6+6 running, double swimming. P.S. is Augmented; in Bio-Armor it becomes Supernatural and Spd doubles. Regenerates 3D6 S.D.C. or Hit Points per hour.', NULL, 8, '{"attacks":5,"initiative":2,"strike":4,"parry":2,"dodge":2,"disarm":2,"roll":3,"pull_punch":4}', 'Five attacks per melee at level one, +1 at levels 3, 5, 7, 9, 11, 13 and 15, and +1 more when underwater. +4 on Perception Rolls. +2 to save vs psionic attacks (so needs 8 or higher), +2 vs magic, +2 vs drugs, poisons, toxins and disease, +4 vs Horror Factor; immune to possession and to a vampire''s bite. All in addition to attribute bonuses. Horror Factor is 8 for most people but 14 for psychics and practitioners of magic who know what a Loak is. Punch damage as per Augmented P.S., or Supernatural P.S. in Bio-Armor. Vulnerabilities: can learn only a tiny handful of skills, is driven by instinct to hunt and kill psychics, demons and magic users and cannot wholly stop, and has the social restraint of a tame tiger. Sensing is at -20% within two miles (3.2 km) of a ley line and fails on one.', 'R.C.C. skills: Dowsing (+15%), Language: four of choice (+30%), Land Navigation (+30%), Lore: Demon & Monster (+25%), Lore: Magic (+15%), Prowl (+15% on dry land, +25% underwater), Swimming 98%, Tailing (+20%), Tracking (people; +20%), Track Animals (+15%), Wilderness Survival (+30%), Wrestling, one Modern W.P. of choice. Secondary skills: three at level two, +1 at levels 4, 8, 10, 12 and 14. Sense Psychic and Magic Energy, base skill to track: 24% +4% per level (+20% with a recent trace of the quarry or while magic or psionics are in use). Bio-Armor is -15% to Acrobatics, Gymnastics, Climb, Prowl and Swim. Experience: Techno-Wizard table; NPCs are level 2D4.', 'Sense Psychic and Magic Energy: always on and free; notices and can trace mages, psychics, creatures of magic, supernatural beings and TW devices within 50 feet (15.2 m) +20 feet (6 m) per level, twice that for anything holding 250 or more P.P.E. or I.S.P., and ten times that while powers are in use. Psionic Void: a permanent free Mind Block, invisible to psychic and magical sensing and closed to Telepathy and Empathy unless it chooses. P.P.E. Vampire: needs 50 P.P.E. a week (1D6x10+30 is consumed every seven days) in place of food and water, taken doubled from prey it kills, from favored prey dying within 300 yards, or 1D4 at a time by torture; never from ley lines. I.S.P. Drain: once a melee, as one attack, takes 10 I.S.P. per level from one psychic within 10 feet (3 m) per level, held up to 30 minutes per level; the victim saves at -3, or Mind Blocks and loses only 2 per level. Spawning: every 2D10 years it must spend 120 stored P.P.E. on a cocoon that yields an adult clone in 1D4+1 days. Rejuvenation Cocoon (80 P.P.E.): restores Bio-Armor or all Hit Points and S.D.C.; 40 P.P.E. per limb, eye or organ regrown in 20 minutes; one kind of healing per cocoon. Bio-Armor: cocoon for 40 P.P.E. or 80 I.S.P., then 20 minutes and 10 P.P.E. or 20 I.S.P. per 100 M.D.C., plus 20 minutes and 30 P.P.E. or 60 I.S.P. per built-in weapon (one per arm); lasts one hour per level; shrugs off ordinary heat, cold and fire and halves M.D. cold and fire; leaps 15 feet (4.6 m) up and 20 feet (6.1 m) across. Breathes water and air, dives to 500 feet (152 m), survives depths to 1.6 miles (2.5 km). Sees through murky water, nightvision 300 feet (91.5 m), hearing and smell twice as sharp as a human''s.', 'None; never uses any magic item, Techno-Wizard items included', 'Starts with Detect Psionics (6) and Sense Evil (2), plus three powers chosen from the Physical and/or Sensitive categories; one more Physical or Sensitive power per level of experience. Typical picks: See Aura (6), See the Invisible (4), Presence Sense (4).', '6-8 feet (1.8 to 2.4 m) tall', '200 to 320 pounds (90 to 144 kg)', 'Estimated 6D6+110 years; does not seem to age, and reproduces only by the Spawning cocoon', 'North America only, along rivers and lakes: Minnesota, Wisconsin, Illinois, Michigan, the Ohio Valley and Magic Zone, the Mississippi River and southern Ontario', 'Depends on the situation; leans toward humans and D-Bees with no psychic or magic ability, and relates best to hunters and warriors (Men-at-Arms and Wilderness Scouts)', 'Psychics (Psi-Stalkers first, then Crazies, Cyber-Knights, Bursters, Zappers, Mind Bleeders, Mind Melters, Mystics, Psi-Goblins, Dragon-Cats), practitioners of magic (Witches and Necromancers first), creatures of magic (Dragons, Sphinx, Witchlings and Black Faeries first) and supernatural beings, evil ones before good', 'No O.C.C. is offered: a complete R.C.C. limited to its instinctive skills. Player characters start at level one; civilized Loaks work as bounty hunters, lawmen and slayers of mages, psychics, dragons and demons, while feral ones make NPC villains. Begins with no gear and no money; only a somewhat civilized Loak takes up the weapons and armor of men.', 'A hunter of mages, psychics and supernatural beings, made 30 or 40 years ago by Gene-Splicers out of an aquatic D-Bee. Tall, with translucent white or grey skin over cartilage, a fish-shaped head, shark teeth, gills, a dorsal fin and webbed fingers tipped with dagger claws. Cunning ambushers whose numbers multiply about every 15 years. Also called Mage Slayers, Mystic Hunters and Mage Assassins.', 'Rifts World Book 30: D-Bees of North America p.120-124'),
('loronoid', 'Loronoid', 'mutant', 'rifts', 1, 'Any, but the majority are Unprincipled (50%) and Anarchist (35%)', '{"IQ":"3D6+4","ME":"3D6+2","MA":"3D6+6","PS":"2D6+3","PP":"3D6+3","PE":"3D4+2","PB":"3D6+4","Spd":"3D6"}', 'PE', '3D6+10', NULL, '3D4', 'ME+2D4x10+10', 'Hit Points are the P.E. number, +1D6 per level of experience. Base S.D.C. is 3D6+10. M.D.C. by armor only. I.S.P. is the M.E. number plus 2D4x10+10, +2D6 per level of experience. Spd 3D6 is running; flying is 4D6+28, with a minimum flying speed of 30 mph (48 km).', NULL, NULL, '{"strike":1,"parry":2,"dodge":1,"pull_punch":2,"roll":3}', '+2 on Perception Rolls; the dodge is +4 when flying instead of +1. All in addition to attribute and skill bonuses. Attacks per melee as per Hand to Hand skill; damage as per combat skill or weapon. Horror Factor: not applicable. Vulnerabilities: easily distracted and often oblivious to its surroundings when fixed on details; treat M.E. as half for anything needing extended concentration or drudgery. Juveniles under 12 perform at half level and gain no experience.', 'R.C.C. skills: Detect Ambush (+15%), Detect Concealment (+20%), Language: Native Tongue: Spanish 98%, Language: Other: American and three of choice (+20%), Literacy: Native Tongue (Spanish) 98%, Literacy: Other: American and two of choice (+20%), Computer Hacking (+15%), Cryptography (+20%), Forgery (+15%), Gambling (Standard; +10%), Imitate Voices & Sounds (+16%), Intelligence (+20%), Land Navigation (+16%), Navigation (+15%), Prowl (+10%), Radio: Basic (+10%), Research (+10%), Sensory Equipment (+20%), Tailing (+10%), Wilderness Survival (+10%), W.P. Blunt or Knife, W.P. Energy Pistol or Energy Rifle, Hand to Hand: Basic (Expert for two Secondary Skills). Mathematics: Basic 98% and Mathematics: Advanced 78% +2% per level. R.C.C. Related Skills: none. Three Secondary Skills at level one, plus two at levels 3, 6, 9, 12 and 15.', 'Winged flier whose wings end in working hands; the bird feet grip, climb and hang. Suspended Animation: at will it drops into a death-like trance for 5 minutes per level, which also stretches its air and slows poison; a Paramedic is -35% and a Medical Doctor -25% to tell it is alive. Intuitive Math: knows the first 1D4x100+47 primes and Pi to 1D6x1,000 places, and computes with no paper or calculator at only -10%. Pattern Recognition: finds the order in jumbled words, numbers and pictures, reads maps without error and identifies places and vehicles from aerial photographs; its bonus is already inside the R.C.C. skill figures.', 'None; no magic potential', 'Master Psionic. At level one: Clairvoyance (4), Empathy (4), Mind Block Auto-Defense (special), Mind Wipe (special), Object Read (6), Remote Viewing (10), Sense Time (2), Telepathy (4), Total Recall (2), plus 1D4 additional Sensitive powers. One more Sensitive power at levels 3, 6, 9, 12 and 15. Super powers: Empathic Transmission at level 4, Hypnotic Suggestion at level 8, Psychic Omni-Sight at level 12.', '4 feet to 5 feet, 5 inches (1.2 to 1.6 m) tall', '60 to 90 pounds (27 to 40.5 kg)', '4D4+130 years; mature at 12; females lay 1D4 eggs twice a year, hatching after five months', 'South America, Central America, the Caribbean and, in the last six years, Mexico and the USA: rain forest treetops, mountains and coastlines, with clans along the Deep South coast and Dinosaur Swamp; northern ones migrate south in winter', 'None as such; they keep company with anyone who knows how to have fun', 'Their creators in South America (hated); feline D-Bees and monsters (feared); other more powerful avian races (wary); the Minions of Splugorth, other slavers and human supremacists (feared)', 'No O.C.C. at all: the race lives on its R.C.C. skills and powers. NPCs are level 1D6+1, player characters start at level one, on the Military Specialist experience table. Cybernetics, M.O.M., Juicer or any other augmentation costs every psionic power. Starts with a Vibro-Knife or Neural Mace, one weapon per W.P., 1D4+1 E-Clips, light or medium M.D.C. armor (patchwork is 32 to 55 M.D.C. and not environmental) and 3D4x100 credits. Slave market value 3D6x10,000 credits.', 'A short, bright-feathered humanoid macaw bred by Achilles in 75 P.A. as an intelligence analyst and written off when the breed proved too restless for desk work and deserted in droves. Also called Parrotoids, Macaw Men and Loafin'' Loros. A mutant, not a D-Bee, though it lets people think otherwise.', 'Rifts World Book 30: D-Bees of North America p.124-127'),
('lyvorrk', 'Lyvorrk', 'humanoid', 'rifts', 1, 'Any, but Anarchist (30%), Aberrant (10%), Diabolic (20%) and Miscreant (20%) are most common', '{"IQ":"3D6+2","ME":"4D6","MA":"3D6","PS":"3D6","PP":"3D6+2","PE":"5D6","PB":"2D6","Spd":"4D6"}', NULL, NULL, '2D6+PE', '2D6+12', 'MEx3', 'M.D.C. is 2D6 plus the P.E. number, +2D4 per level of experience. P.P.E. 2D6+12 is added to the P.P.E. base of one who becomes a practitioner of magic. I.S.P. starts at the M.E. number x3; the gain is printed as ''+10 I.S.P. per melee round'' (the class reads it as +10 per level). P.S. is Augmented. Recovers 1D6+6 M.D.C. every four hours, twice as long in cold weather.', NULL, 12, '{"initiative":2,"strike":3,"parry":4,"dodge":5,"damage":4,"roll":5,"pull_punch":3}', 'The +4 damage is S.D.C. damage. +3 to save vs psionics, +5 to save vs magic, +7 to save vs poison, drugs and disease, +18% to save vs coma, impervious to all snake venoms; all in addition to attribute and skill bonuses. Heat bonuses at 90-140 degrees Fahrenheit, added to the above: +1 attack per melee round, +2 on initiative, +1 to strike and parry, +2 to dodge. Attacks per melee as per Hand to Hand skill. Vulnerabilities: cold. Bonuses, number of attacks and Spd are halved after more than four hours below 50 degrees Fahrenheit or more than one hour below freezing, and return after two hours at 70 degrees or hotter; cold-based attacks do double damage. Cannot swim.', 'R.C.C. skills: Animal Husbandry (+15%, rodents and reptiles only), Barter (+10%), Camouflage (+20%), Climbing (+10%), Detect Concealment (+10%), Gemology (+15%), Hand to Hand: Assassin, Land Navigation (+10%), Language: Native (adopted) Tongue: Spanish, Language: Other of choice (+10%), Lore: D-Bees (+10%), Math: Basic (printed ''20%''), Mining (+10%), Prowl (+15%), Skin and Prepare Animal Hides (+10%), Tracking (people; +5%), Track & Trap Animals (+10%; +20% for small animals), Wilderness Survival (+20%), W.P. Knife, W.P. Targeting (Sling). R.C.C. Related: three at level one and one at levels 3, 5, 8, 10, 13 and 15 from Communications, Espionage (+5%), Medical, Physical, Pilot (basic vehicles only), Rogue (+5%; +10% to Seduction only), Science, Technical, Weapon Proficiencies and Wilderness. Two Secondary Skills at each of levels 1, 3, 8 and 12.', 'A desert reptile that gets by on a pint of water a month, drawing the rest from raw prey, and digests raw or spoiled meat and blood. Regrows a lost tail, foot, hand, toe or finger within 3D4+6 weeks, and a tongue or teeth within 1D4+4 weeks, but never an eye. The half-prehensile tail balances it and swats at foes behind or beside it. Burrows to stay warm, climbs well, hears keenly, has polarized vision that glare does not trouble, and is unharmed by heat up to 140 degrees Fahrenheit. All are insane to a degree (snake fixation, dread of water) and roll a further insanity on the race''s own table at levels 2, 4, 6, 8, 10, 12 and 14.', 'None, unless a Magic O.C.C. is selected', 'Major Psychic. Death Trance (1), Mind Block (4), Nightvision (4), Resist Fatigue (4), Resist Hunger (2), Resist Thirst (6), plus four special powers. 1. Psionic Empathy with Reptiles: reptiles, snakes and reptilian dinosaurs never attack a Lyvorrk and serve it as pets and guards. 2. Telepathy with Reptiles: as Telepathy, cold-blooded reptilian animals only, 1000 feet (305 m). 3. Control Reptiles (3 I.S.P.): 40 reptiles plus 10 per level, range 100 feet (30.5 m) per level, as long as desired; +10% to ride untamed dinosaur reptiles. 4. Control Intelligent Reptilian Life Forms (5 I.S.P.): one per level, range 50 feet (15.2 m), one minute per level; save vs psionic mind control at -2, or -5 for harmless questions.', '5-6 feet (1.5 to 1.8 m) tall; tail 6-7 feet (1.8 to 2.1 m) long', '140-170 pounds (63 to 76.5 kg)', '6D6+100 years; mature by 12; females lay 1D4 eggs after a three month pregnancy and the eggs take three more months to hatch', 'The American Southwest and the Mexican border', 'Their own kind and people subservient to them', 'Dislikes humans, mutants and most warm-blooded D-Bees, especially those resembling birds, rodents, felines and canines; other reptilian races are viewed with suspicion as potential rivals', 'One that keeps to the R.C.C. takes no O.C.C. and advances on the Psi-Stalker table. In place of the R.C.C. skills it may take the Body Doc O.C.C. or any Magic O.C.C. (favorites, most liked first: Shifter, then Necromancer, then Mystic, then Ley Line Walker, then Temporal Wizard, then Elemental Fusionist), using only that O.C.C.''s skills and its experience table. NPCs are level 2D4; player characters start at level one. R.C.C. gear includes a sling (1D6 S.D.C., doubled against vampires) with ordinary and silver shot, a silver dagger (1D6 S.D.C.), one M.D. weapon, grenades, 2D6+4 live poisonous snakes, a Gila Monster and 1D6+2 lizards, with 2D6x1000 credits and 1D6x100 in trade goods. Slave market value 1D4x10,000 credits.', 'A robed lizard man that looks like an upright velociraptor: saurian head with a spiny crest, long serpentine tail, clawed four-toed feet and human-like hands tipped with hooked nails. Cold-blooded, rare (perhaps 200-300 in North America) and living as hunter-scavengers, snake charmers, assassins or mages.', 'Rifts World Book 30: D-Bees of North America p.130-133'),
('malvoren', 'Malvoren', 'humanoid', 'rifts', 1, 'Any, but typically Aberrant (40%), Scrupulous (30%) or Principled (10%)', '{"IQ":"3D6","ME":"3D6+2","MA":"2D6","PS":"4D6+10","PP":"3D6+4","PE":"3D6+4","PB":"2D4","Spd":"3D6+4"}', 'PEx3', '3D4x10+20', NULL, '3D6x10+PE+3D6x10', '2D4x10+ME', 'Hit Points are P.E. x3, +2D6 per level of experience. S.D.C. is 3D4x10+20. M.D.C. only from armor and other M.D.C. machines and components merged into the body. P.P.E. is printed as 3D6x10 plus the P.E. number plus 3D6x10, +10 per level of experience; it returns at 10 per hour of sleep or meditation and cannot be drawn from any outside source. I.S.P. is 2D4x10 plus the M.E. number, +10 per level. Regenerates 1D6 Hit Points or S.D.C. per minute.', NULL, 10, '{"initiative":3,"strike":1,"parry":2,"dodge":2,"disarm":3,"entangle":2,"roll":1}', '+1 attack per melee, +2 to save vs disease and poison, +4 to save vs Horror Factor; all in addition to attribute and skill bonuses. Attacks per melee as per Hand to Hand skill; damage as per combat skill or Robot P.S. Horror Factor 10 applies only when one can tell what it is, none if sealed in environmental armor. Vulnerabilities: poor hearing and poor sight limited to the ultraviolet and infrared. P.P.E., S.D.C. and Hit Points spent on a meld do not come back until the item is un-melded. Over 50% machine (for example four limbs plus four cybernetics, a cyborg torso plus four cybernetics, 12 cybernetic items, or more than 12 weapons, cybernetics and armor in all) costs the non-Telemechanic powers and half the base I.S.P.', 'R.C.C. skills: Language: Native Tongue (Trade Four and Techno-Can at +30%), Literacy: Native Tongue (Trade Four and Techno-Can at +20%), Basic Electronics (+5%), Bioware Mechanics, Mathematics: Basic 98%, Mathematics: Advanced (+20%), Mechanical Engineering, Sensory Equipment (+5%), Vehicle Armorer (+20%), Weapon Systems (+15%), Weapons Engineer (+50%), Pilot: two of choice, W.P.: six of choice, Hand to Hand: Martial Arts (or Assassin if evil). R.C.C. Related: four at level one, plus one at levels 4, 8 and 12, from Communications, Electrical (Electrical Generation and Robot Electronics only), Espionage, Horsemanship, Mechanical (-5%), Military, Physical (except Acrobatics), Pilot (+10% on combat vehicles), Pilot Related, Rogue, Science (Chemistry and Astrophysics only), Technical (Language, Literacy, Computer Operation, Computer Programming and Jury-Rig only), W.P. and Wilderness (Land Navigation only). Secondary Skills: four, ''plus two additional at levels 3 and 9''.', 'Regrows a limb in 72 hours and, while melded with anything, cannot be transformed by any means. Fixes and upgrades weapons in half an Operator''s time; other machines take double time and come out poorly. Melds (each un-meld is one melee action): Weapons, 5 P.P.E. per item and one action: W.P. at six levels above its own, one extra attack and +3 to strike with it, fire-linking of several. Weapon Systems, 8 P.P.E. and two actions: runs them at 95% with +2 to strike. Armor, 10 P.P.E. and three actions: +20% damage capacity, armor penalties halved, and in a full suit P.S. counts as Robotic and blows do Mega-Damage. Cybernetics, 10 P.P.E. and one round, no surgery: 1D6 S.D.C. and 1D4 Hit Points per part, tripled (with time and P.P.E.) for a whole limb or torso frame. War Machines, 15 P.P.E. and one round: pilots it at four levels above its own. Non-Combat Machines, 25 P.P.E.: 2D6 S.D.C. and 1D6 Hit Points each way, level-one operation for 1D6 minutes per level. Power Weapons: 10 P.P.E. recharges a standard E-Clip, 15 a long one, 25 a canister or FSE cell and 40 a backpack cell, or 1 P.P.E. per die of damage fires a shot directly; a rail gun slug takes 1D6 of its own S.D.C. or Hit Points plus 10 P.P.E., a flechette or burst 3D6 plus 20 P.P.E.; such shots do full damage to anything magic or psionics can hurt. Heal and Repair: each S.D.C. mended costs 1 P.P.E. plus 1 of its own S.D.C. or Hit Points, each M.D.C. 5 P.P.E. plus 10, at one attack per 10 points, armor needing 20% left; melded items also mend 1D6 M.D.C. per hour between them.', 'None; no magic potential and cannot use Techno-Wizard items', 'Major Psychic. Telemechanics (10), Telemechanic Paralysis (20) and Telemechanic Mental Operation (12), usable only while melded with a weapon, armor or machine: half I.S.P. and double duration on a weapon, armor or combat sensors, power systems and computers, twice the I.S.P. and half duration on a non-combat machine. Also three powers from the Physical or Sensitive categories at each level of experience, starting at level one.', '7 feet, 4 inches to 8 feet, 8 inches (2.2 to 2.6 m) tall', '270 to 330 pounds (122 to 149 kg)', '4D6+135 years', 'Any, but prefers high-tech war-torn places; on Rifts Earth most often met in North America working for a mercenary company', 'Anyone, of any O.C.C. or race, who shows courage, honesty and honor, including Cyber-Knights, Blucies, Kraks and Lyn-Srial; knows other dimension-spanning beings such as Naruni, True Atlanteans and Temporal Raiders', 'The Splugorth, Sunaj and other Minions of Splugorth above all; also Dirari Ecto-Men, Ganka, Lanotaur Hunters, Loaks and anyone without a strong sense of honor', 'No O.C.C.: the race plays on its R.C.C. skills and melding powers alone. NPCs are level 2D6, player characters start at level one, on the Robot Pilot experience table. May begin in a light exoskeleton or in body armor of medium or heavy weight (a patchwork of plating is 6D6+52 M.D.C.), with three energy or heavy energy weapons and three spare clips each, two melee weapons, up to 1D4 melded cybernetic implants, one bionic limb carrying up to two weapon systems, and 6D6x1,000 credits. The Splugorth pay one million credits for one alive; other slavers 1D4x100,000.', 'A tall skinless warrior made of dark red muscle cords wound into a man''s shape, with small black eyes that glow red and then white in a fight and no visible mouth, nose or ears. The cords unwind to fuse with weapons, armor, bionics and war machines, so one is nearly always seen inside heavy armor and is often mistaken for a robot or cyborg. Honor-bound mercenaries hunted by the Splugorth.', 'Rifts World Book 30: D-Bees of North America p.138-142'),
('mraghiile-tree-man', 'M''Raghiile Tree Man', 'humanoid', 'rifts', 1, 'Any, but the majority are Principled (25%), Scrupulous (35%) or Unprincipled (20%)', '{"IQ":"3D6","ME":"2D6+3","MA":"3D6+3","PS":"1D6+5","PP":"3D6+10","PE":"3D6","PB":"3D6+3","Spd":"3D6"}', 'PE', '3D6+8', NULL, '4D6', NULL, 'Hit Points are the P.E. number, +1D4 per level of experience. S.D.C. is 3D6+8. M.D.C. by armor (typically patchwork with 2D6+17 M.D.C.) or magic only. Spd 3D6 is running on two legs: double on all fours, x10 leaping and swinging through the trees. I.S.P. is not printed (psionics as for humans).', NULL, NULL, '{"initiative":2,"strike":1,"automatic_dodge":4,"disarm":1,"entangle":2,"pull_punch":2,"roll":6}', '+2 to strike on leap attacks and kicks; +4 on sight, smell and hearing Perception Rolls. The automatic dodge is rolled as usual but uses up no melee attack. All in addition to attribute and skill bonuses. Attacks per melee as per Hand to Hand skill; damage as per combat skill. Horror Factor: not applicable. Vulnerabilities: small size, ordinary strength and a gentle nature.', 'R.C.C. skills: Acrobatics (+30%), Camouflage (+30%), Climbing (+35%), Escape Artist (printed ''25%''), Gymnastics (+25%), Hand to Hand: Basic for females and Expert for males, Identify Plants and Fruits (+25%), Land Navigation (+24%), Math: Basic (+10%), Prowl (+10%, and +20% more in trees), Swimming, Wilderness Survival (+30%), W.P. Paired Weapons, two Domestic skills and three W.P. Ancient Weapons of choice. Track by scent 57% +3% per level. Additional skills: level 2, two Language: Other (+20%); level 3, two Wilderness (+15%); level 4, two Communications (+10%); level 5, two Rogue (+5%; no tech skills, Seduction or Streetwise); level 7, two Technical; level 9, two Modern W.P. or two Piloting (basic vehicles only); level 11, two more Domestic or Technical.', 'Four hands: the feet are a second pair, all four are ambidextrous and count as Paired Weapons, striking or parrying in any mix, though one normally holds the body up. Contortionist: folds double, rolls into a ball, fights from any angle and slips through a 5 inch (13 cm) opening. Camouflage: striped fur whose hairs lift or lie flat to change the pattern. Prehensile tail: balances, hangs, carries small things and can wield a knife or club, or fire a handgun at -6 to strike. Acrobat: moves through the canopy as easily as walking, with Gymnastics and Acrobatics already counted in (add none of their bonuses), leaps doubled, falls halved, and no penalty to shoot or throw while leaping, swinging or hanging. Senses: 20-05 vision, nightvision 200 feet (61 m), Advanced Hearing and Advanced Smell.', 'None, unless a Magic O.C.C. is selected', 'Same probability of psionic abilities as a human; tends towards Sensitive and Physical powers', '3-4 feet (0.9 to 1.2 m) long, plus a tail as long as the body', '45-80 pounds (20 to 36 kg)', '2D4+34 years; mature by 12; one young (sometimes twins) after a 7 month gestation', 'The Sequoia forests of central and northern California, with scattered communities in the rainforests of Oregon, Washington, British Columbia and Dinosaur Swamp; wanderers anywhere in North America', 'Other tribal people, including traditional Native Americans, Psi-Stalkers, Druids and Wilderness Scouts; anyone who honors and respects their people and customs', 'Horune Pirates and other slaver races (hated); militant and aggressive people in general, including the Coalition Army and Simvan', 'Almost every one met away from home is a young wanderer on the R.C.C. skills with no O.C.C., advancing on the Wilderness Scout table. Each tribe''s one or two Shamans are instead a Healing or Plant Shaman (as the Native American ones in Spirit West) or an Elemental Fusionist, Mystic or Psychic filling that role, and play on that O.C.C.''s skills and powers in place of the R.C.C. list. NPCs are level 1D6; player characters start at level one. Gear: one weapon per W.P., a waterskin, a pocketed belt or bandoleer and non-environmental patchwork armor of 2D6+17 M.D.C.; no magic, TW or M.D.C. melee weapon to start. Cybernetics: none. Slave market value 3D4x1,000 credits.', 'A small, wiry tree-dweller, part cat and part monkey to look at: tan fur with black stripes, big yellow eyes, tufted lynx ears, a long snout, a whip tail with a tuft, and four limbs ending in hands of three fingers and two thumbs. Tribal, shy of outsiders, magic and machines alike. Also called Raghiile Climbers, Sequoia Men, Tiger-Squirrel Men and Roggies.', 'Rifts World Book 30: D-Bees of North America p.135-138'),
('nreta', 'N''reta', 'humanoid', 'rifts', 1, 'Any, but lean toward Principled (40%), Scrupulous (30%) and Unprincipled (15%)', '{"IQ":"3D6","ME":"2D6+8","MA":"3D6+3","PS":"3D6","PP":"3D6","PE":"2D6+3","PB":"2D6+3","Spd":"3D6"}', 'PE', '4D6+5', NULL, '2D4+4', NULL, 'Hit Points are the P.E. number, +2D4 per level of experience. S.D.C. is 4D6+5. No M.D.C. is printed. I.S.P. is not printed (psionics as for humans).', NULL, NULL, '{"initiative":1,"disarm":1,"pull_punch":1}', '+2 to save versus disease; the initiative bonus comes from the sense of smell. All in addition to attribute and skill bonuses. Attacks per melee as per the Hand to Hand skill of the chosen O.C.C.; damage as per combat skill, weapon or magic. Cannot bite: it has no teeth. Horror Factor: none. Vulnerabilities: the language barrier (without a translator or a sign reader it is down to pointing and pantomime), a diet limited to soft or ground food, and a trusting nature.', 'No R.C.C. skill list; skills come from the chosen O.C.C. Language: Native: N''retan 80% +2% per level, replacing the O.C.C.''s native language skill. All know the universal Sign Language. All understand Spanish and most (83%) American, but cannot physically speak most languages; they learn to understand or read them without penalty. Identify common and strong scents 80% +2% per level; identify specific odors 60% +2% per level; track by smell alone 60% +2% per level.', 'Nightvision to 300 feet (91 m) and ordinary human eyesight by day. A toothless insect eater that also takes soft fruit. The long sticky tongue is prehensile: besides catching food it can lift, hold or fetch a small item such as a key, card, pencil, disc, knife or derringer, and can push a button, type, turn a dial or throw a switch, but it cannot shoot or fight with what it holds. The nose is far keener than a human''s (figures under skills).', 'None, unless a Magic O.C.C. is chosen', 'The same probability of psionic abilities as a human; a Master Psychic may be a Mind Melter, Burster, Psi-Slinger, Zapper or other psionic O.C.C.', '5-6 feet (1.5 to 1.8 m) tall', '135-265 pounds (61 kg to 119 kg)', '3D6+60 years; mature by 13; females are fertile to about 45 and bear twins, one male and one female', 'Northern and central portions of the Mexican Frontier, almost always along rivers or lakes: the Mexican Empire, Ciudad Victoria, the San Marcos River and the Rio Bravo; further north along the Rio Grande, Red River and lower Mississippi, occasionally as far as the Chi-Town ''Burbs', 'Grackle Tooth, Kraks, Fingertooth Carpetbaggers, Fennodi, Cactus People, Floopers, Shapers, most humans, Psi-Stalkers and Tokanii; they enjoy the company of just about anybody', 'Vampires and other undead (all but the most evil N''retas, and except those living in the Mexican Empire); those near the coast or in the north distrust and pity the Coalition States and the Minions of Splugorth', 'Takes an O.C.C. 65% are Adventurers: commonest are Vagabond, Rogue Scientist, Preacher, Cowboy and Body Fixer, then Wilderness Scout, Trapper-Woodsman, Salvage Expert, Saloon Bum, Saddle Tramp, Rogue Scholar, Operator and City Rat. 25% are Men of Arms: Super Spy, Special Forces, Sheriff or Deputy, River Pirate, Robot Pilot, Privateer, Pirate Slaver, Pirate, Pecos Raider, Merchant Marine, Merc or Mercenary Soldier, Justice Ranger, Headhunter, Gunslinger, Gunfighter, Cyber-Knight, Combat Cyborg, Bounty Hunter, Highway Man or Bandit. About 5% take a Magic O.C.C. and 5% a Psychic one. Juicer and Crazy conversion fail on this race, the Dragon Juicer and Mega-Juicer excepted. NPCs are level 1D8; player characters start at level one. On top of O.C.C. gear each has a cross necklace and 1D4 wooden stakes, and about half of the travellers own a language translator. Slave market value 2D6x100 credits.', 'A stocky, furred biped with the long narrow snout of a giant anteater, a brush tail, a Mohawk-like crest, clear white eyes and dark purple fur over lilac skin. Settled in Mexico for generations, largely Christian, fond of human company and culture, and regarded there as neighbors. Also called Ritas, Nosey N''retas and Big Nosed Ritas.', 'Rifts World Book 30: D-Bees of North America p.146-149'),
('nuhr-dwarf', 'Nuhr Dwarf', 'humanoid', 'rifts', 1, 'Any, but lean toward Scrupulous (20%), Unprincipled (20%), Anarchist (20%) and Aberrant (10%)', '{"IQ":"3D6","ME":"2D6+3","MA":"1D6+5","PS":"3D6+10","PP":"3D6","PE":"3D6+5","PB":"2D6+2","Spd":"2D6"}', '2D6+PE', '5D6+5', NULL, '3D6', NULL, 'Hit Points are 2D6 plus the P.E. number, plus 1D6 per level of experience starting at level one (the page prints that gain as ''1D6 M.D.''). S.D.C. is 5D6+5 plus those gained from Physical skills. M.D.C. by M.D.C. body armor, magic armor or other external protection. P.S. is Augmented. I.S.P. is not printed (psionics as for humans).', NULL, NULL, '{"initiative":1,"strike":1,"pull_punch":4,"roll":2}', '+2 to save vs possession, +3 to save vs Horror Factor; the +2 is to roll with punch, fall or impact. All in addition to attribute and skill bonuses. Attacks per melee as per Hand to Hand skill; damage as per P.S., magic or Rune Weapon. Horror Factor: not applicable. Vulnerabilities: short height, and a reputation as pirates that makes many in North America leery.', 'R.C.C. skills, in addition to those of the chosen O.C.C.: Boat Building (+20%), Carpentry (+25%), General Repair & Maintenance (+15%), Leather Working (+10%), Math: Basic (+15%), Rope Works (+20%), Salvage (+20%), Swimming (+10%). +15% to any Mechanical skills. The chosen O.C.C.''s number of Secondary Skills is halved.', 'Keen eyesight that age never dulls, nightvision to 300 feet (91.5 m), Augmented P.S., and stamina such that it tires at a quarter of the human rate.', 'As per O.C.C., if applicable; about 10% are Nuhr Rune Makers and one or two percent Mystics', 'Same range of possibilities as humans; psionic O.C.C.s other than Mystic are not available', '4 feet to 4 feet, 6 inches (1.2 to 1.4 m) tall', '120 to 200 pounds (54 to 90 kg)', '6D6+120 years, females about 10 years longer; mature at 18; one young after an 11 month pregnancy, and only to the age of 35', 'The Lazlo, Montreal and Free Quebec area of eastern Canada, Michigan and the northeastern United States; Nuhr Pirates range up and down the Atlantic', 'Nothing formal; most get along well with humans and other civilized people', 'The Coalition States (particularly its Navy), Free Quebec, the Minions of Splugorth, the Horune, Bayou Ursines and other pirates', 'Takes an O.C.C. and uses its experience table. In theory any Men at Arms class, above all Merc Soldier, Grunt/Soldier, Military Specialist, Bandit, Thief, Bounty Hunter, Pirate and Sailor (robots, power armor and heavy vehicles are shunned), or any Adventurer and Scholar class, above all Operator and Vagabond (Carpenter). Magic classes are rare apart from the Nuhr Rune Maker (close to Mystic Russia''s Mystic Kuznya) and the Mystic; Techno-Wizardry and Eco-Magic are refused, and no psionic class but Mystic is open. NPCs are level 2D4; player characters start at level one. Each inherits two minor Rune Weapons and a suit of armor. Melee, by damage: 4D6 M.D. for a Rune Axe or Morning Star; 3D6 M.D. for a Large Sword or Ball and chain; 2D6 M.D. for a Bayonet, Cutlass or Short Sword; 1D6 M.D. for a Knife; 1D4 M.D. for a Grappling Hook and rope or a Hook with handle. Ranged: Rune Musket Pistol 4D6 M.D., 800 feet (244 m), 35 shots, 25 P.P.E. to reload; Rune Musket Rifle 6D6 M.D., 1600 feet (488 m), 50 shots, 40 P.P.E.; small Rune Pirate Ship Cannon 1D6x10+6 M.D., 3000 feet (914 m), 20 shots, 80 P.P.E.; with a P.S. under 26 every musket weapon is -3 to strike. Armor: Studded Leather 4D6+40 M.D.C., Leather and Chain Mail 1D4x10+45, Chain Mail 1D6x10+90. Slave market value 3D6x1,000 credits, double for skilled carpenters and builders, 3D4x10,000 for Rune Makers.', 'A Dwarf from a world of magic and roughly 18th century technology, whose craftsmen engrave runes into nearly every tool and weapon, muskets included. Builders, sailors and weaponsmiths; no more than 5000 exist, almost half of them at Queenston Harbour, where the Rhees Pirates have given the whole race a name for piracy. Also called Pirate Dwarves and Mystic Dwarves.', 'Rifts World Book 30: D-Bees of North America p.149-151'),
('obsedai', 'Obsedai', 'giant', 'rifts', 1, 'Any, but mostly Principled (48%), Scrupulous (30%), Unprincipled (10%) or Aberrant (8%)', '{"IQ":"2D6+4","ME":"2D6+4","MA":"2D6+2","PS":"3D6+20","PP":"3D6","PE":"2D6+12","PB":"2D4+1","Spd":"2D6+3"}', NULL, NULL, 'PEx10', '5D6+PE', NULL, 'M.D.C. is the P.E. number x10, +3D6 per level of experience. Stone Armor adds 120 M.D.C. per level of experience. In S.D.C. environments only: Hit Points are P.E. x4, +3D6 per level, with 1D4x100 S.D.C. and a Natural A.R. of 16. P.S. is Robotic, and Supernatural when enraged, in combat or in Stone Armor. Bio-regenerates 2D6 M.D.C. per hour, doubled for an hour of meditation. All stats and bonuses, Stone Armor included, are half for juveniles under the age of 200.', NULL, 12, '{"disarm":2,"pull_punch":3,"roll":4}', 'Impervious to poison and toxins, +2 to save vs airborne toxins, and +1 to save vs Horror Factor at levels 1, 3, 5, 7, 9, 13 and 15; all in addition to attribute and skill bonuses. In Stone Armor: +1 attack per melee, +3 to strike, +2 to parry and +5 to save vs Horror Factor, and Horror Factor becomes 16. Attacks per melee as per Hand to Hand skill; damage as per Robot or Supernatural P.S. or weapon. Vulnerabilities: looks, size and weight are a liability in towns; healing magic and healing psionics do nothing for it; the Stone to Flesh warlock spell fails but inflicts 1D6 M.D. per level of the caster.', 'R.C.C. skills: Language: Native Tongue (Obsedai) 98%, Language: American 80%, Language: Other: one of choice (+5%), Mathematics: Basic (+25%), Lore: Demon & Monster (+15%), Land Navigation (+10%), Sing (+10%), Law: General (+10%), Philosophy (+20%), Calligraphy (+10%), Camouflage (+15%), Physical Labor, Body Building, Excavation (+15%), Gemology (+20%), Mining (+15%), W.P.: three Ancient of choice, Hand to Hand: Expert (Martial Arts for one R.C.C. Related Skill). R.C.C. Related: six at level one, plus one at levels 3, 6, 9, 12 and 15, from Communications (Language and Literacy only), Domestic (Dance, Gardening, Play Musical Instrument; +5%), Espionage (Detect Ambush, Detect Concealment, Interrogation, Tracking, Wilderness Survival; +10%), Horsemanship (Exotic only; +5%), Medical (First Aid, Holistic Medicine; +5%), Military (Military Etiquette, Military Fortification, Trap/Mine Detection; +5%), Physical (Climbing, Juggling, Physical Labor), Pilot Related (Navigation; +5%), Rogue (Concealment, Imitate Voices and Sounds, Prowl, Tailing; +5%), Science (Anthropology, Astronomy and Navigation, Botany; +10%), Technical (Appraise Goods, Art, Breed Dogs, all Lore, Masonry, Recycling, Rope Works, Salvage, Ventriloquism, Whittling and Sculpting; +10%), W.P. (any except Dead Ball), Wilderness (any; +10%). Secondary Skills: none.', 'A silicon-based living being, no creature of magic, that must breathe, rest and eat: wood, limestone, granite and coal by preference, any rock at a pinch. Tires at a tenth of the human rate. Feels no pain; S.D.C. weapons, heat and cold cannot hurt it, and Mega-Damage fire and cold are halved. Stone Armor (Fury Armor): on going into a rage or a fight, plates of rock form from nowhere and lock onto the body, doubling its weight and adding half again to its size, and turning Robot P.S. and P.E. Supernatural (M.D.C. and bonuses under pools and bonuses); it lasts 20 minutes per level or until the anger passes. Never wears made armor or force fields.', 'None', 'None', 'Starts at 10 feet (3 m) and grows one foot for every 100 years of life; 50% larger in Stone Armor', 'Starts at 1,200 pounds (540 kg), plus 200 lbs (90 kg) per 100 years of life or foot in size; doubled in Stone Armor', '1D6x100+300 years; mature at 200; one young once every 1D4x10+50 years', 'Any mountainous region, most numerous in the Rocky Mountains and the Appalachian Mountains', 'Psi-Warriors, Cyber-Knights, Knights of the White Rose, Blucies and Lyn-Srial; warms to anyone good, compassionate and kind', 'Splugorth Slavers, Mystic Knights, the CS and all evil and cruel beings; dislikes robots, automatons and Golems; wary of Elementals, Warlocks and Elemental Fusionists; never trusts Anarchist, evil or erratic characters', 'No O.C.C.: it plays on the R.C.C. skills alone. NPCs are level 2D6, player characters start at level one, on the Combat Cyborg experience table. Cybernetics and bionics will not take. Its one possession is the stone weapon grown at its coming of age (see attacks), which has 200 M.D.C., is destroyed only if singled out, and takes 6D6+48 hours of fasting and meditation to regrow; goods worth 1D6x1,000 credits at most. Slave market value 3D6x100,000 credits.', 'A towering man of Mega-Damage rock with eyes that glow like magma, colored black, tan, brown or ash white by the stone it eats. Raised as both philosopher and warrior, it meditates for years at a stretch and is slow to anger, but cruelty, slavery or murder send it into a fury in which it sheathes itself in extra stone. Also called Stone Men, Hardbodies and Stone Fury.', 'Rifts World Book 30: D-Bees of North America p.151-154'),
('phlebus', 'Phlebus', 'humanoid', 'rifts', 1, 'Any, but lean toward Unprincipled (30%) and Anarchist (30%)', '{"IQ":"3D6","ME":"3D6","MA":"3D6+7","PS":"3D6","PP":"3D6+2","PE":"3D6","PB":"2D6+7","Spd":"3D6"}', 'PE', '2D6+15', NULL, '3D6', NULL, 'Hit Points are the P.E. number plus 1D6 per level of experience. S.D.C. 2D6+15. M.D.C. only by armor, force field or extraordinary means. Horror Factor: not applicable.', NULL, NULL, NULL, '+1 attack per melee, +1 to strike with thrown weapons, +5% to invoke trust/intimidate on top of any M.A. bonus, +6 to save vs Horror Factor (not against ghosts, Entities or places believed haunted, graveyards included). Attacks per melee as per Hand to Hand skill; damage by combat skill or weapon. Vulnerabilities: -5 to save vs Horror Factor against ghosts and Entities; arrogant and overconfident; -5 on initiative and Perception Rolls while performing.', 'R.C.C. skills whatever the O.C.C.: Disguise (+15%), Impersonation (+14%), Performance (+15%), Public Speaking (+25%), Seduction (+7%). Ambidextrous: W.P. Paired Weapons or Juggling (pick one), and +10% to Climbing, Concealment, Forgery, Juggling, Palming, Pick Locks, Pick Pockets and Rope Works where held. The O.C.C.''s Related and Secondary Skill counts are halved.', 'A gifted storyteller and performer who shrugs off most Horror Factor. Limited Shape-Shifting: one full melee round (15 seconds) of concentration remakes the face and recolors skin and hair; from age 25 the change costs a single melee action and can be done mid-conversation. The new look lasts as long as wanted. Ambidextrous: both hands are equally skilled.', 'None, unless a Magic O.C.C. is selected (rare)', 'Same probability of psionic powers as a human', '5 feet, 6 inches to 6 feet, 6 inches (1.7 to 2 m)', '100 to 220 pounds (45 to 99 kg)', '3D6+90 years; physical maturity at age 15', 'All over North America, especially boomtowns and traveling shows; thickest in the Midwest from Minnesota and Michigan to Lone Star', 'Gets along with other D-Bees and humans, and will keep company with anyone, demons included, who will listen and be entertained', 'The Coalition States, Free Quebec and others paranoid about shape-changing spies; Floopers, Kraks and Fingertooth Carpetbaggers are friendly competition; hates the Tundra Rangers of Canada, ghosts and Entities', 'Any O.C.C. Favorites: Bandit/Con Artist, Barmaid/Bartender, Bounty Hunter, City Rat, Deputy, Freelance Spy, Merc Soldier, Preacher, Rogue Scholar, Saloon Bum/Stoolie, Smuggler and Vagabond (entertainer). Equipment, money and cybernetics as per O.C.C. Player characters start at level one; NPCs are level 1D6. Slave market value 2D4x1,000 credits.', 'A D-Bee that passes for human apart from faintly pointed ears, known as Story Men or Shake Actors. Feared by the Coalition as likely infiltrators, yet most would rather act, juggle and tell tall tales. Bold before monsters but terrified of ghosts and haunted ground.', 'Rifts World Book 30: D-Bees of North America p.154-156'),
('posluznik', 'Posluznik', 'humanoid', 'rifts', 1, 'Any; Scrupulous (20%), Unprincipled (40%) and Anarchist (33%) are most common, evil is rare', '{"IQ":"3D6+2","ME":"3D6+6","MA":"4D6","PS":"3D6","PP":"3D6+5","PE":"2D6+4","PB":"2D6+2","Spd":"4D6"}', 'PE', '2D6+25', NULL, '2D6', 'MEx2', 'Hit Points are printed ''P.E. attribute number 1D6 per level of experience'' with no joining word, read as P.E. plus 1D6 per level. S.D.C. 2D6+25. I.S.P. is M.E. x2 plus 1D6 per level of experience. M.D.C. only via armor, force field or extraordinary means.', NULL, 10, '{"roll":2}', '+2 to roll with impact; +3 to save vs Horror Factor involving blood and gore in medical situations and crime scenes. Attacks per melee as per Hand to Hand skill; damage by combat skill or weapons. Vulnerabilities: none per se. Horror Factor 10 comes from the pallor, stitches, scars and height.', 'R.C.C. skills: Language: Native Tongue (Posluznik) 98%, Language: Other one of choice (+20%), Literacy: Native Tongue (+20%), Literacy: Other one of choice (+20%), Anthropology (+10%), Biology (+30%), Brewing (+10%), Chemistry (+15%), Field Surgery (+25%), Forensics (+10%), Holistic Medicine (+10%), Law, Mathematics: Basic, Medical Doctor (+15%), Mortuary Science (+25%; base 25% +5% per level), Sewing (professional quality; +20%), Xenology (+20%), W.P. Knife/Scalpel. Hand to Hand: Basic costs one R.C.C. Related Skill, Expert two; no advanced style ever. Four R.C.C. Related Skills at level one, +1 at levels 4, 8 and 12; four Secondary Skills, +1 at levels 4, 8 and 15.', 'Calm, with a gift for surgery and medicine. Embalming: a secret fluid keeps a harvested limb or organ viable indefinitely; once out of the fluid it dies in 2D6+6 minutes unless grafted to a living body. Transplants: 25% chance at level one, +5% per level, of having the right organ, tissue or limb ready for an emergency graft, provided the D-Bee has been harvesting parts (G.M.''s call).', 'None; no magical aptitude', 'Major Psychic. Every Posluznik has Bio-Regeneration (6), Deaden Pain (4), Empathy (4), Healing Touch (6), Object Read (6), Psychic Diagnosis (4), Psychic Surgery (14), See Aura (6), Sense Time (2), Sixth Sense (2) and Total Recall (2).', '6 feet, 2 inches to 8 feet (1.9 to 2.4 m)', '120 to 180 pounds (54 to 81 kg)', '2D6+90 years', 'Anywhere their services are needed, CS ''Burbs and battle fronts included', 'Welcome in nearly all circles; almost anyone who knows of them counts as an ally', 'Slavers, Splugorth, Gene-Splicers, Necromancers and religions that call them an abomination', 'Available O.C.C.s: none; the Posluznik R.C.C. is the whole class and uses the Body Fixer experience table. Player characters start at level one; NPCs are level 1D8+2. Starts with medical kit, scalpels, 1D4+2 knives (1D6 to 1D8 S.D.C. each), a Vibro-Knife, a laser scalpel, an energy pistol and 3D6x1,000 credits. Never accepts cybernetics or bionics. Slave market value 6D6x10,000.', 'Tall, pale, solemn D-Bees newly arrived from another dimension, nicknamed Undertakers and Puz Surgeons. Their skin is a map of stitches and scars worn as marks of service. They work as surgeons, morticians and forensic examiners, carrying preserved body parts to graft onto the injured and collecting more from the dead.', 'Rifts World Book 30: D-Bees of North America p.159-161'),
('roane-piper', 'Roane Piper', 'humanoid', 'rifts', 1, 'Any', '{"IQ":"3D6+1","ME":"3D6","MA":"3D6+6","PS":"3D4","PP":"3D6+3","PE":"3D4","PB":"2D6+3","Spd":"3D6"}', 'PE', '3D6+9', NULL, '1D4', NULL, 'Hit Points are the P.E. number plus 1D6 per level of experience. S.D.C. 3D6+9. No M.D.C. line is printed. I.S.P. only for the few with psionics: M.E. number +1D4, plus 1D4 per level. Horror Factor: not applicable.', NULL, NULL, '{"initiative":2}', '+2 on initiative and +2 to Perception Rolls. Attacks per melee as per Hand to Hand skill; damage by combat skill or weapon. Vulnerabilities: none per se.', 'A Roane not taking the Roane Musician O.C.C. gets Play Musical Instrument: Rinaluo (Roane pipe) and Sing at +15% each (professional quality) on top of O.C.C. skills; any further Play Musical Instrument skill gets at least +10%, even as a Secondary Skill. All Roane: Language: Other (+5%), Public Speaking (+5%), Impersonate Voices & Sounds (+10%), Palming (+10%), Computer Operation (+10%), and +5% to delicate-touch skills such as Demolitions, Pick Pockets, Pick Locks and Cardsharp.', 'Hearing of exceptional range and clarity, perfect pitch in song or on an instrument, a remarkably fine sense of touch, and can hold its breath for 10 minutes. Starts with a rinaluo, the many-keyed bent flute of its people; anyone lacking Roane hands plays it at -20%.', 'None; no magical aptitude', 'Roll percentile at creation: 01-06% one psionic ability, 07-10% two, 11-00% none. Powers come from the Healing or Sensitive categories. Minor Psychic.', '5 feet, 6 inches to 6 feet, 6 inches (1.7 to 2 m)', '115 to 190 pounds (52 to 86 kg)', '2D6+75 years; physical maturity at age 17', 'Anywhere in the Megaverse; on Rifts Earth chiefly North America, in the ''Burbs and the larger cities and towns', 'Humans and most other races, above all peoples with rich cultures who value music', 'The Splugorth, Sunaj, Naruni, Horune and anyone who trades in or uses slaves', 'About 45% are Roane Musicians (an O.C.C. printed with the race) and 20% thieves, spies or assassins: Super-Spy, Safecracker, Professional Thief, Master Assassin, Freelance Spy or Bounty Hunter. Otherwise virtually any O.C.C. except practitioners of magic, psychics and Juicers (M.O.M./Crazy conversion is possible but rare); never a full-conversion ''Borg. Equipment and money as per O.C.C.; non-musicians can earn 300 to 1,000 credits a week performing. Player characters start at level one; NPCs are level 2D4. Slave market value 4D6x10,000 credits.', 'Slender, salmon-skinned, long-faced D-Bees famed across the Megaverse as musicians, also called Pipers. Each hand has five fingers and two thumbs, and extra vocal cords let one harmonize with itself. Many who are not musicians by trade work as thieves, spies or killers behind a performer''s cover.', 'Rifts World Book 30: D-Bees of North America p.170-172'),
('septumbran-witch-wolf', 'Septumbran Witch Wolf', 'humanoid', 'rifts', 1, 'Any, though most are Anarchist (15%), Miscreant (35%), Diabolic (30%) or Aberrant (10%)', '{"IQ":"2D4+8","ME":"2D4+10","MA":"2D4+6","PS":"4D6+26","PP":"2D4+12","PE":"2D4+12","PB":"2D4+4","Spd":"2D4+8"}', 'PE', '1D6x10+40', NULL, '6D6', NULL, 'Hit Points are the P.E. number plus 2D6 per level of experience. S.D.C. 1D6x10+40. A.R. 15 applies to non-Mega-Damage attacks only. M.D.C. by armor or magic; patchwork armor has 3D6+28 M.D.C. P.P.E. 6D6, added to the amount a Magic O.C.C. provides. P.S. is Augmented. Bio-regenerates 1D4 Hit Points and 1D6 S.D.C. per hour.', 15, 13, '{"initiative":2,"strike":2}', '+1 attack per melee, and one more in any round the tail is used; +2 on initiative, +1 on Perception Rolls, +2 to strike, +5 to save vs Horror Factor, +2 to save vs possession, +1 to save vs magic, +20% to invoke fear or intimidation. Attacks as per the O.C.C.''s Hand to Hand skill; damage as per Hand to Hand and Augmented Strength, or by weapon or magic. A power punch does Mega-Damage and counts as two attacks. Borrowed Ash Pouch (while carried and kept safe by its owner): +2 to save vs magic, poison and disease, +10% to save vs Coma/Death. Vulnerabilities: taken for a werewolf or demon and usually attacked on sight; feared, never trusted; headstrong.', 'R.C.C. skills whatever the O.C.C.: Swim 72% (does not improve with experience), Native Language: Gobblely 96%, Demongogian (+20%), one language of choice (typically American; +15%). +10% to balance from the tail. Sense of smell: identify common and strong scents 80%, identify specific odors 65%, track by scent 60% (+10% if fairly fresh, +20% for blood).', 'Nightvision 600 feet (183 m) and 20/10 day vision. Prehensile Tail: thick and alligator-like, an aid to balance and swimming that can also lash a foe standing behind or beside the wolf. Deep Vision: sees the invisible, Entities and Astral beings and travelers included, and anyone hidden by Shadow Meld or Chameleon; ordinary concealment fails too, so Blend and Camouflage are at -30% against it. Smell: follows most scents from a mile (1.6 km) and blood from two miles (3.2 km), doubled downwind.', 'Only via a Magic O.C.C., which is common among them', 'Same probability of psionic abilities as a human', '7-9 feet (2.1 to 2.7 m)', '370-650 pounds on average (167 to 293 kg)', '3D6+62 years for males, 3D6+70 for females; physical maturity by age 11', 'The southern Old American Empire, thickest in the Northern Forests of Alabama and Mississippi and the Hamlet of Clavicle; thought to have arrived by a Rift at the ley line nexus near old Selma, Alabama', 'Keeps to its own kind but deals with evil and magical beings of all sorts and takes any willing underling: Brodkil, Black Faeries, Witchlings, Lesser Demons. Trades slaves with Horune Pirates and Splugorth Slavers; may serve a Neuron Beast, Demon Lord, dark god or Alien Intelligence if given rank', 'Cyber-Knights and other famous heroes; scorns humans and other D-Bees not tied to black magic; the Federation of Magic is a rival', 'In theory any O.C.C. Half practice magic: Shifter (25%), Witch (25%), Necromancer (20%), Ley Line Walker (5%), Mystic (5%), Mystic Knight (5%), Blood Priest (3%), Conjurer (2%), Elemental Fusionist (2%) or other (8%). Others favor River Pirate, Pirate Slaver, Pirate, Pecos Raider, Mercenary Soldier, Headhunter (not Momano), Bounty Hunter, Highway Man, Bandit, Wilderness Scout, Vagabond, Trapper-Woodsman and Professional Gambler; Dragon Juicer and Maxi-Juicer are super rare, psychic O.C.C.s uncommon. Equipment and money as per O.C.C., plus the Borrowed Ash Pouch. Player characters start at level one; NPCs are level 1D6+1. Slave market value 5D6x10,000, +40% for a mage, +60% for a psychic.', 'Huge wolf-headed D-Bees of the Deep South with black to dark grey fur, a mane and a furred serpentine tail, called Witch Wolves, Black Magic Wolves or Necro-Wolves. Mostly cruel slavers, man-eaters and dark sorcerers who honor their dead by carrying a pouch of family ashes. Fewer than a thousand are thought to exist.', 'Rifts World Book 30: D-Bees of North America p.177-179'),
('shale-bogle', 'Shale Bogle', 'humanoid', 'rifts', 1, 'Any, but tend to be Principled (20%), Scrupulous (25%), Unprincipled (20%) and Anarchist (30%)', '{"IQ":"2D6+3","ME":"2D6+2","MA":"2D6+6","PS":"2D6+10","PP":"2D6+4","PE":"2D6+6","PB":"1D6+4","Spd":"2D6+4"}', 'PE', '5D6+18', NULL, '3D6+3', NULL, 'Hit Points are the P.E. number plus 1D4+3 per level of experience. S.D.C. 5D6+18. A.R. 10 applies to non-Mega-Damage attacks only. No M.D.C. line is printed; hunters and adventurers wear patchwork armor of 4D6+28 M.D.C. Spd 2D6+4 is running and climbing; digging is half. Horror Factor 11 fades once one gets to know a Bogle.', 10, 11, '{"dodge":1,"roll":3}', '+1 to Perception Rolls when below ground, +1 to dodge, +3 to roll with impact, +1 to save vs magic, +2 to save vs poisons and drugs, +5 to save vs drugs, poisons and toxins in gaseous form (a successful save means no damage, penalty or ill effect). Attacks and damage as per Hand to Hand skill. Without tinted eye-wear in daylight: -1 on initiative and all combat bonuses. Vulnerabilities: few and primitive skills; taken for ghosts or demons and attacked or fled from; shy, skittish and unused to civilization.', 'R.C.C. skills: Begging (+10%), Climbing (+10%), Escape Artist (+20%), Excavation (+15%), Gardening (+15%), Land Navigation (+10%), Language: Native: Gobblely, Language: Other (typically American; +6%), Math: Basic (+5%), Mining (+10%), Palming (+10%), Spelunking (+10%), Swimming (+10%), Trap/Mine Detection (+20%), W.P. Blunt or W.P. Axe, one W.P. of choice (not Heavy Military or Heavy M.D. Weapons), Hand to Hand: Basic (Expert for two R.C.C. Related or three Secondary Skills). Underground Land Navigation 60% +3% per level. Four R.C.C. Related Skills at level one, +1 at levels 3, 6, 9 and 12, from Domestic (+5%), Medical (Brewing, First Aid, Holistic only), W.P. and Wilderness (+10%). Three Secondary Skills at levels 1, 4, 8 and 12; a worldly Bogle gets double at level one.', 'Nightvision 2000 feet (610 m), even in total darkness, but day sight of only 500 feet (152 m) and a need for tinted lenses. Smell, taste and hearing match a human''s. Holds its breath for 1D4 plus the P.E. number in minutes, gets by on 10% of the air a human uses, and breathes foul gases such as carbon dioxide and methane safely. Contortionist: pops shoulders and hips out of joint and folds its pliant bones to pass a gap of 6 inches by 1 foot (0.15 by 0.3 m). Digging: moves through loose earth mole-fashion at half running Spd, leaving no tunnel behind, or cuts rough tunnels and warrens at 10% of Spd. Always knows its depth and bearings underground.', 'One in 100 is a Mystic, with that O.C.C.''s usual psionic and spell casting abilities', 'Minor psionics only. Roll percentile: 01-20% minor psionics; 21-00% none.', '4-5 feet (1.2 to 1.5 m)', '90-130 pounds (40.5 to 58.5 kg)', '2D6+44 years; full maturity by age 13', 'Temperate climates: shale beds, rock quarries, caves, ruins, tunnel systems and abandoned mines, above all in Pennsylvania, New York, West Virginia, Kentucky and Tennessee. A rural village has 2D6+10 residents, a large one up to 6D6+20; thousands are rumored in Alaska', 'None per se; gets along well with humans, Grackle Tooth, Hobgoblins, Kraks, Larmac, Quick Flex Aliens and Vanguard Brawlers', 'None per se; other nocturnal and subterranean beings may be rivals, and it fears aggressive, violent people such as Psi-Goblins', 'No Available O.C.C.s line is printed; the entry is a full R.C.C. with its own R.C.C., Related and Secondary skills, and one in 100 is a Mystic. Player characters start at level one; NPCs are level 1D6. A hunter or adventurer has one weapon per W.P., 1D4 E-Clips, a folding shovel, patchwork armor of 4D6+28 M.D.C., sacks, backpack, blanket, canteen, tinted goggles and travel clothes; starts with no money. Knows nothing of cybernetics. Slave market value 2D4x1,000.', 'Small, bone-white, hairless D-Bees with huge dark eyes and a jagged fixed grin, also called Shale Ghosts, Quarry Goblins or Dirt Ghosts. They live a near Stone Age life in flimsy stacked warrens under quarries and old mines in the northeast, come out at night, and pilfer from travelers rather than fight. Gentle and playful among themselves, shy with strangers.', 'Rifts World Book 30: D-Bees of North America p.179-182'),
('shaper', 'Shaper', 'humanoid', 'rifts', 1, 'Any, but typically Scrupulous (32%), Unprincipled (25%) or Anarchist (25%)', '{"IQ":"1D4+4","ME":"1D6+1","MA":"4D6","PS":"2D6+3","PP":"3D6","PE":"4D6","PB":"3D6","Spd":"1D6x10"}', NULL, NULL, '1D6x10', '2D4x10', NULL, 'M.D.C. is 1D6x10, +1D6 per level of experience (the Vulnerabilities line gives a typical 30 to 90 points). Recovers 1D6 M.D.C. per hour. Horror Factor: none in its natural ape-like form, 2D4+7 when disguised as a ferocious beast or a frightening mix of creatures.', NULL, NULL, '{"initiative":2,"strike":1,"parry":1,"dodge":3,"pull_punch":2,"roll":3}', '+2 on initiative, +1 to strike and parry, +3 to dodge, +2 to pull punch, +3 to roll with impact, +5 to save vs poison, +3 to save vs drugs, +2 to save vs magic, +2 to save vs psionic attack. Attacks per melee as per Hand to Hand skill; damage via physical combat or weapon. Tail: -2 to fire a gun, -1 to strike with melee weapons. Vulnerabilities: clowning at the wrong moment can get it or a companion killed; looks fearsome but has little M.D.C. Silliness overload leaves it helpless for 3D4 minutes.', 'R.C.C. skills: Acrobatics (+5%), Begging (+20%), Brewing (+15%, professional quality), Brewing: Medicinal (+10%), Climbing (+30%), Cook (+10%, professional quality), Dance (+15%, professional quality), Gardening (+10%), Holistic Medicine (+5%), Juggling (+15%), Land Navigation (+10%), Language: Native (American is the adopted native tongue), Identify Fruits & Plants (+20%), Performance (+10%), Prowl (+10%), Sing (+10%, professional quality), Tailing (+5%), Wilderness Survival (+10%), Hand to Hand: Basic (cannot be changed). Scent recognition 50% +2% per level (+10% for a very common or well known smell). Four R.C.C. Related Skills at level one, +1 at levels 3, 6, 9 and 12, from Communications (+5%), Domestic (+10%), Horsemanship (General and Exotic only), Rogue, Technical (+5%), W.P. (any except heavy weapons) and Wilderness (+5%). Two Secondary Skills at levels 2, 6, 8 and 12.', 'Sharp eyes that see human colors clearly at double a human''s range, plus nightvision to 120 feet (36.5 m). A scavenger that eats nearly anything, craves sweets and resists poisons. Selective Metamorphosis: reshapes single body parts at will, blending features of up to 12 animals at once and adding as many as four extra limbs, wings, horns or antennae; every change costs one melee action, lasts as long as wanted, and can triple its height to 12 feet (3.6 m). Only animal features, never human, and never one whole animal. Borrowed shapes are cosmetic: no added attacks, M.D.C. or flight. Prehensile Tail: works doorknobs, buttons, simple machines, tools and weapons, and it climbs and swings by it. Enhanced Sense of Smell: picks out particular scents at 100 feet (30.5 m), +20 feet (6.1 m) per level.', 'None', 'None', 'Four feet (1.2 m); can shape-change to three times that (12 feet/3.6 m)', '60-100 pounds (27 to 45 kg)', '2D6+40 years in the wild, +20 years in an urban setting; physical maturity by age 10', 'Just about anywhere; most common in the American Southwest and Mexico, also Arzno, Kingsdale, MercTown, Ciudad Juarez, the Chi-Town ''Burbs, Old Bones and the Pirate Kingdom of Montreal', 'Gets along with most people; especially fond of humans, Phlebus, Fennodi, Fingertooth, Floopers, Kraks, Larmac and Grackletooth', 'None per se; dislikes anyone cruel, violent or a slaver', 'Available O.C.C.s: none; R.C.C. skills only, on the Elemental Fusionist experience table. Player characters start at level one; NPCs are level 1D6+1. Typical gear: pocket knife (1D4 S.D.C.), Vibro-Knife (1D6 M.D.), one weapon and a spare clip per W.P., light partial armor (2D6+20 M.D.C.), juggling balls, candy, tea things and oddments; 3D4x100 credits. No cybernetics or bionics, ever. Slave market value 6D6x100 credits.', 'Chimp-sized, fur-covered D-Bees with a hyena-like head, big ears, a wide grin and a monkey''s tail, nicknamed Monkey Morphs. Good-natured clowns who beg, juggle, cook and mind children, and who remake their bodies into absurd or alarming animal mash-ups for laughs or to scare off danger. They fight only when cornered or defending someone dear. A reprint from World Book One: Vampire Kingdoms.', 'Rifts World Book 30: D-Bees of North America p.182-185');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('shemarrian-warrior', 'Shemarrian Warrior', 'construct', 'rifts', 1, 'Starts out Unprincipled or Anarchist (pick one)', '{"IQ":"14","ME":"N/A","MA":"1D6","PS":"36","PP":"24","PE":"N/A","PB":"24","Spd":"132"}', NULL, NULL, '400', '0', NULL, 'A robot: fixed attributes, with M.E. and P.E. not applicable; I.Q. 14 is a Neural Intelligence, M.A. is ''effectively 1D6'', P.S. 36 is Robot P.S., Spd 132 is 90 mph (144 km). M.D.C. by location, Improved Shemarrian (introduced 105 P.A.): Rail Gun (1) 70*, Antennae (2) 10 each*, Hands (2) 18 each*, Upper Arms and Shoulders (2) 100 each, Forearms (2, plated) 80 each, Legs (2) 130 each, Head 90*, Protective Armored Headdress 75, Main Body 400 in armor or 250 without armor (rare). * needs a Called Shot and the attacker is still -3 to strike (-4 for antennae). Damage to the head comes off the headdress first. P.P.E. is printed as -0-. No Hit Points or S.D.C. are printed.', NULL, NULL, '{"attacks":8,"initiative":3,"strike":7,"parry":9,"dodge":9,"pull_punch":5,"roll":4}', 'Attacks per melee: eight (the whole count, not a bonus). Bonuses are in addition to attributes and skills: +3 initiative, +7 strike, +9 parry and dodge, +5 pull punch/claw, +4 roll with impact, critical strike on a natural 19 or 20, Paired Weapons. +6 to strike with the Shemarrian rail gun, +4 to strike with most other ranged weapons. Head destroyed: fights on blind with no bonuses to strike, parry or dodge. With antennae intact the penalty for being blind is only -3 to strike, parry and dodge. Horror Factor: not applicable. Vulnerabilities: none as such, beyond a poor grasp of people, society and emotions.', 'Robot programming, the same skill programs as the A-64 Master (Rifts Sourcebook One Revised and Expanded has the specifics): combat identification of known troops, robots, vehicles, animals and D-Bees; Basic Math (96%); all Military, Espionage and Scouting skills (+40%); W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy M.D. Weapons, W.P. Blunt, W.P. Chain, W.P. Knife, W.P. Sword, W.P. Paired Weapons; Hand to Hand: Martial Arts (8th level proficiency). Speaks, understands and reads the common languages and 30 pre-Rifts languages at 92%; speaks but cannot read Dragonese 98% and Splugorth 80%.', 'Runs at up to 90 mph (144 km) without ever tiring. Leaps roughly 20 feet (6 m) up or across, and 10 feet (3 m) farther from a run faster than 40 mph (64 km). Fake skin and hair make her pass for a living being. About half the body is bionic: limbs, a reinforced spine and shoulders, and armor. Each gauntleted forearm holds a laser and each hand has retractable claws. Carries every standard Archie robot feature plus passive nightvision and thermal imaging, each to 2000 feet (610 m), and an ultraviolet targeting laser with a 6000 foot (1828 m) reach. Two antennae (three on officers) work as motion and heat detectors and as feelers: they warn of any attack from the rear, count who is behind or beside her inside 20 feet (6.1 m) and whether they approach, and read temperature (to within 1D4 degrees), heat and cold sources, wind, humidity, altitude and travel speed. When the main body is destroyed she does not explode; the insides melt into dark green ooze.', 'None', 'None', '8 feet (2.4 m)', '900 pounds (405 kg)', 'Not alive; an undamaged unit can run for decades, its nuclear power supply replaced or recharged every 20 years or so', 'Mainly the Atlantic Northeast from West Virginia to Newfoundland, west to the Appalachian Mountains; now and then anywhere in North America', 'None as such; respected by the East Coast people they protect. Faerie Bot D-Bees who have met them know what they are and keep it secret.', 'Minions of Splugorth, Horune Pirates and slavers in general; wary of Free Quebec and CS soldiers; distrusts magic and its users', 'Available O.C.C.s: none. Playable only if the Game Master allows it, since the race was written as NPCs; a player character starts at level one on the Dragon Hatchling experience table. Archie tracks and records every unit. Standard gear: a Vibro-Sword (2D6 M.D.) and Vibro-Knife (1D6 M.D.), an energy rifle and an energy pistol with 1D6 E-Clips apiece, backpack, large sack, belts, cloak, 2D6x1,000 credits, and the Shemarrian Rail Gun: 2D6x10 M.D. a round, one round per attack, 6000 feet (1828 m), 12 rounds in the gun (hand reload 1D4+3 a melee) or an 820 round belt drum, +2 to strike. The gun blows up for 5D6 M.D. within five feet (1.5 m) if its owner dies or an outsider tampers with it. None has ever been enslaved; the slave market would pay 4D6x10,000 credits or more for one.', 'Eight foot androids built by Archie Three and Hagan Lonovich to pass as an alien race of warrior women, half flesh and half machine. Proud and blunt, they hunt slavers and fight the Splugorth''s forces along the East Coast. This entry is a reprint; the race first appeared in Rifts Sourcebook One.', 'Rifts World Book 30: D-Bees of North America p.185-188'),
('slurmph', 'Slurmph', 'humanoid', 'rifts', 1, 'Any, but gravitate toward Scrupulous (35%), Unprincipled (25%), Anarchist (10%) or Aberrant (10%)', '{"IQ":"2D6+5","ME":"3D6+3","MA":"2D6+3","PS":"3D6+7","PP":"3D6+3","PE":"3D6+3","PB":"1D4","Spd":"2D6+3"}', NULL, NULL, 'PEx3', '4D6', 'ME+2D6+6', 'M.D.C. is the P.E. number x3, plus 1D6 per level of experience. I.S.P. is the M.E. number +2D6+6 to start, plus 1D6+1 per level. It can ooze into a suit of armor for more protection at a 20% cut to its speed. Regenerates 1D6+2 M.D.C. per hour; lost limbs regrow within 2D4+4 days.', NULL, 9, '{"dodge":1,"pull_punch":2,"roll":3}', 'In addition to attributes and skills: +2 to strike with slime attacks, +1 dodge, +2 pull punch, +3 roll with impact, +4 to save vs drugs and poison, +2 to save vs Horror Factor, impervious to disease; cannot be pinned, crushed, held, handcuffed or chained. Horror/Disgust Factor is 13 the first time one is met up close. Attacks and damage as per Hand to Hand skill, weapon or psionics. Blunt attacks do half damage. Vulnerabilities: salt burns like acid, 1D6 M.D. per ounce and then 1D4 M.D. for 2D4 melee rounds or until washed off (saltwater only irritates). Must submerge in water one hour a week; each week missed is -10% to Spd, P.E., M.D.C. and appetite and -1 attack per melee, with combat bonuses halved after the second week, and recovery takes one unbroken soak of two hours per week missed. Its mucus trail gives trackers +15% (also +15% for tracking by scent alone).', 'Whatever the O.C.C.: Botany, Gardening, Identify Plants & Fruits and Swimming, each +20%; Escape Artist +10%; +10% to skills involving plants, food and preparation (Brewing, Brewing: Medicinal, Cooking, Holistic Medicine, Preserve Food), on top of any O.C.C. bonus. The number of Secondary Skills is halved.', 'A coat of slime makes it nearly impossible to grip and shields the skin against sun, radiation, heat and cold. A natural swimmer that holds its breath one minute per point of P.E. and withstands depths to 600 feet (183 m). Malleable body: flattens to a tenth of its girth and squeezes through gaps of six inches (0.15 m) or more in 1D6+1 melee rounds. Eyeless multi-optic sight: infrared, ultraviolet and thermal vision, and it sees magic energy and living auras for free. Mute; speaks by telepathy out to 500 feet (152 m) in any language at no I.S.P. cost, while actual mind reading costs and reaches as usual. Slime attacks: a flung glob blinds a target until 1D4+1 actions are spent wiping it off (Horror Factor 10 for the squeamish, no damage); a slip track, 3 feet (0.9 m) square per action, drops anyone crossing faster than Spd 8 on a roll of 01-82% and costs drivers -20% to piloting (hover vehicles exempt); a slimed melee weapon is dropped on a strike roll of 8 or less, a slimed gun is -2 to strike, and cleaning an object takes 2D4+5 melee actions, or half that with water.', 'None, unless a Magic O.C.C. is selected (rare)', 'Major Psychic. Meditation, See Aura (no I.S.P. cost), See the Invisible (4), Sense Time (2), Telepathy (4), Psychic Diagnosis (4, plant-life only), and one Sensitive power of choice.', '6-7 feet (1.8 to 2.1 m) tall', '170-350 pounds (77 to 158 kg)', '2D6+62 years; hermaphroditic, breeding about every three years, 2D4 live young after three months, mature within 1D4+3 years', 'Anywhere in North America; most common in the old Midwestern States, the Ohio River Valley, the Great Lakes region (Wisconsin, Illinois, Michigan, Ohio, Ontario) and Mexico. Driven out of southern Wisconsin, Iowa, Missouri and Arkansas by the CS.', 'Often found with Idie Swamp Men, Larmac and occasionally a Butter Troll; likeable enough to befriend almost anyone', 'The Coalition Army, which has killed hundreds of thousands of them over the last 35 years; Slurmphs hate and fear the CS', 'In theory any O.C.C. except Robot Pilot and any that receives cybernetic or bionic parts; it cannot be augmented at all. Most pick Adventurer and Scholar classes: Vagabond (farmer, rancher, explorer, laborer, wanderer), Wilderness Scout, Salvage Expert, Rogue Scientist or Rogue Scholar, Barkeep/Barmaid or Saloon Bum, Grunt or Mercenary Soldier. Roughly one in a million studies magic, and none becomes a psychic class such as Burster or Mind Melter. NPCs are level 1D10; player characters begin at first level. Equipment and money as per O.C.C. Slave market value 3D4x1,000 credits as farmers, 1D4x1,000 as labor or waste management.', 'The Slug Men: fat, eyeless, slime-coated D-Bees on two stumpy legs with mitten hands and a vertical slit for a mouth. Repulsive to look at and smell, yet cheerful, generous and hard working, they are gifted farmers and brewers who eat nearly anything and get drunk on a couple of beers.', 'Rifts World Book 30: D-Bees of North America p.190-193'),
('spinne', 'Spinne', 'alien', 'rifts', 1, 'Any, though a majority are Principled (32%), Scrupulous (43%) or Aberrant (12%)', '{"IQ":"3D6+6","ME":"3D6","MA":"2D6","PS":"3D6+8","PP":"2D6+9","PE":"4D6+2","PB":"2D4","Spd":"3D6"}', 'PE', '3D6x10', NULL, '1D6', NULL, 'TWO BLOODLINES; the rolled figures in this row (attributes, S.D.C., combat) are the STARKE (Engineers & Artists). Starke: I.Q. 3D6+6, M.E. 3D6, M.A. 2D6, P.S. 3D6+8, P.P. 2D6+9, P.E. 4D6+2, P.B. 2D4, Spd 3D6 running, +6 climbing; Hit Points P.E. plus 2D6 per level; Base S.D.C. 3D6x10. SCHNELLIG (Warriors & Spies): I.Q. 2D6+6, M.E. 3D6, M.A. 2D6, P.S. 3D6+3, P.P. 3D6+12, P.E. 4D6+4, P.B. 2D4, Spd 5D6 running, +10 climbing; Hit Points P.E. plus 1D6 per level; Base S.D.C. 2D6x10. An S.D.C. being that cannot wear armor; protection is a Spinne force field (Light 40 M.D.C., Medium 80, Heavy 160, Super-Heavy 250), belt or web-gear mounted.', NULL, 13, '{"attacks":1,"initiative":4,"perception":3,"parry":2,"dodge":2,"roll":2}', 'In addition to attributes and skills. Starke (the combat figures stored): +1 melee attack, +4 initiative, +3 Perception Rolls, +2 parry and dodge, +2 roll with impact, W.P. Paired Weapons. Schnellig: +1 melee attack, +6 initiative, +2 Perception Rolls, +2 strike, +3 parry, +1 dodge, +2 disarm, +4 entangle, +5 pull punch, +2 roll with impact, W.P. Paired Weapons, +2 to save vs Horror Factor. Attacks per melee as per Hand to Hand plus bonuses. Fighting blind or against an invisible foe is only -3. Vulnerabilities: Dehydration - needs six quarts (5.6 liters) of water and three liquid meals a day or bonuses and attacks are halved; after 24 hours without liquids it loses 25% of Hit Points, then 10% every 12 hours until death. Chemical Sensitivity - -2 to save vs gas, contact or ingested poison (alcohol included), with 50% more damage and 50% longer effects. Partial Nudity - a garment over torso and arms halves all sensory bonuses and ranges, partial hard armor cuts them 75%, a full environmental suit removes them. Horror Factor 13; those with Phobia: Spiders will not go near.', 'Both bloodlines: natural Climbing 80%/70% (+10% on a silk drag line; halved on super-smooth surfaces, with no drag line bonus); stealth as Prowl 60%, or 85% when trying to hide; +10% to skills needing a delicate touch. Motion sensing: Track 45% +5% per level (+20% if the target is larger than a human), Estimate distance 50% +5%, Estimate direction and speed 45% +5%, Estimate location 45% +5%. Touch: Recognize and locate changes in surface 70% +4%, ID fabric and materials 60% +4%, Measure temperature 60% +4%. Smell: Recognize specific odors 70% +3% (+10% common odors), Recognize poison/toxin 50% +4%, Recognize person 50% +4%, Track by scent 40% +4%. Starke: Architecture, Civil Engineering and Carpentry & Construction 85% +2% per level, +10% on Technical and Science skills, Play Musical Instrument: Stringed 85%, Recognize voice and sound 40% +5% per level. Schnellig: Dance 90%; Tunnelers have Underground sense of direction 70% +2% per level.', 'Four arms, fully ambidextrous. Body hairs sense all motion in a full circle out to 75 feet (22.9 m), so nothing short of Invisibility: Superior can creep up on one. Keen touch, and scent good to 100 feet (30.5 m). Perfect time sense. Silk from forearm glands: a single thread holds 20 pounds (9 kg) per point of the spinner''s P.E. and has 40 S.D.C.; a sticky line can be cast 50 feet (15.2 m); a thrown net costs its target one attack, -2 initiative, -3 strike, parry and dodge and half speed, stacking with more nets. A loose net takes 1D4 melee rounds to shed, or a Vibro-Blade or Augmented P.S. 17; a secured one needs P.S. 50 (34 Augmented, 26 Robotic, 18 Supernatural). A net costs three attacks, a line two, a thread one; hourly output is ten nets and 40 lines, or 400 threads, and three times that per day. Starke only: nearsighted but hearing reaches 350 feet (107 m) for normal speech (thirty decibels), 150 feet (45.7 m) for ten decibels and 75 feet (22.9 m) for a single decibel. Schnellig only: reads a face a mile (1.6 km) off, nightvision 3000 feet (914 m), infrared and ultraviolet sight, thermal vision 1000 feet (305 m); plus ONE of Jumper (leaps P.S. x10 feet across and P.S. x6 feet up, harmless falls of twice the leap, automatic dodge at +3) or Tunneler (digs 50 feet (15.2 m) a melee round in dirt, 20 in sand, 12 in packed earth, 2 in stone; safe tunnels at a tenth of that).', 'None known; magic O.C.C.s are not available', 'None; no psychic potential', 'Starke: 6 to 9 feet (1.8 to 2.7 m) for males, about one foot (0.3 m) more for females. Schnellig: 5 feet, 6 inches to 8 feet (1.7 to 2.4 m) for males, six inches (0.15 m) more for females.', 'Starke: 200 to 280 pounds (90 to 126 kg). Schnellig: 140 to 180 pounds (63 to 81 kg).', '4D6+62 years', 'Anywhere; a Megaversal race also common to North America. At least 2,500 on Earth and 1000 in North America, with 100 in Lazlo and 50 in New Lazlo.', 'Individuals ally with open-minded, D-Bee-accepting societies such as Lazlo or New Lazlo', 'D-Bee haters and slavers; wary of the Coalition States as a military power while respecting its efficiency; the Chasseur Vert, their ancient rivals', 'Any O.C.C. except psionic and magic ones. Starke lean to constructive classes: Operator, Rogue Scientist, Rogue Scholar, Vagabond Inventor/Builder. Schnellig lean to Men at Arms and Wilderness classes, especially Bounty Hunter, Special Forces, Assassin, Ranger and Wilderness Scout. The player or GM picks one bloodline and uses its figures. NPCs are level 2D4; player characters begin at first level. No cybernetics or bionics. Equipment and money as per O.C.C. Slave market value 3D4x2,000 credits for a Schnellig, 3D6x3,000 for a Starke engineer.', 'Spider Men: four-armed humanoid arachnids in a matte black, fuzz-covered exoskeleton with two large eyes ringed by six small ones and folding fanged mandibles. Regimented, lawful and aloof, with a culture oddly like the NGR''s. The tall Starke are engineers, artists and musicians; the smaller, faster Schnellig are warriors and spies. They feed on the blood and liquefied organs of herd animals.', 'Rifts World Book 30: D-Bees of North America p.193-198'),
('squilb', 'Squilb', 'humanoid', 'rifts', 1, 'Any, but lean toward Principled (30%), Scrupulous (40%) and Unprincipled (20%)', '{"IQ":"3D6","ME":"3D6","MA":"3D6+6","PS":"3D6+9","PP":"2D6+6","PE":"3D6+4","PB":"2D6+2","Spd":"3D6+6"}', 'PEx2', '1D6x10+16', NULL, '2D6', 'ME+2D6', 'Hit Points are the P.E. number x2, plus 1D6 per level of experience. S.D.C. 1D6x10+16. I.S.P. is the M.E. number +2D6, plus 1D6 per level.', NULL, NULL, '{"attacks":1,"initiative":2,"strike":1,"parry":1,"disarm":2,"pull_punch":3,"roll":2}', 'In addition to attributes and skills: +1 attack per melee round, +2 initiative, +1 strike and parry, +2 disarm, +3 pull punch, +2 roll with impact, +1 to save vs Horror Factor, +5 to save vs demonic possession. Attacks as per Hand to Hand skill; damage as per combat skill, weapon or P.S. Horror Factor: not applicable. After Hidden Strength ends, combat bonuses are halved for three hours. Vulnerabilities: none as such, beyond the drawbacks of an obsession with duty.', '+10% to Domestic skills, in addition to any O.C.C. bonuses.', 'Nightvision 200 feet (61 m), exceptional hearing and fast reflexes. Hidden Strength: under stress its P.S. becomes the equivalent of Robot Strength and it deals limited Mega-Damage (Rifts Ultimate Edition p.285) for 2 minutes +1 minute per level; usable twice a day, with one more daily use gained at each of levels 2, 5, 8 and 12, and followed by three hours of exhaustion. Empathic Link: after more than six months serving one person it senses that master''s mood, health, danger and rough location, and how pleased the master is with it.', 'None, unless a Magic O.C.C. is selected (rare)', 'Minor Psychic. Two powers of choice from the Sensitive category.', '7-9 feet (2.1 to 2.7 m) tall', '300-500 pounds (135 to 225 kg)', '4D6+100 years; physically mature by 16', 'Lone individuals and groups across the continent; largely driven from the Midwest and Domain of Man by the CS, and most numerous in the New West, American Southwest, southern Canada and northern Mexico', 'Gets along with most races; drawn to Glitter Boys, Cyber-Knights, Justice Rangers, Reid''s Rangers, Blucies, Malvoren, and heroes or leaders with a noble cause', 'All demons, tyrants, slavers and evildoers, the Brodkil, Thornhead Demons and Neuron Beasts most of all; also dislikes Loaks, Ganka, Lanotaur Hunters, Witchlings, Witch Wolves, Black Faeries, Simvan, Worm Wraiths, the undead and the Minions of Splugorth. Opposes the Coalition leadership rather than all its citizens.', 'Nearly any O.C.C. without human augmentation (no Cyborgs, Juicers or Crazies). Favorites are combat classes: every kind of Soldier, Merc Soldier, Commando, Cyber-Knight and Squire of the White Rose, then Operator, Body Fixer, Wilderness Scout and Vagabond, with the odd Elemental Fusionist or Mystic. NPCs are level 1D6; player characters begin at first level. Equipment by O.C.C., pole arms and spears being favorites; money by O.C.C., with 1D4x1,000 credits of trade goods on top. Cybernetics are possible but Bio-Systems are preferred. Slave market value 3D6x1,000 credits.', 'The Bronze Squires: big, muscular humanoids with wrinkled raisin-like skin of gold, red or dark brown, small dark eyes and a braid growing from the base of the skull. Selfless and honest, they attach themselves to a worthy leader or cause and serve it as lawmen, knights and protectors, leaving any master who misuses them.', 'Rifts World Book 30: D-Bees of North America p.198-200'),
('swamp-sludger', 'Swamp-Sludger', 'humanoid', 'rifts', 1, 'Any, typically Principled (20%), Scrupulous (20%), Unprincipled (20%) and Anarchist (25%); those who turn evil are usually Diabolic or Miscreant', '{"IQ":"1D6+2","ME":"2D6+3","MA":"1D6+8","PS":"3D6+8","PP":"2D6+7","PE":"2D6+8","PB":"2D6","Spd":"4D6"}', NULL, NULL, 'PE', '6D6', 'MEx2', 'A lesser Mega-Damage creature: M.D.C. is the P.E. number, +1D6 per level of experience. Partial armor of 4D6+28 M.D.C. is the usual issue, though most wear little. I.S.P. is M.E. x2, plus 1D6 per level. Spd 4D6 is on land; double when swimming. Bio-regenerates 2D6 M.D.C. every 24 hours.', NULL, 12, '{"attacks":2,"initiative":2,"strike":1,"parry":1,"dodge":2,"pull_punch":3,"roll":3}', 'Attacks per melee: two plus those from hand to hand. In addition to attribute bonuses: +2 initiative, +1 strike and parry, +2 dodge, +3 pull punch, +3 roll with impact, +3 to save vs disease and poisons. Damage as per P.S. or weapon. Vulnerabilities: none as such, other than low I.Q. and a lack of social skills.', 'R.C.C. skills: Climbing (+5%), Camouflage (+5%), Concealment (+16%), Detect Concealment (+5%), Fish (+10%), Hand to Hand: Basic, Identify Plants & Fruit (+10%), Land Navigation (+15%, undersea too), Language: Native Tongue: Gobblely, Language: Other of choice (+10%), Palming (+10%), Pick Pockets (+5%), Prowl (+5%), Swimming (+20%), Track Animals, Wilderness Survival (+20%), two W.P. Ancient of choice. Related skills: two at each of levels 3, 7 and 11 from Domestic (+5%), Horsemanship (General or Exotic), Physical, Piloting (simple vehicles), Rogue (+5%), Science (Math only), Technical or Ancient W.P.s. Secondary skills: three at level one, one more at levels 4, 8 and 12.', 'At home in the water: stays under for 10 minutes plus one per point of P.E. and dives as deep as 300 feet (90 m). Works in salt water but lives in fresh. Sharp eyes by day and nightvision reaching 1000 feet (305 m). Slowly heals its own Mega-Damage hide.', 'None', 'Major Psionic. Presence Sense (4), Sixth Sense (2), Sense Evil (2), Empathy (4), Resist Hunger (4), Resist Fatigue (4), Mind Block (4).', '5-6 feet (1.5 to 1.8 m) tall', '140-200 pounds (63 to 90 kg)', '4D6+72 years; mature by age 12; lays 1D6 eggs', 'Marshlands, bayous and everglades of the South, and parts of Michigan and Ontario; alone, in groups of 1D4+1, or clans of rarely more than 30', 'None as such; may befriend anyone who shows kindness or fights a common enemy', 'Coalition and Free Quebec soldiers, who attack them on sight; other dangerous humanoids and predators', 'Available O.C.C.s: none; the race is its own class and uses the Wilderness Scout experience table. NPCs are level 1D4+1. Starts with partial armor (4D6+28 M.D.C.), a hunting knife (1D6 S.D.C.) and a Vibro-Knife (1D6 M.D.) in a scabbard, an ammo-belt and holster, loincloth, waterskin, large sack and 1D6x100 credits. No cybernetics to start. Slave market value 2D6x1,000 credits as labor, warriors and gladiators.', 'The Old Man of the Swamp: a shy reptilian humanoid with the mind of a young child. Gentle despite its looks, it rescues lost children and pets, but it also raids camps for food and shiny things and has no notion of law or property. This entry is a reprint; the race first appeared in Rifts Sourcebook Four: Coalition Navy.', 'Rifts World Book 30: D-Bees of North America p.200-201'),
('vernulian', 'Vernulian', 'alien', 'rifts', 1, 'Any. Military Vernulians lean toward Unprincipled (5%), Anarchist (25%), Aberrant (35%), Miscreant (20%) and Diabolic (10%); refugees toward Scrupulous (15%), Unprincipled (35%) and Anarchist (30%)', '{"IQ":"3D6","ME":"4D6","MA":"4D6","PS":"4D6","PP":"4D6","PE":"4D6","PB":"1D6","Spd":"4D6"}', NULL, NULL, '1D6x10+PE', '6D6', '1D6x10+ME', 'Main body M.D.C. is 1D6x10 plus the P.E. number, and 1D4 per level of experience; each of the four tentacles has 2D6+10 M.D.C. I.S.P. is 1D6x10 plus M.E., and 1D6+1 per level. P.S. is Augmented. Soldiers wear a force field collar of 160 M.D.C.; only 30% of refugees have one, of 100 M.D.C. Either regains 10 M.D.C. an hour and runs 12 hours a day at most or it shuts down for 24 hours. Tentacles and tail heal 2D6 M.D. per 24 hours and regrow in 1D4+3 weeks. Walking upright is half Spd; slithering is full Spd.', NULL, 14, NULL, 'TWO FACTIONS, so no combat figures are stored; use one line, in addition to attributes and skills. Military: +3 attacks per melee round, +1 strike, +4 parry, +3 automatic dodge (costs no attack), +4 entangle, +2 disarm, +4 pull punch, +2 to save vs Horror Factor, +2 to save vs poison. Refugees: +2 attacks per melee round, +1 Perception Rolls, +2 parry, +2 dodge (not automatic), +2 entangle, +2 to save vs poison. Attacks as per Hand to Hand skill and bonuses; damage as per P.S., weapon or psionics. Special Entangle: pins one foe with two arms while striking with the other two; it may parry or strike another foe at half bonuses, and a dodge frees the victim. An escape attempt costs the victim two attacks and the Vernulian one, D20 each, bonuses for the Vernulian only, high roll wins. Vulnerabilities: cannot disguise itself and is taken for a demon or monster on sight; -10% on complicated devices built for humanoids.', 'Whatever the O.C.C.: Climbing (+30%), Swimming (+25%), Prowl (+20%), W.P. Paired Weapons, and one new spoken language every level of experience at +25%.', 'Flawless color vision for life. Swims on or under the surface, staying down two minutes per point of P.E. and as deep as 600 feet (183 m). Four strong tentacle arms, each as long as half the body, handle fine work and machinery (less deftly than fingers), and their suckers carry it up sheer or slick surfaces such as glass and ice or through any tree that bears its weight. Its low, snaking body suits stalking and ambush and fits through a hole 9 inches (23 cm) across. Its own weapons fire by Telekinesis through hidden triggers, and Telekinesis also works human guns and computers.', 'None, except by O.C.C. (rare; refugees only)', 'Major Psychic. Telepathy (4), Telekinesis (varies) and Mind Block (4), plus four more powers from the Healing, Sensitive and/or Physical categories.', '2D6+8 feet (3 to 6.1 m) long; rears up to three quarters of body length', '3D4x100 pounds (135 to 540 kg)', '3D8+76 years; mature by age 10; 1D6 live young after a 12 month pregnancy', 'As of 109 P.A. mostly northern Mexico and the American Southwest, but anywhere in the Americas', 'None as such; refugees try to accept all peoples and wish to live in peace, and despise slavers and tyrants', 'Soldiers treat all Earthlings and intelligent mammals as enemy and prey, and other reptilian peoples as rivals. Termination squads hunt the refugees.', 'In theory any O.C.C. Military characters practice no magic and match most Men at Arms classes other than Juicer, Crazy, Glitter Boy and Cyber-Knight (20% are full conversion cyborgs). Refugees can be anything, most often Adventurer and Scholar classes, and only they take up magic, rarely. NPC level: military 2D4+1, refugees 1D8; player characters begin at first level. Equipment and money as per O.C.C. Military gear includes Serpent Power Armor (head 100, four tentacles 100 each, main body 300, six underside hover jets 25 each, two main jets 75 each; flies 400 mph (640 km) up to 300 feet (91 m)) and Serpent Borg full conversions (P.S. 30, P.P. 26, Spd 50, 300 M.D.C. armor, Vibro-Sword or Vibro-Claws 3D6 M.D.). Slave market value 2D4x10,000 credits.', 'Serpent People: giant snakes with four suckered octopus arms, a salamander-like head and unsettlingly human eyes and teeth, known in Mexico as the Children of Cihuacoatl. Two factions reached Rifts Earth: ruthless Special Forces scouts who prey on mammals and prepare an invasion, and political refugees, most of them peaceful. This entry is a reprint; the race first appeared in Rifts World Book One: Vampire Kingdoms.', 'Rifts World Book 30: D-Bees of North America p.210-212'),
('vintex-warrior', 'Vintex Warrior', 'humanoid', 'rifts', 1, 'Any, but lean toward Scrupulous (25%), Unprincipled (30%), Anarchist (15%) and Aberrant (15%)', '{"IQ":"2D6+3","ME":"2D6+3","MA":"2D6+3","PS":"3D6+11","PP":"2D6+9","PE":"2D6+7","PB":"2D6","Spd":"3D6+13"}', NULL, NULL, '6D6+PE+2D6', '2D6+5', NULL, 'M.D.C. is 6D6 plus the P.E. number, and an additional 2D6 per level of experience starting at level one; the stored formula is the level one figure (6D6 + P.E. + 2D6). Often wears partial or full armor on top; issue armor is 4D6+40 M.D.C. with the tail left bare. P.S. is Augmented. Average Spd is 22 (15 mph/24 km). Bio-regenerates 2D6 M.D.C. every 24 hours.', NULL, NULL, '{"attacks":1,"initiative":1,"strike":3,"parry":1,"dodge":1,"disarm":3,"entangle":1,"pull_punch":4,"roll":1}', 'In addition to attributes and skills: +1 attack per melee round, +1 initiative, +3 strike, +1 parry and dodge, +3 disarm, +1 entangle, +4 pull punch, +1 roll with impact, +3 to save vs Horror Factor, impervious to most diseases. Tail: +10% to balance, +2 strike and +1 parry with it; -3 to strike if it wields a weapon. Attacks as per Hand to Hand and Boxing; damage as per Augmented P.S., combat skill or weapon. Horror Factor: not applicable. Vulnerabilities: none as such, beyond an obsession with war.', 'R.C.C. skills: Acrobatics, Boxing, Combat Driving, Language: Native (+4%; American), Literacy: Native Language (+10%), Climbing (+15%), Land Navigation (+10%), Math: Basic (+12%), Military Etiquette (+20%), Pilot: one vehicle of choice (+12%), Radio: Basic (+15%), Rope Works (15%), Sign Language (+10%), Swimming (+15%), W.P. Ancient: three of choice, W.P. Modern: two of choice, W.P. Rope, W.P. Targeting, Hand to Hand: Martial Arts or Commando. Area of Specialty: five skills at +15%, all from ONE of Communications, Cowboy, Domestic, Electrical (with Computer Operation), Espionage, Horsemanship, Mechanical, Medical, Military, Pilot (no Submersible, Tanks, Robot or Power Armor skills), Rogue, Science, Technical, W.P. or Wilderness; Physical and Pilot Related: none. Secondary skills: two at each of levels 1, 3, 5, 7, 9 and 11.', 'A Mega-Damage hide over Augmented muscle, with fast reflexes and sharp senses; a severed tail grows back in half a year. The prehensile tail can lift and carry things but cannot shoot, and serves for balance, hanging, swimming and clubbing anyone behind or beside the Vintex; males'' tails end in spikes and only theirs can hit for Mega-Damage. Superior Aim: shoots with no penalty while running, leaping, dangling head down or riding a moving vehicle.', 'None', 'None', '6-7 feet (1.8 to 2.1 m) tall', '200-250 pounds (90 to 112.5 kg)', '6D6+99 years; physically mature by 15', 'Throughout North America wherever there is a battle or war; an estimated 300,000 to 400,000, with at least 30,000 in the Pecos Empire, 100,000 across the New West and 100,000 across western Canada, met alone, as merc squads or in clans of 5D6+30', 'Other warriors, especially Psi-Stalkers, Malvoren, Squilbs, Blucies and Rogue Dog Boys; respects Cyber-Knights and Lynn-Srial; admires Body Fixers, Operators and Rogue Scientists, and reveres Rogue Scholars, historians, artists and thinkers (Erin Tarn above all)', 'Demons and other supernatural beings, Worm Wraiths and vampires first; not fond of creatures of magic or psychics. Sees Simvan, Brodkil, Xiticix, Witch Wolves and Deer Horn as savages, and Loaks, Vernulians, Gankas, Forest Wardens, Chasseur Vert, Drizzit, Spinne and the Minions of Splugorth as dangerous aliens. Regards the CS and Free Quebec without fear or hatred.', 'Takes no O.C.C.: whatever trade it follows (assassin, bounty hunter, gunslinger, lawman, mercenary, soldier, spy), every Vintex has the R.C.C. skills and one Area of Specialty, and uses the Military Specialist experience table. NPCs are level 2D4+1; player characters begin at first level. Starts with medium or non-environmental armor (4D6+40 M.D.C.), clothing, leather boots and gloves, one weapon per W.P. with 1D6+3 E-Clips each, backpack, satchel, bedroll, two canteens, chalk, spray paint, notebook and pens, pocket mirror, wooden cross, language translator, and 1D6x1,000 credits of trade goods. Open to cybernetics, chiefly to replace a lost limb. Slave market value 1D4x10,000 credits.', 'The Dark Age Hunters or Iron Skin Soldiers: tailed, lipless humanoids with yellow-orange hide blotched black or dark red and wiry black hair streaked silver. They descend from a genetically engineered invasion army stranded on Earth early in the Dark Age and still live by military order as mercenaries, lawmen and monster slayers, while quietly admiring the artists and thinkers they can never be.', 'Rifts World Book 30: D-Bees of North America p.213-215'),
('tokanii', 'Tokanii', 'humanoid', 'rifts', 1, 'Any, but most are Anarchist or evil; only the Ronii tribe runs about 10% Scrupulous, 28% Unprincipled, 20% Anarchist, 22% Aberrant and the rest other evil alignments', '{"IQ":"2D6+3","ME":"3D6","MA":"2D6+3","PS":"4D6","PP":"3D6+3","PE":"4D6+3","PB":"2D4","Spd":"3D6+6"}', NULL, NULL, 'PEx3', '4D6', NULL, 'M.D.C. is the P.E. number x3, +4D6 M.D.C. per level of experience, and +10 M.D.C. for every 20 years of age; the stored formula is the P.E. x3 base only. The bone exoskeleton holds most of it (printed as 90% on the Mega-Damage line and as 80% under Bone Regeneration). Roughly 10 M.D.C. per foot, 28 per hand and 20 per claw. P.S. and P.E. are Supernatural; P.B. 2D4 is by human standards. No I.S.P. is printed.', NULL, 13, '{"attacks":1,"initiative":1,"strike":2,"parry":2,"roll":2,"pull_punch":2}', '+1 attack per melee round, +3 to save vs poison and drugs, +3 to save vs disease, +8 to save vs Horror Factor; resistant to fire and heat (half damage, M.D. fire included). All in addition to attribute and skill bonuses. Attacks per melee as per Hand to Hand; damage as per Supernatural P.S. or weapon. A power claw strike doubles the damage and uses two attacks. Experience level 1D8 for NPCs. Vulnerabilities: a demonic look and an arrogance that makes them underrate opponents, technology and magic.', 'Tokanii Warrior R.C.C. skills: Barter (+10%), Language: Native Tongue: Tokanii, Language: Other: American or Spanish (+20%), Identify Plants & Fruits (+15%), Land Navigation (+15%), Radio: Basic (+10%), Recognize Weapon Quality (+20%), Running, Swim (+10%), Skin & Prepare Animal Hides (+15%), Track Animals (+15%), Wilderness Survival (+20%), W.P. Blunt, W.P. Energy Rifle, three W.P.s of choice, Hand to Hand: Expert (cannot be changed). Climb 95%/90% as a natural ability. Ronii only: Horsemanship and Horsemanship: Exotic Animals (+30% each), and may pick from Communications, Military, Piloting and Rogue. Four R.C.C. Related Skills at level one, plus one at levels 2, 5, 8 and 12; three Secondary Skills at level one, plus one at levels 2, 4, 8 and 12.', 'Supernatural Strength, a Mega-Damage shell of bone plates, nightvision to 300 feet (91.5 m), color vision as sharp as a hawk''s, and climbing at 95%/90%. Broken or damaged horn and bone grows back at 2D6+4 M.D.C. a day. The hands and feet are the only unarmored parts; a lost one regrows completely in 1D4+2 weeks. Retractable claws on the fingers and the three toes.', 'Typically none. Among the Kreenae and Tokae only the shamans (in effect Mystics) have magic; only Ronii may take a magic O.C.C.', 'Same chance of being psychic as humans', '7-9 feet (2.1 to 2.7 m)', '350-550 lbs (158 to 248 kg)', '1D6x10+180 years; mature at 20, females bear 1D4 young after an 18 month pregnancy, no more often than every eight years, until age 90', 'Mainly Lone Star and the Southwest. Tokae (27,500 in 24 clans) keep to the eastern forests of Texas, Louisiana and Arkansas; Kreenae (23,100 in 21 clans) to the southern forests toward the Gulf Coast and lower Louisiana; Ronii (16,700 in seven clans) to the plains and prairies', 'Primarily other Tokanii; most ride with the Pecos Raiders and other Texas bandits and accept known desperados and anyone a known bandit vouches for. The Ronii tribe and the Pervic Simvan are true allies of each other', 'The Coalition Army above all others; rival clans will even stop fighting each other to join a battle against it. Suspicious of outsiders and other races in general', 'The Tokanii Warrior R.C.C. is the default and for Tokae and Kreenae the only choice. Ronii tribesmen alone may instead take one of three kinds of O.C.C.: Men at Arms (any), the Wilderness Scout, and Practitioners of Magic (any; under 1% have). Player characters start at level one. Warriors start with one weapon per W.P., 1D4+2 E-Clips, a Vibro-Sword (2D6 M.D.), 1D6x100 credits and 2D6x1,000 in trade goods; Ronii add a horse or exotic mount. They never wear armor and refuse cybernetics and bionics. Slave market value 3D6x10,000 credits.', 'Horned D-Bees who look like black-skinned demons cased in tan to gray bone, with a black mane, long exposed teeth and arms and hands far too big for the body. Refugees from a jungle world wrecked by an asteroid, they came through a Rift into Lone Star 56 years ago, about 10,000 surviving a Coalition massacre, and now live as three clan-ruled tribes of raiders in and around the Pecos Empire: the Tokae, the merciless Kreenae and the more open Ronii.', 'Rifts World Book 30: D-Bees of North America p.203-206'),
('simvan-monster-rider', 'Simvan Monster Rider', 'humanoid', 'rifts', 1, 'Any, but the majority are Anarchist (30%), Aberrant (30%) and Miscreant (20%)', '{"IQ":"3D6","ME":"4D6","MA":"2D6","PS":"4D6","PP":"4D6","PE":"5D6","PB":"2D6","Spd":"4D6"}', '1D4x10', '2D6x10', NULL, NULL, NULL, 'P.P.E. and I.S.P. differ by sex, so neither is stored as a formula. P.P.E.: males 4D4, females 4D6. I.S.P.: females 4D4x10 plus the M.E. number, males 2D4x10 plus the M.E. number. No per-level gain is printed for Hit Points or I.S.P. M.D.C. by armor only.', NULL, 12, '{"initiative":1,"strike":1,"parry":1,"dodge":1,"roll":1,"pull_punch":2}', '+1 on Perception Rolls, +2 to save vs Horror Factor, +2 to save vs spoiled meat/food. Attacks per melee as per Hand to Hand; damage as per P.S., psionics, weapon or the animal under the rider''s control. Experience level 1D8 for NPCs, on the Psi-Stalker experience table. Vulnerabilities: an aggressive nature and a diet of people cause trouble.', 'MALES: all Wilderness skills (+20% each), Wilderness Survival (+30%), Athletics (General), Body Building, Climbing (+10%), Dance (+10%), Hand to Hand: Expert or Assassin (pick one), Horsemanship: Cowboy (+10%), Horsemanship: Exotic Animals (+30%), Math: Basic (+20%), three Physical skills of choice, Recognize Weapon Quality (+10%), Running, Sing (+10%), Track (people; +20%), W.P. Archery, W.P. Targeting, W.P. Knife, W.P. Energy Rifle, three W.P.s of choice. FEMALES: all Domestic skills (+30% each) and all Wilderness skills (+10%), Animal Husbandry (+20%), Breed Dogs (+20%), Brewing (+10%), Brewing: Medicinal (+15%), Cook (+10%), Dance (+10%), Holistic Medicine (+20%), Hand to Hand: Basic, Horsemanship: General (+10%), Horsemanship: Exotic Animals (+20%), Running, two Physical skills of choice, Sing (+15%), Veterinary Science (+15%), W.P. Blunt, W.P. Knife, two W.P.s of choice. EITHER SEX: five R.C.C. Related Skills from a restricted list (only females may take Medical); two Secondary Skills at each of levels 2, 4, 8 and 10.', 'Keen eyesight and nightvision to 120 feet (36.5 m). Males have a no-cost empathy with animals: tame beasts obey them, any horse or other animal can be ridden as if with Horsemanship: General +15%, and wild animals and predators (alien animals of human intelligence excepted) ignore them, so nothing gives away their approach. A wild predator, dinosaur or monster becomes a mount if the rider stays on its back for one melee round: 1 I.S.P., then roll 1D20 for each of the rider''s attacks that melee, parry bonuses added; 1-6 throws him off, 7 or more holds. Once broken it obeys any Simvan, to the death, yet stays dangerous to everyone else.', 'None', 'Females (healers): Deaden Pain (4), Detect Psionics (6), Exorcism (10), Healing Touch (6), Increase Healing (10), Psychic Diagnosis (4), Psychic Surgery (8), plus one Healing power of choice at levels 1, 3, 6, 9 and 12. Males: Empathy (4), Mind Block (4), Mind Bond (10), Sixth Sense (2), Telepathy (4), plus the animal empathy under natural abilities.', '5 feet, 7 inches (1.7 m) to six feet (1.8 m)', '150 to 200 pounds (67 to 90 kg)', '3D6+44 years; mature at 16, one young (two on 01-30%) after an eight month pregnancy', 'Plains and deserts of the American West, parts of Northern Mexico and around Calgary, in nomadic tribes of 1D4x100 to 4D6x100; in the Pecos Empire mostly the Lone Star high plains, The Bend and the Rio Grande Plain', 'Other Simvan tribes, the Ronii Tokanii, Tokanii and Pecos bandits in general; they welcome intelligent mutant animals, Were-Beasts and any animal-like D-Bee', 'Psi-Stalkers (a growing feud, worst in the Pecos Empire) and the Coalition Army; other peoples are anything from trade partners to prey', 'No O.C.C. is available: the R.C.C. is the whole character, with separate skill and psionic lists for males and females. Player characters start at level one and advance on the Psi-Stalker table. Starts with a Vibro-Knife (1D6 M.D.), one weapon per W.P., 1D4+1 E-Clips per energy weapon, 2D6+10 arrows and 1D6+2 M.D. arrows, light or medium M.D. body armor, a horse, Ostrosaurus or Silonar to ride, 1D4x100 credits and 2D6x1,000 in trade goods. Avoids cybernetics and bionics. Slave market value 3D6x1,000 credits.', 'Furred, tribal D-Bee nomads out of the Calgary Rift who eat humanoids by preference and honor their own dead the same way. Gentle and loyal among themselves and hostile to nearly everyone else, they fight as fast cavalry on tamed predators, the Ostrosaurus above all. Men hunt and fight; women run the camp and are the tribe''s psychic healers.', 'Rifts World Book 30: D-Bees of North America p.188-190'),
('psi-x-alien', 'Psi-X Alien', 'humanoid', 'rifts', 1, 'Any, but tending to extremes: Principled (30%), Diabolic (30%), Aberrant (17%), Anarchist (17%)', '{"IQ":"3D6+6","ME":"3D6","MA":"2D6","PS":"2D4+4","PP":"2D4+4","PE":"2D4+1","PB":"2D4+2","Spd":"2D6+4"}', 'PEx2', '2D6+2', NULL, 'PEx10', NULL, 'Hit Points are the P.E. number x2, +1D6 per level of experience. M.D.C. only through body armor, force fields or psionics. I.S.P. is rolled on a percentile table (p.168), so no formula is stored: 01-20 M.E. x10, +8 per level; 21-40 M.E. x5, +2D6 per level; 41-60 M.E. x2, +12 per level; 61-80 M.E. x3, +1D6 per level; 81-00 the M.E. number only, +4D6 per level. M.A. is +2 for a good alignment. I.Q. is narrow: see skills.', NULL, NULL, NULL, '+5 to save vs Horror Factor and +5 to save vs magic illusions, in addition to attribute and skill bonuses. Attacks per melee: one physical action or attack at levels 1, 2, 4, 8 and 12, or two psionic actions/attacks at levels 1, 3, 6, 10 and 15. Experience level 1D10 for NPCs, on the Mind Melter table. Vulnerabilities: day vision of only 40 feet (12 m), and eyes that are blinded by sunlight or any bright light unless covered by tinted protection; ley lines raise confidence, aggression and baser emotions along with the powers. Insanity: three phobias and one obsession.', 'R.C.C. skills: two languages of choice at 98%, plus ALL the skills of ONE chosen category at +20%: Communications, Electrical, Mechanical, Medical, Pilot Related, Rogue, Science, Technical Studies (all Computer, History, Law, Lore, Myth and Research skills, with Computer Hacking from Rogue) or Technical Applications (every other Technical skill). R.C.C. Related Skills: none. Four Secondary Skills at level one, plus one at levels 3, 5, 9 and 11.', 'Nightvision to 3000 feet (914 m) with a hawk''s color vision; sees infrared, ultraviolet and electromagnetic energy, and sees the invisible automatically (Astral beings, Entities and energy beings included). Hovers 1-4 feet (0.3 to 1.2 m) off the ground at its Spd as its normal way of moving, at no I.S.P. cost; walking takes concentration.', 'None', 'All (p.168): See Aura (6), Sense Magic (3), Detect Psionics (6), Bio-Regeneration (6) and the free telekinetic hover. Plus one package by percentile roll: 01-12 Kineticist; 13-24 Psychic Sensitive; 25-37 Psychic Energy Conduit; 38-49 Psychic Intuitive; 50-61 Psychic Spiritualist; 62-73 Psychic Manipulator; 74-85 Healer; 86-97 Closed Mind; 98-00 Mind Melter (powers as that O.C.C.). I.S.P. by a second percentile roll: see pools note.', '4 to 5.6 feet (1.2 to 1.7 m)', '90 to 130 lbs (40.5 to 58.5 kg)', '1D6x10+170 years; mature around 20, one young after a nine month pregnancy, fertile until 90', 'Mostly still in the Coalition States of Lone Star, El Dorado and Chi-Town; some have joined the Pecos Empire or Arzno, and individuals turn up anywhere', 'None per se; drawn to other outcasts and to those who share their alignment, and they look down on most people''s intellect', 'Other psychics (rivals and threats); dislikes and distrusts slavers, shape-changers, Cyber-Docs, Gene-Splicers and scientists who dabble in genetics', 'No O.C.C. is available; the R.C.C. is the whole character, though the chosen skill category can earn a living as a doctor, mechanic, electrician, researcher and the like. Player characters start at level one and advance on the Mind Melter table. May wear light armor. Starts with a survival knife, one energy weapon of choice with 1D4 extra E-Clips, protective eye goggles, a universal translator, a portable tool kit and 3D6x100 credits. Slave market value 1D4x10,000 credits.', 'Not D-Bees at all but humans: Pecos Empire teenagers kidnapped and genetically altered in Desmond Bradford''s illegal psionics experiments at the Lone Star Complex, labelled aliens to hide the fact, and over 150 of them quietly turned loose in the Pecos Badlands about 30 years ago. Tall, frail, hairless and chalk-pale, with huge dark eyes and a cranium two or three times human size. Powerful but erratic psychics, brilliant in one field and blank in others, solitary and prone to addiction; the second generation believes it truly is alien.', 'Rifts World Book 30: D-Bees of North America p.166-168');
INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'amana', 'Touch of Life (touch)', '1D4 Hit Points', 0, 'Touch', 'Harms the undead only. Against animated dead and other dead or undead beings with M.D.C. it is 1D4 M.D.', 0),
('creature', 'amana', 'Touch of Life (punch)', '3D4 Hit Points', 0, 'Touch', 'A punch or laying on of hands, against the undead only. Against animated dead and other dead or undead beings with M.D.C. it is 3D4 M.D.', 1),
('creature', 'arac', 'Venomous Bite', '1D4 S.D.C.', 0, NULL, 'A hit injects toxin: the victim saves vs poison at 14 or higher. Saved, 1D6 S.D.C. more. Failed, 4D6 S.D.C. more, and for 2D4 hours -3 to strike, parry and dodge, -15% on skills and half speed. Toxic to mammals, birds and reptiles.', 0),
